"""SPEC-FIRE LIVE (Stage B, 24.07): боевые пробы-ликвидации по ЖИРНЫМ целям в последние
секунды predict-окна — попытка взять предочередь (11% призов, победители-спекулянты idx+2).

Гейт снят данными (см. STATE 24.07): бэктест каскада 24-25.06 (87% ликвидаций при армленном
окне, lead med 67с) + live spec-canary DELTA=4/3 (предочередь достижима). Дизайн:
- ОКНО: arm-событие с целями >= SPEC_FIRE_MIN_REPAID_USD ($1000 — боевое значение; ранний
  Stage B стартовал с $500k «только жир», порог давно снижен env'ом, дефолт-призрак $500k
  убран 19.08 по слову kelbic: потеря строки env не должна молча закрывать почти всё поле).
- ОГОНЬ: только когда |ret| >= dev × SPEC_FIRE_THRESHOLD (1.0) — транзит неминуем в секундах
  (оракул триггерится на dev); до порога НЕ стреляем (там lead минуты — пробы в пустоту).
- ПРОБА: настоящий liquidate-calldata top-1 жирной цели: полный repaid, своп из PREARM-кэша
  (мега: Kyber-агрегат, обрыв пула) либо direct-роут (0 RTT); minProfit-floor аналитический
  (SPEC_FIRE_MIN_PROFIT_BPS от repaid) — контракт ревертит плохой филл. До флипа Morpho
  ревертит 'healthy' (~$0.01-0.02); проба в блоке транзита ПОСЛЕ него = WIN полным призом.
- БЕЗОПАСНОСТЬ: send через send_spec_fire_probe (канареечная nonce-машинерия под общим
  _SEND_LOCK; _INFLIGHT>0 -> пробы молчат — боевая tx главнее); пробы НЕ трогают
  _RECENT_SENDS (не глушат реактивный выстрел); WIN маркирует дедуп отдельно; свой
  газ-бакет SPEC_FIRE_MAX_GAS_USD; капы проб на окно; receipts собираются фоном
  (kill-switch-слепоты к газу нет — газ букается в бакет по receipt).
"""
from __future__ import annotations

import logging
import os
import random
import threading
import time

from chain.spec_fire import _label_of

log = logging.getLogger("liq.spec_fire_live")
# Лок пофидового учёта позиций (р-5, майор C). МОДУЛЬНЫЙ: счётчики трогает тред коллектора
# (по исходу пробы) и тред окна (снимок на арме / дельта в закрывающей строке), а сам учёт —
# измерительный, ронять из-за него денежный путь нельзя.
_PROBE_FEED_LOCK = threading.Lock()

# Дефекты кода, которые бой не переживёт НИКОГДА: их нельзя показывать как осечку связи.
_CODE_BUGS = (NameError, AttributeError, TypeError, ImportError, KeyError, IndexError)


def _diag(e) -> str:
    """Класс исключения + его текст (отредактированный от ключей).

    Голый type(e).__name__ прятал арм доски пять суток: строка «доска arm fail: NameError»
    читается как операционная осечка, из-за которой залп разумно откатился на V1, — а на деле
    это была необъявленная переменная, то есть путь не мог сработать ни разу и ни у кого.
    """
    from chain.rpc import redact
    tag = " ДЕФЕКТ КОДА" if isinstance(e, _CODE_BUGS) else ""
    return "%s%s: %s" % (type(e).__name__, tag, redact(e)[:200])

# ПОРОГ КАНДИДАТА — ПЕР-РЫНОЧНЫЙ (#138, 20.08). Плоское число здесь неверно ПО ПОСТРОЕНИЮ:
# в тракте доски нет ни одного долларового пола прибыли (SPEC_FIRE_FAT_PRIZE_USD=0,
# min_profit_usd не используется), то есть MIN_REPAID — ЕДИНСТВЕННЫЙ экономический гейт, и он
# обязан считаться от БЕЗУБЫТКА СВОЕГО РЫНКА: приз = долг × бонус, значит порог = цена окна /
# бонус. На карте это разброс в 12 раз:
#     12.68% -> $17.7 | 4.38% -> $51 | 2.62% -> $86 | 1.68% -> $134 | 1.06% -> $212
# Плоские $50 на половине карты стоят ниже безубытка ДАЖЕ ПРИ p=1.
# Замер #138 (30 суток, analysis/liq_class_histogram.py) даёт вторую половину ответа: класса
# $50k+ на покрытых рынках нет вовсе, весь поток в $1k-50k, а бакет $0-50 — это 1487 позиций
# ради $225/мес (в 50 раз хуже соседнего по выходу на кандидата). Отсюда пол $50 у самых
# жирнобонусных рынков и отказ опускаться ниже.
SPEC_FIRE_MIN_REPAID_USD = float(os.environ.get("SPEC_FIRE_MIN_REPAID_USD", "50"))
# Цена ОДНОГО окна подготовки (замер: кап 150 проб × ~$0.015 главного кошелька).
SPEC_FIRE_WINDOW_COST_USD = float(os.environ.get("SPEC_FIRE_WINDOW_COST_USD", "2.25"))
# Бонус рынка НЕИЗВЕСТЕН -> безубыток не посчитать -> держим ПРЕЖНИЙ порог. Незнание бонуса не
# имеет права открывать мелочь: это ровно тот класс, где ошибка стоит дороже пропуска.
SPEC_FIRE_MIN_REPAID_NOBONUS_USD = float(os.environ.get("SPEC_FIRE_MIN_REPAID_NOBONUS_USD", "1000"))

# #140: ПОСЕВ СКЛАДА НА СТАРТЕ. Дефолт включён; откат SPEC_FIRE_SEED_ON_START=0 возвращает
# прежний подъём движка (только из окна/арма) бит-в-бит.
SPEC_FIRE_SEED_ON_START = os.environ.get("SPEC_FIRE_SEED_ON_START", "1").lower() not in (
    "0", "false", "no")
# ПОЧЕМУ НЕ НА t=0. Старт идёт под 429-штормом прогрева кэшей, и подпись 4400 ECDSA на общем
# ядре в тот же момент — это эффект наблюдателя, которым мы уже платили (канон одноядерной VPS).
# Сеем ПОСЛЕ первого УСПЕШНОГО candidate refresh: к этому моменту прогрев кэшей позади, а до
# первого окна spec-fire ещё часы.
# ДВА УСЛОВИЯ СХОДЯТСЯ В ЛЮБОМ ПОРЯДКЕ: refresh-воркер стартует РАНЬШЕ, чем создаётся
# SpecFireLive, поэтому «кандидаты готовы» и «есть кого сеять» приходят порознь, и посев
# запускает тот, кто пришёл вторым. Одноразово (`done`).
_SEED_LOCK = threading.Lock()
_SEED_STATE = {"hook": None, "ready": False, "done": False}


def set_seed_hook(fn) -> None:
    """Точка, куда main отдаёт сеятеля (метод живого SpecFireLive). Арм ЯВНЫЙ, канон notify_fn."""
    with _SEED_LOCK:
        _SEED_STATE["hook"] = fn
    _maybe_seed()


def note_candidates_ready() -> None:
    """Первый успешный candidate refresh состоялся (зовёт refresh-воркер main)."""
    with _SEED_LOCK:
        if _SEED_STATE["ready"]:
            return
        _SEED_STATE["ready"] = True
    _maybe_seed()


def _maybe_seed() -> bool:
    """Оба условия сошлись -> посев В ФОНЕ (тред), чтобы не задерживать ни refresh-воркер, ни
    старт. Прибор сбоку: исключение сеятеля не выходит за этот тред."""
    with _SEED_LOCK:
        if _SEED_STATE["done"] or not _SEED_STATE["ready"] or _SEED_STATE["hook"] is None:
            return False
        _SEED_STATE["done"] = True
        fn = _SEED_STATE["hook"]

    def _run():
        try:
            fn()
        except Exception:                         # noqa: BLE001
            log.info("SPECFIRE посев склада: сеятель упал — старт не затронут")

    threading.Thread(target=_run, daemon=True, name="spec-seed").start()
    return True


def _market_min_repaid_usd(bonus) -> float:
    """Порог кандидата ДЛЯ ЭТОГО РЫНКА = max(пол, цена окна / бонус). bonus — доля (LIF−1),
    как её отдаёт covered-снапшот (`_bonus_of`); 0/None = неизвестен -> прежний порог."""
    try:
        b = float(bonus or 0.0)
    except (TypeError, ValueError):
        b = 0.0
    if b <= 0.0:
        # НИКОГДА не ослабляем явно поднятый пол: если владелец поставил MIN_REPAID выше
        # «прежнего порога», незнание бонуса обязано оставить ЕГО, а не откатить к $1000.
        return max(SPEC_FIRE_MIN_REPAID_USD, SPEC_FIRE_MIN_REPAID_NOBONUS_USD)
    return max(SPEC_FIRE_MIN_REPAID_USD, SPEC_FIRE_WINDOW_COST_USD / b)
SPEC_FIRE_INTERVAL_SEC = float(os.environ.get("SPEC_FIRE_INTERVAL_SEC", "0.7"))
# ПЛОТНЫЙ РЕЖИМ (31.07: первая боевая гонка cbBTC 14:07 проиграна ДЕНЬГАМИ — победитель сидел
# в предочереди блока транзита idx 2928 с tip 0.0034, наша реакция 106мс легла блоком позже с
# tip 30): в FCFS решает не скорость и не tip, а присутствие пробы в очереди МЕЖДУ транзитом и
# спамом конкурента. Это гонка плотностей: P(win) ~ наш темп / (наш + конкурента). Хвост 2.0с
# давал ~1 пробу на блок со случайной фазой — флип 14:07 упал между пробами. Плотный режим:
# вся горячая фаза (|ret| >= порога) на DENSE_INTERVAL 0.5с (4 пробы/блок; пол send-слоя
# SPEC_FIRE_MIN_INTERVAL_SEC=0.25 совместим), джиттер ±0.15 ломает подпись расписания.
# Выравнивание фазы по границе 2с-блока НЕ строим: flashblocks каждые 200мс делают границу
# бессмысленной — окно очереди скользящее, место покупает только плотность.
# Откат без кода: SPEC_FIRE_DENSE=0 -> прежний burst/slow-каденс и кап 24.
SPEC_FIRE_DENSE = os.environ.get("SPEC_FIRE_DENSE", "1").lower() not in ("0", "false", "no")
SPEC_FIRE_DENSE_INTERVAL_SEC = float(os.environ.get("SPEC_FIRE_DENSE_INTERVAL_SEC", "0.5"))
SPEC_FIRE_DENSE_JITTER_SEC = float(os.environ.get("SPEC_FIRE_DENSE_JITTER_SEC", "0.15"))
# Кап окна в плотном режиме: 150 × 0.5с = 75с покрытия >= p75 «первая проба -> транзит» жирных
# окон (64с, датасет 27.07). Цена худшего окна 150×$0.015 ~= $2.25 — суточный бакет $10 держит
# 4+ полных окна, WIN-cooldown (900с) рвёт серию раньше; окно и так стопится на confirmed/disarm.
SPEC_FIRE_MAX_PROBES_WINDOW = int(os.environ.get("SPEC_FIRE_MAX_PROBES_WINDOW")
                                  or (150 if SPEC_FIRE_DENSE else 24))
# EV-ПЛОТНОСТЬ (06.08, «го» kelbic; вскрытие $65.6k cbBTC 27.07): победитель держал 10-17
# проб/блок против наших 4 и взял приз $2,879 пробой idx+8 после транзита; наша реакция
# (детект суб-блочно, send 510мс) легла ревертом −$6.55 — реакция не бьёт предочередь,
# место покупает только плотность. Плотность = функция размера добычи: жирная цель
# (долг >= FAT_DEBT_USD) в досягаемости тика переключает каденс DENSE 0.5с -> 0.12с
# (квант петли SPEC_FIRE_POLL_SEC=0.15 даёт ~13 проб/блок — паритет с лучшим замеренным
# конкурентом) и кап окна 150 -> 600 (~90с горячей фазы). Худшее жирное окно 600×$0.015
# ~= $9 против приза >=$1.5k при долге $50k. Сопряжённо: пол send-слоя 0.25 -> 0.10 и
# бакет 20 -> 40 (execute.py). Откат: SPEC_FIRE_EV_DENSITY=0 (см. docs/ROLLBACKS.md).
SPEC_FIRE_EV_DENSITY = os.environ.get("SPEC_FIRE_EV_DENSITY", "1").lower() not in ("0", "false", "no")
SPEC_FIRE_FAT_DEBT_USD = float(os.environ.get("SPEC_FIRE_FAT_DEBT_USD", "50000"))
SPEC_FIRE_FAT_INTERVAL_SEC = float(os.environ.get("SPEC_FIRE_FAT_INTERVAL_SEC", "0.12"))
SPEC_FIRE_FAT_JITTER_SEC = float(os.environ.get("SPEC_FIRE_FAT_JITTER_SEC", "0.04"))
SPEC_FIRE_FAT_CAP = int(os.environ.get("SPEC_FIRE_FAT_CAP", "600"))
# ГЕЙТ ЖИРА ПО ПРИЗУ («го» kelbic 07.08; CASCADE_TIER_DESIGN, экономика 180д): окупаемость
# плотности определяет ПРИЗ = долг × бонус, а FAT_DEBT меряет долг. $50k долга на cbBTC
# (LIF 4.39%) = приз $2.2k — кромка окупаемости, а на 12.68%-рынках (cbXRP/AERO/stkWELL)
# окупаемость начинается уже с долга ~$16k — такие окна мы не уплотняли. PRIZE_USD > 0 =
# гейт по призу (bonus рынка из covered-снапшота); рынок без бонуса -> фолбэк на долг-гейт
# (fail-open к прежнему). 0 = прежний долг-гейт бит-в-бит. Откат: убрать из .env.
SPEC_FIRE_FAT_PRIZE_USD = float(os.environ.get("SPEC_FIRE_FAT_PRIZE_USD", "0"))


def _tgts_fat(tgts, bonus_of=None) -> bool:
    """Жир в досягаемости тика -> EV-каденс/кап окна."""
    if not SPEC_FIRE_EV_DENSITY:
        return False
    if SPEC_FIRE_FAT_PRIZE_USD > 0 and bonus_of is not None:
        def _fat(t):
            try:
                b = float(bonus_of(t[0]) or 0.0)
            except Exception:
                b = 0.0
            return (t[2] * b >= SPEC_FIRE_FAT_PRIZE_USD) if b > 0 else (t[2] >= SPEC_FIRE_FAT_DEBT_USD)
        return any(_fat(t) for t in tgts)
    return any(t[2] >= SPEC_FIRE_FAT_DEBT_USD for t in tgts)


# ---- EV цели = долг × близость к флипу (пакет B1) ----
# Селектор владельца ОДНОГО слота доски и ценностной гард #88 ранжируют не по долгу,
# а по EV. Близость считается из HF: down — залог должен упасть на (1-1/HF); up — долг
# вырасти на (HF-1). closeness = 1/max(dist, eps) — монотонно растёт к флипу, никогда не
# отрицательна (1-dist уходила в минус на далёких up-целях), и сильно вознаграждает
# цель у самой кромки (proximity). Незнание HF -> None: цель НЕ тащится по одному долгу
# (канон «незнание закрывает гард») — в ранжировании падает в нижний бакет, в гарде #88
# не вытесняет живого владельца. HF из Morpho API (main.py:86) — по канону врёт на
# экзотике; это НАСЛЕДУЕМЫЙ предел входа EV, не чинится в B1 (см. named_limits).
_EV_CLOSE_EPS = float(os.environ.get("SPEC_FIRE_V2_EV_CLOSE_EPS", "0.0001"))


def _flip_dist(hf, direction):
    """Дистанция до флипа из HF; None = HF нечитаем (нет ключа / <=0)."""
    if hf is None:
        return None
    try:
        hf = float(hf)
    except (TypeError, ValueError):
        return None
    if hf <= 0.0:
        return None
    if hf <= 1.0:
        return 0.0                       # уже за кромкой — ближе не бывает
    return (hf - 1.0) if direction == "up" else (1.0 - 1.0 / hf)


def _plan_ev_val(debt, hf, direction):
    """EV = долг × близость. None = HF нечитаем ИЛИ долга нет (нижний бакет / не вытесняет)."""
    d = _flip_dist(hf, direction)
    if d is None:
        return None
    dd = float(debt or 0.0)
    if dd <= 0.0:
        return None
    return dd * (1.0 / max(d, _EV_CLOSE_EPS))


# КАП МЕЛКОГО ОКНА (kelbic «го б» 26.08, вариант (б) экономики). Замер суток: 2317 проб из
# 2382 (97%) ушли в 13 плотных окон, 12 из них — XRP на целях debt=$0-2k (приз десятки $), а
# транзитов С ЖЕРТВОЙ за сутки был ОДИН. То есть 97% газа жглось там, где приза физически
# нет, и суточный бакет $450 исчерпывался к 09:46 — к настоящему каскаду денег могло не
# остаться. Мелкое окно = НЕ fat (приз ниже SPEC_FIRE_FAT_PRIZE_USD) И НЕ открытое
# детонатором (детонаторное = близкая цель, ради которой окно и живёт). Жирные и
# детонаторные окна НЕ ТРОГАЮТСЯ вовсе.
# ДЕФОЛТ 0 = ВЫКЛЮЧЕНО (поправка 26.08 по вопросу kelbic «а приборы?»): замер показал, что
# кап окна режет лишь пробы ГЛАВНОГО кошелька (1207 за 4.2ч), а основной расход даёт ДВИЖОК
# с ног флота (board_probes 4731) — он капом окна не ограничен. Экономия вышла бы ~$25-35 из
# $390/сутки, при этом приборы позиции/класса кормятся именно tx движка и не пострадали бы —
# но и резать нечего. Ручка готова и проверена стендом; включение — SPEC_FIRE_SMALL_CAP=20,
# осмысленно ТОЛЬКО вместе с правкой права огня движка по тому же признаку (отдельная спека).
SPEC_FIRE_SMALL_CAP = int(os.environ.get("SPEC_FIRE_SMALL_CAP", "0"))
# ПОРОГ ПРИЗА ДЛЯ ИСКЛЮЧЕНИЯ ИЗ МАЛОГО КАПА (kelbic «го» 26.08, по аналогии с HR-полом $300).
# Замер: XRP-окно на ПЫЛИ стоит 146-150 проб × 250 CU ≈ 36.5k CU при призе $2-16 — работа
# пылесоса по тарифам боевого ключа. Детонатор освобождает от капа ТОЛЬКО настоящие призы;
# пыль у воды режется до SPEC_FIRE_SMALL_CAP. Гейт считается НА АРМЕ окна и печатается в
# close-строке (`det[...]`) — иначе спор «почему окно полное» повторится вслепую. НАЗВАННЫЙ
# ПРЕДЕЛ: приз плавает с ценой, цель с $250 может перевалить $300 внутри окна — срез на
# открытии осознанный. Откат: SPEC_FIRE_DET_PRIZE_USD=0 (исключение снова безусловное).
SPEC_FIRE_DET_PRIZE_USD = float(os.environ.get("SPEC_FIRE_DET_PRIZE_USD", "300"))


def _window_cap(fat_mode: bool, det: bool = False) -> int:
    if SPEC_FIRE_EV_DENSITY and fat_mode:
        return SPEC_FIRE_FAT_CAP
    if SPEC_FIRE_SMALL_CAP > 0 and not det:
        return min(SPEC_FIRE_SMALL_CAP, SPEC_FIRE_MAX_PROBES_WINDOW)
    return SPEC_FIRE_MAX_PROBES_WINDOW


def _dense_interval(fat_mode: bool) -> float:
    if SPEC_FIRE_EV_DENSITY and fat_mode:
        _j = SPEC_FIRE_FAT_JITTER_SEC
        return max(0.10, SPEC_FIRE_FAT_INTERVAL_SEC + (random.uniform(-_j, _j) if _j > 0 else 0.0))
    _j = SPEC_FIRE_DENSE_JITTER_SEC
    return max(0.25, SPEC_FIRE_DENSE_INTERVAL_SEC + (random.uniform(-_j, _j) if _j > 0 else 0.0))
# КЭШ ПРОБЫ: _build на каждую пробу = 2×aggregate3 + роут — на плотном каденсе это душило бы
# ядро и RPC (эффект наблюдателя). Позиция/шары за секунды не меняются, плохой филл ревертится
# min_profit-полом контракта -> собранный calldata переиспользуем REBUILD_SEC.
# 5.0 -> 2.5 (31.07, «го» kelbic после апгрейда Шарлотты до 2 ядер): 5с = 2.5 блока жизни
# жертвы, проба могла стрелять устаревшими шарами/роутом; 2.5с = свежесть в один блок, защита
# hot path больше не требует голодания (2-е ядро). Гарды на первом окне: load>1.5 или
# деградация реакции -> откат SPEC_FIRE_REBUILD_SEC=5 (см. docs/ROLLBACKS.md).
SPEC_FIRE_REBUILD_SEC = float(os.environ.get("SPEC_FIRE_REBUILD_SEC", "2.5"))
# TIP-ГАРД: FCFS — tip НЕ покупает место (победитель 14:07 взял приз с tip 0.0034 против наших
