# SPEC_FIRE_V2_EV_MARGIN=0 ⇒ вытесняет любое строгое превосходство.
SPEC_FIRE_V2_EV_MARGIN = float(os.environ.get("SPEC_FIRE_V2_EV_MARGIN", "0.2"))
