# только живой севший план; V1-деградация сидит за тир-гейтом, ложным в решающий блок). Осечка
# ОДНОГО setPlan при каденсе переарма 240с оставляла окно короче ретрая вовсе без доски: движок
# выглядит здоровым, проб ноль. Поэтому неудача переспрашивается БЫСТРО, а не через каденс.
SPEC_FIRE_V2_ARM_RETRY_SEC = float(os.environ.get("SPEC_FIRE_V2_ARM_RETRY_SEC", "5"))
# #112 REVIEW (MAJOR-1/КРИТИЧНО): ценовой аудит НЕ подчинён бюджету подписи (иначе R1 «пересобрать
# флот за проход» и A1 «низкий потолок» неразрешимо конфликтуют) — но на скачке базы В ОКНЕ он
# серийно пересобирает ВСЕ протухшие ноги (до 110×40=4400 подписей ≈ 2.08с непрерывной подписи)
# на ЕДИНСТВЕННОМ треде fire-refill. На одноядерной Шарлотте это МОНОПОЛИЗИРОВАЛО бы ядро под GIL
# на решающие 2-4с каскада: 8 воркеров огня и БОЕВОЙ dispatch_liquidations остались бы без CPU,
# флот теряет присутствие на транзите в момент приза (урок single-core-observer-effect). Освобождение
# бюджетом сломало бы R1 (4400/125≈35 проходов). Поэтому ломаем МОНОПОЛИЮ, а не работу: между
# ногами тред УСТУПАЕТ ядро явным сном (sleep(0) ненадёжен против ~5мс кванта переключения GIL —
# берём 3мс). Максимальный НЕПРЕРЫВНЫЙ захват GIL падает с ~2.08с до одной ноги (~40 подписей
# ≈ 19мс p50 / 44мс p99); суммарная добавка к стенке ≈ (ног−1)×3мс ≈ 0.3с, сходимость остаётся в
# окне. Лока в этом цикле НЕ держим (invalidate/presign берут лок ноги внутри и отпускают), поэтому
# сон безопасен. Откат: SPEC_FIRE_AUDIT_YIELD_SEC=0.
SPEC_FIRE_AUDIT_YIELD_SEC = float(os.environ.get("SPEC_FIRE_AUDIT_YIELD_SEC", "0.003"))
# Ручка на РАЗМЕР бёрста аудита (в дополнение к каденсу PRICE_AUDIT_SEC, который двигает лишь ЧАСТОТУ).
# Кап пересборок за ОДИН проход аудита: остаток протухших ног ДОБИВАЕТСЯ на следующих проходах (их
# лестницы остаются протухшими -> аудит их снова находит следующим проходом; работа не теряется, а
# размазывается по каденсам, в окне следующий проход через ~1с). 0 = БЕЗ капа (только откат; бёрст
# тогда держит одна уступка ядра YIELD_SEC).
# #112 R2 (находка #2, дрель R7): дефолт 0 означал, что ОДИН проход аудита на каскаде пересобирал
# ВСЕ ~110 протухших ног = 110×DEPTH ≈ 4400 подписей ≈ 2.08с непрерывной подписи — монополизация
# ядра в решающие 2-4с (замер вердикта 20/20). Дефолт выведен из СЕГМЕНТА fire-refill-треда (200мс),
# а НЕ из ENGINE_SIGN_BUDGET: аудит СОЗНАТЕЛЬНО не подчинён бюджету подписи (см. MAJOR-1 выше — иначе
# R1 «пересобрать флот за проход» и низкий потолок неразрешимо конфликтуют). Кап = сколько ног влезает
# в один 200мс-сегмент ядра: floor(200мс / (DEPTH×p99)) = floor(200 / (40×0.985)) = 5 ног
# (5×40 = 200 подписей ≈ 95мс на замеренной цене 0.473мс/подп, ≈197мс на хвостовой p99 0.985мс — под
# сегментом). Пять ног ломают МОНОПОЛИЮ (2.08с -> ~0.1-0.2с непрерывного захвата ядра), оставляя CPU
# воркерам огня и боевому dispatch; остаток флота добивается следующими проходами.
# #112 R2 (линза-2 рв2, MAJOR): НАЗВАННАЯ СУММА капа. Кап размазывает ПОЛНЫЙ репрайс флота по
# каденсам: при N протухших ног и каденсе 1.0с в окне сходимость к 3x-запасу идёт ~ceil(N/кап)
# проходов = 110/5≈22 ≈ 24с (замер demo_cap_cadence: cap=True -> 23.845с/polls=43 против
# uncapped 2.908с/polls=1). Это ВЫШЕ 2.581с, что показывает приёмка R1 — но R1 гоняет audit_fn
# БЕЗ капа (полный репрайс за проход), поэтому её зелёный капнутый агрегат НЕ доказывает; joint
# кап+каденс дрель в пиннутые приборы не входит (сторона координатора). Предел ДОПУСТИМ: это
# деградация ЗАПАСА (2x вместо 3x форы включаемости ≈ 6 блоков Base для пробы, что садится
# следующим блоком), НЕ немота — включаемость держится 110/110 весь репрайс (множитель maxFee 20x
# против дрейфа <=12.5%/блок; выход из игры требовал бы ~25 блоков ~50с непрерывного макс-дрейфа,
# что кап 24с покрывает с запасом >2x). Под непрерывным макс-дрейфом флота цена всё равно сходится
# 110/110; отстаёт ГЛУБИНА склада (67/110 на 60с) — ОРТОГОНАЛЬНЫЙ путь бюджета долива, не кап.
SPEC_FIRE_AUDIT_MAX_RESIGN = int(os.environ.get("SPEC_FIRE_AUDIT_MAX_RESIGN", "5"))
# #112 REVIEW (MAJOR-3): кэш базы под TTL. В ОКНЕ депт-долив (fire-refill) звал presign_ladder БЕЗ
# base_fee, и КАЖДЫЙ вызов делал свой get_block RTT в боевой ключ ДО compat-проверки. С узкой полосой
# [39,40] долив срабатывает почти каждый проход -> шторм get_block на всю 180с-фазу удержания (~9/с
# × 180с ≈ 1600 на арм), проходящий ПОД бюджетом подписи (бюджет считает подписи, не RTT) — эскалация
# истории #100 (наш огонь топит боевой RPC) и уроков квоты 07-09.08. Аудит уже читает базу ОДИН раз
# на проход: делаем его ПИСАТЕЛЕМ кэша, депт-долив ЧИТАЕТ кэш при свежести (TTL ~2× каденса аудита
# в окне ≈ блок Base), иначе fail-open к своему get_block (корректность важнее экономии). Сток
# get_block в удержании падает с ~9/с до ~1/с (аудитового) и заодно перестаёт ОТКЛАДЫВАТЬ 1с-аудит.
# Множитель maxFee (×20) держит 2с-старую базу с огромным запасом. Откат: SPEC_FIRE_BASE_FEE_TTL_SEC=0.
SPEC_FIRE_BASE_FEE_TTL_SEC = float(os.environ.get("SPEC_FIRE_BASE_FEE_TTL_SEC", "2.0"))
# Ш29: залп по подтверждённому транзиту (откат SPEC_FIRE_TRANSIT_BURST=0).
SPEC_FIRE_TRANSIT_BURST_ON = os.environ.get("SPEC_FIRE_TRANSIT_BURST", "1") == "1"
# Право огня движку по подтверждённому транзиту вне зависимости от порога огня (#47+#41).
SPEC_FIRE_HANDOFF_KEEPALIVE = os.environ.get(
    "SPEC_FIRE_HANDOFF_KEEPALIVE", "1").lower() not in ("0", "false", "no")
# Как часто переиздавать отметку probe_board, пока план жив (потребители гейтят 10с).
SPEC_FIRE_BOARD_RESTAMP_SEC = float(os.environ.get("SPEC_FIRE_BOARD_RESTAMP_SEC", "4"))
# Право огня движку в ЗАКРЫТУЮ секунду фазового гейта (#64): гейт экономит газ кадансовых
# проб, а не выключает плотность. Откат: SPEC_FIRE_LATTICE_KEEPALIVE=0.
SPEC_FIRE_LATTICE_KEEPALIVE = os.environ.get(
    "SPEC_FIRE_LATTICE_KEEPALIVE", "1").lower() not in ("0", "false", "no")
# #49: предел доверия к `updatedAt` оракула. Больше — часы разъехались (или апдейт из
# прошлого), метка встаёт на время детекта, и это видно счётчиком lattice_skew_bad.
SPEC_FIRE_LATTICE_MAX_SKEW_SEC = float(os.environ.get("SPEC_FIRE_LATTICE_MAX_SKEW_SEC", "120"))
SPEC_FIRE_V2_PROBE_GAS = int(os.environ.get("SPEC_FIRE_V2_PROBE_GAS", "260000"))
# ЛИМИТ ГАЗА ПРОБЫ ДОСКИ — считается от ВЫИГРЫША, а не от no-op'а (замер 07.08, #32).
# Однобайтовая проба почти всегда тихий no-op (18.6k), но в тот единственный раз, когда
# триггер сработал, ОНА ЖЕ исполняет весь план. Три измеренных числа задают лимит:
#   709 038 — реальная ликвидация со свопом (исполнитель конкурента, блок 49642833);
#   +214 941 — надбавка нашего пути: план на 2KB копируется из ХОЛОДНОГО стораджа
#              (форк-замер testFireGasFallbackVsDirectHeavyRoute: 449 983 против 235 042);
#   2 470 096 — фактический расход на ките $1.5M (форк-экзамен 25.07, из-за него главный
#              путь огня и держит gas_limit_floor=4M).
# Прежние 260k (и 625k у V1-пробы) не покрывают ни одного из этих случаев, а OOG внутри
# fallback ГЛОТАЕТСЯ try/catch: tx успешна, план цел, приз ушёл — без следа в журнале.
# На Base платим за ИСПОЛЬЗОВАННЫЙ газ, поэтому запас в лимите почти бесплатен; его
# единственная цена — резерв maxFee x limit на балансе ноги, и он разведён с расходом
# отдельно (см. _VOLLEY_EXPECTED_GAS в execute: гейт по худшему случаю, декремент по факту).
# #89 (10.08): 3M -> 900k. Два независимых выигрыша, оба замеренные.
# (1) ПОРОГ НЕМОТЫ. Резерв гейта патрона = gas x maxFee, поэтому лимит входит в него прямо:
#     при 3M и множителе 20 флот немел выше 0.083 gwei (замер: 82% ног при 0.0808), при
#     900k и множителе 5 — выше 1.11 gwei, то есть покрывает июньский p90 0.755.
# (2) ПОПАДАНИЕ В РЕШАЮЩИЙ БЛОК. op-geth снимает с пула ПОЛНЫЙ лимит tx, поэтому пробу на 3M
#     не пускают всякий раз, когда в блоке осталось меньше 3M — а это ровно хвост
#     стопроцентно заполненных блоков каскада (49666339-42 шли на 399.58-399.99M из 400M).
# Запас держим ЧЕСТНЫЙ: замеренный худший случай пробы 710k (форк #70), сегодняшний прогон
# дал 649 623. НО существующий набор требует больше: 709 038 (попытка со свопом) +
