PENDING_KEEPALIVE_SEC = float(os.environ.get("PENDING_KEEPALIVE_SEC", "3.5"))
# WS-handoff (разбор 06.08, «го на пендинг детект»): источник детекта для A2 — НЕ полл
# сторонних "pending" (у base.org/nodies/dRPC это алиас latest — ярус-1 слеп до запечатывания,
# 0 handoff за всю жизнь слоя; замер pd_probe 06.08), а СОБСТВЕННАЯ recv-петля flashblocks:
# она уже видит transmit в формируемом блоке (~200мс суб-кадры) и зовёт _process_transmit.
# note_ws_transmit() ставит pending_fire армленному окну с досягаемой доской -> окно стреляет
# ГОТОВОЙ пробой за <=SPEC_FIRE_POLL_SEC, минуя конвейер реактива (гонка №3: победитель бил
# in-block, наша реакция структурно +1 блок). Кулдаун гасит дубли feed/bare/poll-источников
# одного транзита. Откат: PENDING_WS_HANDOFF=0 (см. docs/ROLLBACKS.md).
PENDING_WS_HANDOFF = os.environ.get("PENDING_WS_HANDOFF", "1").lower() not in ("0", "false", "no")
PENDING_WS_CD_SEC = float(os.environ.get("PENDING_WS_CD_SEC", "2.0"))
PENDING_WS_BOARD_MAX_AGE_SEC = float(os.environ.get("PENDING_WS_BOARD_MAX_AGE_SEC", "10.0"))


# канон дробления живёт в chain.execute (общий для проб и fast-lane); ре-экспорт для юнитов
from chain.execute import partial_shares_for_cap  # noqa: E402


def _facts_fresh(now_wall=None):
    """True = факт-сигнал каскада действителен (флаг существует и mtime моложе TTL)."""
    if not SPEC_FIRE_HYBRID:
        return True
    try:
        age = (time.time() if now_wall is None else now_wall) - os.path.getmtime(SPEC_FIRE_FACTS_FLAG)
        return 0 <= age <= SPEC_FIRE_FACTS_TTL_SEC or age < 0   # mtime в будущем = свежий (скью часов)
    except OSError:
        return False
SPEC_FIRE_THRESHOLD = float(os.environ.get("SPEC_FIRE_THRESHOLD", "1.0"))     # ×dev
# ДЕТОНАТОР-ЧУВСТВИТЕЛЬНОСТЬ (пост-мортем $128k 22.08): цель hf=0.9987 флипается движением
# 0.13%, а универсальный порог окна dev×THRESHOLD=0.5% — окно «не считало эту цель своей
# войной», залп не вышел, реактивная лента (+425мс = 2-4 суб-блока) проиграла стоячей
# предочереди. Порог огня = clamp(min(универсальный, ближайший flip_dist жирной цели фида),
# пол_шума, универсальный); пол шума держит hf=1.000001 от окна каждым тиком; кап окон
# близости в минуту — предохранитель от дребезга. Откат: SPEC_FIRE_DET_SENSE=0.
SPEC_FIRE_DET_SENSE = os.environ.get("SPEC_FIRE_DET_SENSE", "1").lower() not in ("0", "false", "no")
SPEC_FIRE_DET_NOISE_FLOOR = float(os.environ.get("SPEC_FIRE_DET_NOISE_FLOOR", "0.0005"))
SPEC_FIRE_DET_WIN_CAP_MIN = int(os.environ.get("SPEC_FIRE_DET_WIN_CAP_MIN", "6"))
# Predicted-HF гейт (24.07, ревью + live-данные): цена на транзите ~= текущий Binance mid,
# значит проба имеет смысл ТОЛЬКО если этот транзит способен флипнуть цель:
#   dist_to_flip <= |ret| + MARGIN_DEVS × dev   (аддитивный запас на лаг HF-кэша ~60с,
# USD-approx HF и следующий dev-шаг; НЕ мультипликативный — reach×3 на ret −3% открывал бы
# огонь по цели в 9%, которую ЭТОТ транзит не флипнет). Первый живой день: 6 окон × 10 проб
# по киту dist=8.25% на ret −0.11% — гейт отсёк бы всё ($0.59 и бакет целы).
# Арм-гейт: окно вовсе не стартует, если ближайший жир дальше ARM_MAX_DIST (нет ни петли,
# ни ончейн-фингерпринта по заведомо мёртвым окнам); в настоящий каскад HF-refresh (~60с)
# подтянет dist под потолок — последующие армы окно запустят.
# Откат без кода: SPEC_FIRE_DIST_MARGIN_DEVS=1e9 / SPEC_FIRE_ARM_MAX_DIST=1e9.
# HF цели неизвестен -> fail-open.
SPEC_FIRE_DIST_MARGIN_DEVS = float(os.environ.get("SPEC_FIRE_DIST_MARGIN_DEVS", "2.0"))
SPEC_FIRE_ARM_MAX_DIST = float(os.environ.get("SPEC_FIRE_ARM_MAX_DIST", "0.03"))
# #92: пол досягаемости ПРОГРЕВА доски. Прежде она считалась только как 3xdev от статической
# константы фида и при спокойной dev не дотягивалась до целей вовсе. По умолчанию равен
# порогу арма окна: доска планирует на ту же дистанцию, на какой окно себя армит.
SPEC_FIRE_PREARM_MIN_REACH = float(os.environ.get(
    "SPEC_FIRE_PREARM_MIN_REACH", str(SPEC_FIRE_ARM_MAX_DIST)))
# PEAK-OWED fire-policy («го» kelbic 02.08, дизайн ревью): транзит оракула, заряженный на
# пике (|ret| пробил dev), НЕ отменяется отскоком — едет на чейн 22-50с (shadow-леады) и
# садится старой ценой. Старая политика глушила огонь по текущему ret и отдавала такие
# посадки конкурентам («оконная рулетка», гонка cbDOGE 01.08 18:50: пик 18:49, транзит
# +50с). Долг: каждый горячий тик продлевает owed_until на HOLD_SEC и задирает owed_ret до
# пика; серая полоса гистерезиса (|ret| >= thr - OWED_BAND*dev) тоже продлевает — без неё
# дрожание у порога съедало бы таймер («та же рулетка уровнем ниже», ревью). В долге огонь
# живёт с reach по ПИКОВОМУ ret, disarm/falsepos окно не убивают (sticky), confirmed/push/
# stale убивают как раньше. Каждый выстрел, который старая политика пропустила бы, помечен
# [owed] в журнале + stats[owed_probes] — атрибуция бенчмарка, не спор версий.
# Цена: реверты по невыехавшим транзитам (~$0.01/проба), кап проб/бакет прежние.
# Откат: SPEC_FIRE_PEAK_OWED=0 (огонь только по текущему ret, disarm убивает окно).
SPEC_FIRE_PEAK_OWED = os.environ.get("SPEC_FIRE_PEAK_OWED", "1") == "1"
# ============ В1 (15.08): ЛИПКОЕ ОКНО — ЖИТЬ СЕРИЮ ПУШЕЙ ============
#
# Причина №4 вскрытия 110 проигрышей: окно закрывалось ПО ПЕРВОМУ транзиту, а деньги шли на
# СЛЕДУЮЩЕМ пуше серии (замер: +30с нёс $27k / 26 ликвидаций; predict disarm за 0.6с до пуша).
# Теперь confirmed/push НЕ закрывает окно, а засчитывает пуш серии — окно ре-армится на
# следующий, пока: (а) возраст окна < V1_SERIES_TTL_SEC (жёсткий TTL — вечных окон нет);
# (б) пушей серии < V1_MAX_PUSHES; (в) состояние ЧИТАЕТСЯ — K подряд нечитаемых тиков
# (ret_fn=None: без mid ни reach, ни переоценка HF целей невозможны — это наш уровеньный
# прокси «нечитаемых HF», честно назван) закрывают окно ГАРДОМ (незнание закрывает гард).
# Гард #88 (ценностной, живой пересчёт EV) и #54 (выручка в kill-switch) — предусловия,
# оба в бою. WIN-закрытие окна НЕ ТРОНУТО (замороженный слой). Откат SPEC_FIRE_V1=0 —
# прежнее «одноразовое окно» бит-в-бит.
SPEC_FIRE_V1 = os.environ.get("SPEC_FIRE_V1", "1") == "1"
SPEC_FIRE_V1_SERIES_TTL_SEC = float(os.environ.get("SPEC_FIRE_V1_SERIES_TTL_SEC", "150"))
SPEC_FIRE_V1_MAX_PUSHES = int(os.environ.get("SPEC_FIRE_V1_MAX_PUSHES", "4"))
SPEC_FIRE_V1_UNREADABLE_K = int(os.environ.get("SPEC_FIRE_V1_UNREADABLE_K", "8"))
SPEC_FIRE_OWED_HOLD_SEC = float(os.environ.get("SPEC_FIRE_OWED_HOLD_SEC", "75"))
SPEC_FIRE_OWED_BAND = float(os.environ.get("SPEC_FIRE_OWED_BAND", "0.3"))   # доля dev
# Двухфазный каденс (по замеру 24.07: транзит приходит через 22-31с ПОСЛЕ пробития dev —
# OCR-раунд оракула; старый каденс 0.7с выжигал кап за ~7с, за 22с до транзита): первые
# BURST проб быстро (страховка от мгновенного/heartbeat-транзита), дальше медленно — кап 10
# растягивается на ~0.7+8×3.5 ~= 29с, накрывая замеренный лаг. Тюнить по новым транзитам.
SPEC_FIRE_BURST_PROBES = int(os.environ.get("SPEC_FIRE_BURST_PROBES", "2"))
# ХВОСТ 3.5 -> 2.0с и кап 10 -> 24 (27.07, shadow-датасет 871 арм/462 транзита): проба полезна
# ровно в БЛОКЕ транзита, значит ценность = доля покрытых блоков в зоне плотности. Замер
# «первая проба -> транзит» (живые окна): медиана 31с, 6-213с; окна с жиром: мед 40 p75 64с.
# 24×2.0с = ~45с покрытия ОДНОЙ пробой на КАЖДЫЙ блок (было 10×3.5 = 29с и один выстрел на
# ~1.75 блока). Цена $0.29/окно против $0.12 — суточный бакет $10 не замечает (7 окон/19д).
SPEC_FIRE_SLOW_INTERVAL_SEC = float(os.environ.get("SPEC_FIRE_SLOW_INTERVAL_SEC", "2.0"))
# ДЖИТТЕР хвоста: ровное расписание читается конкурентом как подпись слоя (тот же мотив, что
# у WIN-паузы). ±0.3с ломает периодичность почти бесплатно — покрытие блоков не страдает.
SPEC_FIRE_TAIL_JITTER_SEC = float(os.environ.get("SPEC_FIRE_TAIL_JITTER_SEC", "0.3"))
# Пауза после WIN (25.07, ревью-фингерпринт): серия «пробы -> приз» ончейн читается конкурентом
# как учебник нашего слоя. После взятого приза окна не армятся COOLDOWN сек — паттерн рвётся,
# а сам приз уже в кармане (реактивный путь паузой НЕ трогаем, он главный). 0 = выключено.
SPEC_FIRE_WIN_COOLDOWN_SEC = float(os.environ.get("SPEC_FIRE_WIN_COOLDOWN_SEC", "900"))
# #46 (решение владельца 08.08, ревью). Кулдаун победы страховал РЕАКТИВНЫЙ тракт от двойного
# расхода инвентаря и от «палева паттерна проб». Обе премиссы устарели: реакция 0/9794, а пробы
# движка инвентарь не тратят вовсе — страхуемый актив отсутствует, значит страховка чистый
# убыток. Прежнее поведение (любая победа гасит арм ВСЕХ фидов на 900с) в каскаде отдавало
# стене ноги 2+: каждый пуш ре-якорит и дизармит, новой ноге нужен новый arm, а он заблокирован.
#   TRIGGER=combat (дефолт) — взводит только БОЕВАЯ победа с положительным доказательством
#                             захвата; победа пробы (в т.ч. 1-байтовой) кулдаун не ставит.
#   TRIGGER=any             — прежнее «любая победа» (откат).
#   SCOPE=feed (дефолт)     — гасится только фид, чья цель взята; остальные стреляют.
#   SCOPE=global            — прежнее «все фиды» (откат).
# TTL 900с намеренно не трогаем этим пакетом — отдельной задачей после телеметрии.
SPEC_FIRE_COOLDOWN_TRIGGER = os.environ.get("SPEC_FIRE_COOLDOWN_TRIGGER", "combat").strip().lower()
SPEC_FIRE_COOLDOWN_SCOPE = os.environ.get("SPEC_FIRE_COOLDOWN_SCOPE", "feed").strip().lower()
SPEC_FIRE_MIN_PROFIT_BPS = int(os.environ.get("SPEC_FIRE_MIN_PROFIT_BPS", "30"))
SPEC_FIRE_POLL_SEC = float(os.environ.get("SPEC_FIRE_POLL_SEC", "0.15"))
SPEC_FIRE_RECEIPT_TIMEOUT = float(os.environ.get("SPEC_FIRE_RECEIPT_TIMEOUT", "45"))
# П.3 (22.08): thread-per-call -> коллекторная модель квитанций ОКНА. Корень трёх инцидентов
# (cgroup-душилка, TasksMax=256, «два потолка» 05:38Z) — тред на каждую пробу/квитанцию в
# _collect/_collect_volley, при том что движок уже вылечен ReceiptCollector'ом. Режимы:
#   thread    — легаси бит-в-бит (тред-на-пробу); это и ручка ОТКАТА без кода;
#   shadow    — ДЕФОЛТ миграции: деньги ведёт легаси-тред, коллектор параллельно сверяет
#               исход на тех же хэшах, расхождение в лог (неделя/200 проб -> collector);
#   collector — очередь коллектора вместо тредов; переполнение = учётный дроп в
#               collector_overflow + фолбэк легаси-тредом (денежный инвариант «ровно один
#               исход на отправку» не теряется никогда).
SPEC_FIRE_RCPT_MODE = os.environ.get("SPEC_FIRE_RCPT_MODE", "shadow").lower()
SPEC_FIRE_RCPT_MAX_PENDING = int(os.environ.get("SPEC_FIRE_RCPT_MAX_PENDING", "4096"))


def _probe_tip_wei(tip_gwei: float) -> int:
    """Tip ЛЮБОЙ пробы = ПОЛ рынка (#91, дыра найдена анализатором Ш10 10.08).

    Прежде здесь стоял min(боевой, кап) = 0.05 gwei. Ш1 перевёл на пол флотские пути
    (presign_ladder, send_volley_probe), но КАДАНСОВЫЕ пробы главного кошелька — те самые
    30 штук за окно, что реально садятся в блоки, — остались на боевом tip. Анализатор
    показал это на свежем блоке 49789768: транзит на idx 19, наши tx на idx 1 (−18) и idx 48
    (+29), обе с tip 0.0500 — ровно телепорт в голову суб-блока и в начало следующего, мимо
    призового окна. Дыру не увидел ни один тест: они экзаменовали кап каскадной ступени, а не
    отношение к полу рынка.

    Кап каскадной ступени сохраняем как ВЕРХНЮЮ границу: если кто-то поднимет cfg.tip_gwei,
    проба всё равно не уедет выше капа. Но по умолчанию проба идёт на полу — внутри суб-блока
    сортировка по убыванию tip, и плата выше пола выносит нас ПРОЧЬ от транзита."""
    from chain.execute import _PROBE_TIP_WEI
    return int(min(_PROBE_TIP_WEI, SPEC_FIRE_TIP_CAP_GWEI * 1e9))


def _receipt_has_win(r, liquidator_addr: str):
    """Есть ли в квитанции событие Liquidated ОТ НАШЕГО контракта (см. LIQUIDATED_TOPIC0).

    -> True/False, либо None если о логах судить нельзя (поле отсутствует). None НЕ равно False:
    на доске оно означает «не знаю», и вызывающий обязан не объявлять победу, а на пути V1 —
    что вердикт остаётся за статусом. Чужие Liquidated (конкурент в том же блоке) отсекаются
    сверкой адреса эмитента: событие есть у многих, наш контракт — один.
    """
    logs = r.get("logs") if hasattr(r, "get") else None
    if logs is None:
        return None
    want = (liquidator_addr or "").lower()
    for lg in logs:
        try:
            src = lg.get("address") if hasattr(lg, "get") else getattr(lg, "address", None)
            tops = lg.get("topics") if hasattr(lg, "get") else getattr(lg, "topics", None)
            if not tops or str(src or "").lower() != want:
                continue
            t0 = tops[0]
            t0 = t0.hex() if hasattr(t0, "hex") else str(t0)
            if not t0.startswith("0x"):
                t0 = "0x" + t0
            if t0.lower() == LIQUIDATED_TOPIC0:
                return True
        except Exception:
            continue
    return False


class SpecFireLive:
    """Потребитель событий PredictDriver + fire-петля на окно. Все внешние вызовы — через швы."""

    def __init__(self, rpc, cfg, shared, ret_fn, dev_by: dict,
                 build_fn=None, send_fn=None, receipt_fn=None, log_fn=None,
                 now=time.monotonic, sleep=None,
                 volley_accounts_fn=None, volley_send_fn=None):
        self.rpc, self.cfg, self.shared = rpc, cfg, shared
        self.ret_fn = ret_fn                      # label -> текущий return к якорю (None = нет данных)
        self.dev_by = {k.upper(): float(v) for k, v in dev_by.items()}
        self._build_fn = build_fn                 # шов: (mid, borrower, debt_usd) -> {calldata, gas}|None
        self._send_fn = send_fn                   # шов: (calldata, gas) -> hash|None
        self._receipt_fn = receipt_fn             # шов: (hash) -> (status, gas_usd)|None
        self._volley_accounts_fn = volley_accounts_fn   # шов тира: () -> [(addr, key)]
        self._volley_send_fn = volley_send_fn     # шов тира: (rpc,cfg,addr,key,calldata,gas,...) -> hash|None
        self._log = log_fn or (lambda m: log.info("%s", m))
        self._now = now
        self._sleep = sleep or time.sleep
        self._lock = threading.Lock()
        self._windows: dict = {}                  # feed -> stop Event
        self._armskip_ts: dict = {}               # feed -> ts последнего arm-skip-лога (троттлинг 300с)
        self._cooldown_until = 0.0                # WIN-пауза (SCOPE=global): окна не армим
        self._cooldown_feed: dict = {}            # feed -> ts (SCOPE=feed, дефолт): гаснет только
                                                  # фид, чья цель взята — ноги 2+ каскада живы
        self._arm_ts: list = []                   # ts армленных окон за час (каскад-детект)
        self.stats = {"windows_armed": 0, "probes": 0, "wins": 0,
                      "owed_probes": 0, "sticky_windows": 0,   # peak-owed: would-have-fired учёт
                      "pending_fires": 0,                      # A2: выстрелы по pending-handoff
                      "volley_probes": 0,                      # каскадный тир: ноги залпа (07.08)
                      "lattice_skips": 0,                      # фазовый гейт: тики без огня
                      "lattice_hits": 0, "lattice_misses": 0,  # пуш в фазе / вне фазы (живой валидатор)
                      "board_arms": 0, "board_probes": 0,      # v5 доска: записей плана / 1-байт проб
                      "board_fails": 0,                        # арм не удался -> ноги ушли на V1
                      # v6-D4 (#135). ТРИ РАЗНЫХ ИСХОДА, и их нельзя мешать: «не сел» —
                      # доказанный отказ, «НЕИЗВЕСТНО» — узел не дорос (гард отставания),
                      # «чужой адрес» — флаг включён на контракте v5.
                      "board_v6_arms": 0, "board_v6_unlanded": 0,
                      "board_v6_unknown": 0, "board_v6_wrong_addr": 0,
                      "board_v6_cleared_targets": 0,
                      # §9/#133 СБОРЩИК ГРУППЫ. Осечка сборщика безопасна (деградация к n=1),
                      # и ровно поэтому она обязана быть НАЗВАНА: молчаливый откат к одной цели
                      # неотличим от «кандидатов не было», и мультицель три недели «работала бы»
                      # на группе из одного. group_assembled растёт НА РАЗМЕР группы — число
                      # арм-событий уже считает board_v6_arms, а здесь нужен счёт ЦЕЛЕЙ.
                      "group_assembled": 0, "group_skipped_kyber_owner": 0,
                      "group_skipped_no_extras": 0, "group_skipped_quotes_none": 0,
                      "group_skipped_infeasible": 0, "group_skipped_no_trigger": 0,
                      # дверь §9 отбила уже собранную группу на самом арме (чужой стэш,
                      # разъехавшийся состав): арм не сел, но прогрев обязан доработать
                      "board_v6_group_refused": 0}
        self._push_ts: dict = {}                  # feed -> метки севших пушей (решётка OCR, 07.08)
        self._board: dict = {}                    # v5 доска: {"key": (mid,b), "until": ts, "armed_ts": ts}
        self._board_lock = threading.Lock()       # арм доски — одна запись за раз (nonce главного)
        self._board_arm_fn = None                 # шов юнитов: (calldata, gas, tag) -> hash|None
        # --- v6-D4 (#135). Всё ниже мертво при SPEC_FIRE_V6=0 (дефолт) ---------------------
        self._board_v6: dict = {}                 # раскладка живого спана: {"g","count","until",
                                                  # "slots": {(mid,b): (g,i)}, "mp", "dl"}
        self._v6_call_fn = None                   # шов стенда: (to, data) -> bytes
        self._v6_send_fn = None                   # шов стенда: (calldata, gas) -> квитанция|None
        self._v6_head_fn = None                   # шов стенда: () -> номер головы узла
        self._owed: dict = {}                     # feed -> owed_until (peak-owed, пишет петля окна)
        self._prio: dict = {}                     # feed -> (claim_debt, ts): заявки на слот (пакет B)
        self.probe_board: dict = {}               # feed -> (mid, b, debt, calldata, gas, ts): свежая
                                                  # проба окна для яруса-2 pending (читает PendingDetect)
        self.pending_fire: dict = {}              # feed -> (mid, b, debt, ts): атомарный handoff (A2)
        self._win_birth: dict = {}                # В1: feed -> ts арма окна (перезаписывается армом,
        self._win_pushes: dict = {}               # чистка не нужна); feed -> пушей серии засчитано
        self.pending_healthy_fn = None            # () -> bool: pending-цикл жив (A3-кипэлайв)
        self._ws_handoff_ts: dict = {}            # feed -> ts последнего WS-handoff (кулдаун дублей)
        self._alert = None                        # (text, key) -> None: канал к ЧЕЛОВЕКУ. Ставится
                                                  # снаружи; нужен там, где состояние само не
                                                  # рассосётся (немота ног по комиссии)
        self._board_probe_cache: dict = {}        # (mid,b) -> (debt, calldata, gas): проба под
                                                  # живым планом, чтобы окна 2..N публиковали
                                                  # доску без пересборки (HIGH N1)
        # §9/#133: ЭКСТРА-ЦЕЛИ ГРУППЫ, собранные прогревом под ВЛАДЕЛЬЦА (mid,b). Стэш, а не
        # параметр `_arm_board`: сигнатуру метода пинят юнит-стабы prearm (см. коммент в
        # _arm_board), и лишний kwarg сорвал бы их TypeError'ом. Ровно ОДНА запись, как у
        # _board_probe_cache: словарь ПЕРЕЗАПИСЫВАЕТСЯ каждым проходом сборщика (в т.ч. пустым),
        # потому что котировки в планах привязаны к моменту снятия — доехать до двери на
        # следующем арме они не должны. Читается consume-once (pop) в v6-ветке арма.
        self._group_extra: dict = {}
        # СЧЁТЧИКИ ПОЗИЦИЙ — ПО КЛЮЧУ ДОСКИ (mid, borrower), ревью р-6, БЛОКЕР C.
        #
        # Общий self.stats годился, пока окна шли ПОДРЯД; в каскаде окна разных фидов живут
        # ОДНОВРЕМЕННО, а `_note_probe_position` зовётся из треда КОЛЛЕКТОРА. Правка р-5
        # привязала счётчики к ЯРЛЫКУ ФИДА — и на БОЕВОМ тракте это не работает: ярлык в
        # meta берётся из `FireEngine._target`, а это ОДНО перезаписываемое поле, куда пишет
        # ПОСЛЕДНИЙ тикнувший keepalive любого окна каскада. Дрель L3 (настоящие `_worker` и
        # `_engine_fat_keepalive`, доска армлена соседом под слепой рынок) показала ровно
        # прежнюю картину: окно BTC — no_agg=428 при judged=428.
        #
        # ПРАВИЛЬНЫЙ КЛЮЧ — ЦЕЛЬ ПЛАНА, под которым проба реально ушла: mid+borrower из того же
        # `_target`. Он не «последний тикнувший», а тот, чью калдату несёт проба, и потому
        # атрибуция перестаёт зависеть от порядка keepalive. Окно печатает дельту по ключу
        # СВОЕГО живого плана, пробы под ЧУЖИМ планом — отдельным бакетом, безключевые
        # (движок армлен без цели) — своим: незнание обязано быть НАЗВАНО, а не растворено.
        self._probe_by_key: dict = {}             # (mid,b)|None -> {ключ счётчика: значение}
        # КЛЕЙМО КЛЮЧА (р-7): что по этому плану УЖЕ засчитало закрывшееся окно. Без него два
        # окна каскада с совпавшими планами печатают одну дельту дважды.
        self._probe_claim: dict = {}
        # ПЛАН ОКНА — ТОЛЬКО ДЛЯ ИЗМЕРЕНИЯ (рез #110). feed -> (mid,b): план, который ЭТО окно
        # опубликовало. Читателей ровно два, и оба измерительные: закрывающая строка окна
        # (`план_окна=` и дельта позиций по СВОЕМУ ключу) и щадящий список `_live_plan_keys`
        # при вытеснении кольца. РЕШЕНИЙ ПО ОГНЮ ЗДЕСЬ НЕТ И БЫТЬ НЕ ДОЛЖНО: у этого словаря
        # была ВТОРАЯ роль — «чьё окно гасить при победе», — и ровно она три раунда подряд
        # давала то ложное действие, то бездействие. Роль срезана вместе со слоем победы, а
        # имя словаря сменено намеренно: чтобы её нельзя было вернуть по недосмотру.
        self._plan_key_by_feed: dict = {}
        self._board_next_try: dict = {}           # feed -> ts следующей попытки арма (#57): осечка
                                                  # арма обязана перепробовать БЫСТРО, а не через
                                                  # каденс переарма — окно короче ретрая иначе
                                                  # остаётся без доски, и весь флот нем
        self._det_capped: set = set()             # детонатор: фиды под капом окон близости
        self._det_key_by_feed: dict = {}          # feed -> ((mid,b), dist, ts): ЦЕЛЬ детонатора
        if SPEC_FIRE_DET_SENSE:                   # пушер det-dist — с ПЕРВОЙ секунды (линза (1))
            threading.Thread(target=self._det_push_loop, daemon=True,
                             name="det-dist-push").start()

    def note_ws_transmit(self, mids, src="ws"):
        """WS-handoff (06.08): recv-петля увидела transmit в ФОРМИРУЕМОМ блоке — если он бьёт
        по рынку доски армленного окна, ставим pending_fire (A2, тот же потребитель в петле
        окна, единый nonce). O(1)-словарные операции, зовётся с нити _process_transmit (не
        recv). mids = рынки транслирующего агрегатора. Возврат True = handoff поставлен."""
        if not PENDING_WS_HANDOFF or not mids:
            return False
        n = self._now()
        hit = False
        mids_l = {str(m).lower() for m in mids}
        for feed in list(self._windows):
            board = self.probe_board.get(feed)
            if not board:
                continue
            mid, b, debt = board[0], board[1], board[2]
            if mid.lower() not in mids_l or n - board[5] > PENDING_WS_BOARD_MAX_AGE_SEC:
                continue
            if n - self._ws_handoff_ts.get(feed, -1e9) < PENDING_WS_CD_SEC:
                continue
            self._ws_handoff_ts[feed] = n
            self.pending_fire[feed] = (mid, b, debt, n)
            try:                                  # П.7: метка стадии handoff (прибор сбоку)
                from chain.stage_probe import mark_feed as _mf
                _mf(feed, "handoff")
            except Exception:                     # noqa: BLE001
                pass
            hit = True
            self._log("SPECFIRE ws-handoff feed=%s %s/%s src=%s — транзит армленного фида "
                      "в формируемом блоке, огонь окну" % (feed, mid[:10], b[:10], src))
        return hit

    # ---- боевые швы ----
    def _build(self, mid, borrower, debt_usd):
        from chain.multicall import (aggregate3, encode_id_to_market_params_call,
            decode_id_to_market_params, encode_market_call, decode_market,
            encode_position_call, decode_position, encode_price_call, decode_price)
        from chain.simulate import to_assets_up
        from strategy.pnl import lif_from_lltv
        from chain.execute import direct_swap, encode_liquidate, _MORPHO_BLUE
        from chain.prearm import prearm_get
        m32 = self.rpc.to_bytes32(mid)
        r1 = aggregate3(self.rpc, [(_MORPHO_BLUE, encode_id_to_market_params_call(m32)),
                                   (_MORPHO_BLUE, encode_market_call(m32)),
                                   (_MORPHO_BLUE, encode_position_call(m32, borrower))])
        loan, coll, oracle, irm, lltv_wad = decode_id_to_market_params(r1[0][1])
        mk = decode_market(r1[1][1]); tba, tbs = mk[2], mk[3]
        bs, coll_amt = decode_position(r1[2][1])
        if bs == 0:
            return "gone"                         # позиция разобрана (конкурент/погашение) — LOSS-стоп
        if coll_amt == 0:
            # #78 (09.08, находка ревьюера): долг есть, залога нет — брать нечего ни по какой
            # цене. Раньше такая цель падала в `return None` ниже и оставалась в списке: вечная
            # пересборка по быстрому каденсу _arm_retry, а на вершине _top_fat (k=1) она ещё и
            # глушила прогрев склада. Семантика та же, что у разобранной позиции, — LOSS-стоп.
            return "gone"
        # ЖИВОЕ ОКНО НАЧИСЛЕНИЯ — В ТУ ЖЕ ПАЧКУ, ЧТО И ЦЕНА (лишнего RTT нет). Кап-ветка
        # `_cap_repaid_shares` обязана считать запас от `block.timestamp - market.lastUpdate` и
        # живой ставки IRM: окно — свойство РЫНКА, а не нашего TTL (замер 20.08: у этого рынка
        # 4714с без accrual, у LBTC/cbBTC — 9.8 суток), и худший случай коррелирует с самой
        # веткой (подводный рынок = утилизация под потолок = ставка максимальна).
        # Осечка ставки НЕ ломает сборку плана: цена читается своим вызовом, а незнание окна
        # закрывает ровно кап-ветку (её гард внутри `_cap_repaid_shares`), а не весь план.
        _rate_ps = None
        try:
            from chain.multicall import encode_borrow_rate_view_call, decode_borrow_rate_view
            _r2 = aggregate3(self.rpc, [(oracle, encode_price_call()),
                                        (irm, encode_borrow_rate_view_call(
                                            (loan, coll, oracle, irm, int(lltv_wad)), mk))])
            price = decode_price(_r2[0][1])
            _rate_ps = decode_borrow_rate_view(_r2[1][1]) if _r2[1][0] else None
        except Exception:                         # noqa: BLE001
            price = decode_price(aggregate3(self.rpc, [(oracle, encode_price_call())])[0][1])
        # lastUpdate — пятое поле market(); если снимок его не несёт (усечённый стенд/старый
        # декодер), окно НЕИЗВЕСТНО, и это закрывает кап-ветку, а не сборку плана.
        _last_upd = int(mk[4]) if len(mk) > 4 else None
        _elapsed = None if _last_upd is None else max(0, int(time.time()) - _last_upd)
        _drift = (lambda: None if (_rate_ps is None or _elapsed is None) else (_elapsed, _rate_ps))
        # #74 (09.08, находка ревьюера): путь ДОСКИ считал amount_in оценкой СВЕРХУ
        # (полные шеры + to_assets_up + expected_seized), тогда как горячий путь после фикса
        # P1-7 считает ТОЧНО по канону Morpho. Контракт аппрувит РОВНО фактический баланс
        # (Liquidator.sol:320-321), поэтому завышенный amount_in в предсобранной калдате
        # заставлял роутер тянуть больше, чем есть -> revert -> SwapFailed(). Именно это и
        # ловила форк-репетиция: одинаковый газ при minOut=долг и minOut=1, живая квота
        # канарейки. Плюс без капа шер глубокая позиция даёт Panic 0x11 внутри Morpho.
        from chain.hotpath import _seized_exact, _cap_repaid_shares, _shave_ask
        _lif_wad = int(round(lif_from_lltv(lltv_wad / 10**18) * 10**18))
        # #121: запас вниз ДО капа — заявка строго меньше долга (граница underflow Morpho)
        repaid_shares = _cap_repaid_shares(_shave_ask(int(bs)), int(coll_amt), int(price), _lif_wad,
                                           tba, tbs, drift_fn=_drift)
        if repaid_shares <= 0:
            return None
        if repaid_shares < int(bs):
            # КАП-ВЕТКА (тот же учёт, что в горячем пути): запоминаем ПРЕДВЫСТРЕЛЬНЫЙ залог,
            # иначе огрызок после нашего же выстрела неотличим от живой цели и жжёт подготовку.
            from chain.hotpath import note_cap_plan
            note_cap_plan(mid, borrower, coll_amt)
        repaid_assets = to_assets_up(repaid_shares, tba, tbs)   # репэй-сторона: вверх, как и было
        seized = _seized_exact(repaid_shares, _lif_wad, int(price), tba, tbs)
        if seized == 0:
            return None
        liq = self.cfg.liquidator_address
        mp = {"loanToken": loan, "collateralToken": coll, "oracle": oracle,
              "irm": irm, "lltv": lltv_wad}
        fl_max = float(getattr(self.cfg, "fast_lane_max_repaid_usd", 500000.0) or 500000.0)
        swap = None
        swap_meta = None                          # consume-хук (05.08): только direct-сайз списывает кап
        if debt_usd >= fl_max:                    # мега: обрыв одиночного пула -> сперва PREARM (Kyber)
            hit = prearm_get(coll, loan, int(seized))
            if hit is not None:
                swap = hit["swap"]
        if swap is None:
            swap = direct_swap(coll, loan, seized, liq, liq, repaid_assets=repaid_assets)
            if swap is not None:
                swap_meta = (coll, loan, int(seized))
        if swap is None:
            hit = prearm_get(coll, loan, int(seized))
            swap = hit["swap"] if hit is not None else None
        if swap is None and SPEC_FIRE_PARTIAL:
            from chain.execute import route_max_in
            cap = route_max_in(coll, loan)        # дробление (01.08): сейз сверх ёмкости пула
            sp = partial_shares_for_cap(repaid_shares, seized, cap) if cap is not None else 0
            if sp > 0:
                ap = to_assets_up(sp, tba, tbs)
                # #74 хвост (ревьюер 09.08): ЧАСТИЧНАЯ ветка осталась на оценке СВЕРХУ, хотя
                # главная уже считала по канону — а `zp` уходит в amount_in свопа, и контракт
                # аппрувит РОВНО фактический баланс. Замер на ките: +2 wei. Мало, но инварианта
                # «оценка <= факт» в пути доски нет, и спасает нас сейчас лишь направление
                # дрейфа цены между армом и выстрелом, а не код.
                zp = _seized_exact(sp, _lif_wad, int(price), tba, tbs)
                sw = direct_swap(coll, loan, zp, liq, liq, repaid_assets=ap)
                if sw is not None:
                    self._log("SPECFIRE probe partial %s/%s: сейз %d > кап %d — режем до "
                              "%d shares" % (mid[:10], borrower[:10], seized, cap, sp))
                    repaid_shares, repaid_assets, seized, swap = sp, ap, zp, sw
                    swap_meta = (coll, loan, int(zp))
        if swap is None:
            return None                           # ни роута, ни прогретой квоты — пробу НЕ строим
        min_profit = int(repaid_assets) * SPEC_FIRE_MIN_PROFIT_BPS // 10000
        calldata = encode_liquidate(mp, borrower, repaid_shares, swap["router"],
                                    swap["calldata"], min_profit)
        # v5 доска: сырые компоненты того же выстрела + порог цены оракула-обёртки.
        # Morpho здоров, пока collateral*price*lltv >= borrowed*1e36*1e18, значит граница
        # price = borrowed*1e54/(collateral*lltv). Долг РАСТЁТ с начислением, т.е. настоящая
        # граница со временем ползёт ВВЕРХ — замороженный порог занижается и начал бы гасить
        # огонь (fail-closed). Поэтому запас: фильтр чуть свободнее правды, лишняя проба
        # дешевле пропущенного приза.
        trigger = 0
        try:
            if coll_amt and lltv_wad:
                # #77 (09.08, находка ревьюера): порог считался из repaid_assets — величины
                # ПЛАНА, а не позиции. В частичной ветке repaid_assets переприсвоен на урезанный
                # долг, а coll_amt остался ПОЛНЫМ, и порог проваливался в разы ниже настоящей
                # границы здоровья. Контракт видел px > trig и МОЛЧА выходил: status=1, логов
                # ноль, газ 52k — ни Liquidate, ни PlanFailed. План армирован, флот стреляет,
                # не происходит НИЧЕГО, и диагностировать нечем. Бьёт ровно по классу жира,
                # ради которого доска и строилась (кит $16.5k: trigger 2.64e35 против цены
                # 1.01e36). Граница здоровья Morpho — свойство ВСЕЙ позиции, обе величины
                # полные: price = borrowed*1e54/(collateral*lltv).
                _debt_full = to_assets_up(int(bs), tba, tbs)
                _b = int(_debt_full) * 10**54 // (int(coll_amt) * int(lltv_wad))
                trigger = _b * (10000 + SPEC_FIRE_V2_TRIGGER_MARGIN_BPS) // 10000
        except Exception:
            trigger = 0                           # не посчитали -> 0 = фильтра нет (fail-open)
        return {"calldata": calldata, "gas": int(self.cfg.gas_limit_est * 125 // 100),
                "swap_meta": swap_meta,
                "plan": {"mp": mp, "borrower": borrower, "repaid_shares": repaid_shares,
                         "router": swap["router"], "swap_calldata": swap["calldata"],
                         "min_profit": min_profit, "trigger": int(trigger),
                         # §9 (#133): сырьё для сборщика мультицелевой группы. Все четыре поля
                         # берутся ПОСЛЕ частичной ветки (она переприсваивает seized/repaid_assets
                         # на урезанные zp/ap) — считать запас группы по ДОплановой величине
                         # значило бы котировать размер, которого в свопе нет (класс #77).
                         # Kyber-план (swap_meta is None) поля тоже несёт, но в группу не идёт:
                         # его пул нам не принадлежит, котировать нечего (решает сборщик).
                         "seized": int(seized), "repaid_assets": int(repaid_assets),
                         "coll": coll, "loan": loan}}

    def _consume_cap(self, spent, key, probe):
        """Consume-хук (05.08): ПЕРВАЯ успешная отправка цели списывает её direct-сайз из
        живого капа — резерв «для других» строек (сим каскада 04.08: B ревертил minOut в
        осушенном A пуле). Повторные пробы той же цели не списывают повторно: healthy-реверты
        пул не трогают, а плотный каденс 0.5с обрушил бы кап в ноль за секунды."""
        try:
            sm = probe.get("swap_meta") if isinstance(probe, dict) else None
            if not sm or key in spent:
                return
            from chain.execute import consume_live_cap
            nc = consume_live_cap(sm[0], sm[1], sm[2])
            if nc is not None:
                spent[key] = sm
                self._log("SPECFIRE LIVECAP consume %s->%s: -%d -> %d (%s/%s)" % (
                    sm[0][:8], sm[1][:8], sm[2], nc, key[0][:10], key[1][:10]))
        except Exception:
            pass

    @staticmethod
    def _release_cap(spent, key):
        """Возврат своего резерва перед пересборкой той же цели: свой расход не должен резать
        свой же сайз до партиала. После отправки новой пробы резерв берётся заново."""
        res = spent.pop(key, None)
        if res is not None:
            try:
                from chain.execute import release_live_cap
                release_live_cap(*res)
            except Exception:
                pass

    def _send(self, calldata, gas):
        from chain.execute import send_spec_fire_probe
        from chain.hotpath import _fresh_basefee
        fb = _fresh_basefee()
        tip = _probe_tip_wei(self.cfg.tip_gwei)
        seq = str(getattr(self.cfg, "sequencer_rpc", "") or "")
        bcast = [seq] if (seq and seq.lower() not in ("off", "none", "0")) else None
        return send_spec_fire_probe(self.rpc, self.cfg, calldata, gas, log=log,
                                    max_fee=(fb * 2 + tip) if fb is not None else None, tip=tip,
                                    broadcast_raw_urls=bcast)

    def _receipt(self, h):
        """Ручной полл вместо wait_for_transaction_receipt: его дефолтный poll 0.1с при плотном
        залпе (6-8 сборщиков параллельно) = 60+ req/с в RPC. Раз в RECEIPT_POLL_SEC достаточно —
        Base подтверждает за 2-4с, таймаут ловит только дропы."""
        w3 = self.rpc._web3()
        deadline = self._now() + SPEC_FIRE_RECEIPT_TIMEOUT
        while self._now() < deadline:
            r = None
            try:
                r = w3.eth.get_transaction_receipt(h)
            except Exception:
                pass                              # not found / транспорт — ждём следующий полл
            if r is not None:
                gas_usd = (int(r.get("gasUsed") or 0) * int(r.get("effectiveGasPrice") or 0)
                           * float(self.cfg.eth_price_usd) / 1e18)
                # blk/idx — метрика гонки плотностей: позиция пробы в очереди против
                # транзита/победителя снимается прямо из журнала (ревью 31.07)
                return (int(r.get("status") or 0), gas_usd,
                        r.get("blockNumber"), r.get("transactionIndex"),
                        _receipt_has_win(r, self.cfg.liquidator_address))
            self._sleep(SPEC_FIRE_RECEIPT_POLL_SEC)
        return None

    # ---- выбор жирной цели (top-1 по долгу; та же фид/направление-семантика) ----
    # max_dist (доля, напр. 0.0033): reach-гейт — пропускать цели, чей флип дальше, чем
    # достаёт текущее движение (down: цена залога должна упасть на 1-1/HF; up: долг вырасти
    # на HF-1). Применяется ТОЛЬКО в момент огня — арм окна без гейта, иначе в настоящий
    # каскад окно не запустится вовсе (на арме ret всегда мал по построению).
    def _top_fat(self, feed: str, direction: str, max_dist=None, k=1):
        """-> (top-k список [(mid, b, debt)] по долгу, hold_dist, edge) — hold_dist =
        ближайшая отсечённая гейтом цель; edge = ближайшая-по-dist ДОСЯГАЕМАЯ цель
        (кандидат edge-слота ротации; None = dist ни у кого не вычислим). Пустой
        список = досягаемого жира нет."""
        elig = []
        hold_dist = None
        edge_d, edge_t = None, None
        with self.shared.lock:
            groups = dict(self.shared.groups)
            debt_by = dict(self.shared.debt_by)
            by_id = dict(self.shared.by_id)
            hf_by = dict(getattr(self.shared, "hf_by", {}) or {})
        for mid, borrowers in groups.items():
            m = by_id.get(mid)
            if m is None:
                continue
            cl = _label_of(getattr(m, "collateral_token", ""))
            ll = _label_of(getattr(m, "loan_token", ""))
            if cl == ll or not ((direction == "down" and cl == feed) or (direction == "up" and ll == feed)):
                continue
            # Порог считается ОДИН раз на рынок: бонус — свойство рынка, не цели. Источник тот
            # же, что у гейта жира (_bonus_of/covered-снапшот), но берётся из уже снятого by_id —
            # лишнего захвата лока на каждый рынок не делаем.
            _min_usd = _market_min_repaid_usd(getattr(m, "bonus", 0.0))
            for b in borrowers:
                d = float(debt_by.get((mid, b), 0.0) or 0.0)
                if d < _min_usd:
                    continue
                dist = None
                if max_dist is not None:
                    hf = float(hf_by.get((mid, b), 0.0) or 0.0)
                    if hf > 1.0:                  # HF неизвестен/битый -> fail-open
                        dist = (1.0 - 1.0 / hf) if direction == "down" else (hf - 1.0)
                        if dist > max_dist:
                            if hold_dist is None or dist < hold_dist:
                                hold_dist = dist
                            continue
                    elif 0.0 < hf <= 1.0:         # уже за флипом — ближе кромки не бывает
                        dist = 0.0
                elig.append((mid, b, d))
                if dist is not None and (edge_d is None or dist < edge_d):
                    edge_d, edge_t = dist, (mid, b, d)
        # top-1 по ДОЛГУ. Контракт edge-слота (test_spec_fire_edge_slot): кромка-по-dist
        # отдаётся ОТДЕЛЬНО через edge_t и НЕ ранжирует top-K; незнание HF fail-open — цель
        # остаётся eligible (1c: без hf_by len(tgts)==1). Владельца ОДНОГО слота доски по EV
        # (долг × близость) выбирает арбитр в _prearm_board ПОСЛЕ этого ранга (R2 разрешает
        # post-selection), а ценностной гард #88 — в _arm_board. Здесь ранг чист по долгу.
        elig.sort(key=lambda t: -t[2])
        return elig[:k], hold_dist, edge_t

    def _min_flip_dist(self, feed: str, direction: str):
        """Детонатор: ближайший flip_dist ЖИРНОЙ цели фида — ТА ЖЕ математика, что в
        _top_fat (down: 1−1/HF, up: HF−1; hf<=1 = уже за флипом = 0). None = ни у одной
        цели dist не вычислим (fail-open: порог остаётся универсальным)."""
        best, best_key, best_prize = None, None, 0.0
        with self.shared.lock:
            groups = dict(self.shared.groups)
            debt_by = dict(self.shared.debt_by)
            by_id = dict(self.shared.by_id)
            hf_by = dict(getattr(self.shared, "hf_by", {}) or {})
        for mid, borrowers in groups.items():
            m = by_id.get(mid)
            if m is None:
                continue
            cl = _label_of(getattr(m, "collateral_token", ""))
            ll = _label_of(getattr(m, "loan_token", ""))
            if cl == ll or not ((direction == "down" and cl == feed)
                                or (direction == "up" and ll == feed)):
                continue
            _min_usd = _market_min_repaid_usd(getattr(m, "bonus", 0.0))
            _bonus = float(getattr(m, "bonus", 0.0) or 0.0)
            for b in borrowers:
                _debt = float(debt_by.get((mid, b), 0.0) or 0.0)
                if _debt < _min_usd:
                    continue
                hf = float(hf_by.get((mid, b), 0.0) or 0.0)
                if hf <= 0.0:
                    continue                              # HF неизвестен — эта цель не судит
                dist = 0.0 if hf <= 1.0 else (
                    (1.0 - 1.0 / hf) if direction == "down" else (hf - 1.0))
                if best is None or dist < best:
                    # ПРИЗ цели детонатора (kelbic «го» 26.08): долг × бонус рынка. Нужен
                    # капу — исключение из малого капа даётся ТОЛЬКО настоящим призам.
                    best, best_key, best_prize = dist, (mid, b), _debt * _bonus
        # ОСЕВОЕ РАССЛОЕНИЕ (класс дефектов, назван 26.08): слой-открыватель обязан отдавать
        # ЦЕЛЬ, а не только число — иначе планировщик внизу ищет цель СВОИМ критерием и
        # окно живёт без плана (замер: 135 проб при 29 отказах арма доски подряд).
        _dk_map = getattr(self, "_det_key_by_feed", None)
        if _dk_map is None:
            _dk_map = self._det_key_by_feed = {}      # ленивая карта: прибор не падает на
        _dk_map[feed] = ((best_key, best, self._now(), best_prize) if best_key
                         else None)                    # «голом» объекте; 4-й элемент = ПРИЗ
        return best

    def _det_thr(self, feed: str, direction: str, thr: float):
        """Порог огня окна с детонатор-чувствительностью: min(универсальный, ближайший
        flip_dist), снизу пол шума; кап окон близости в минуту ПЕР-ФИД (линза (2): глобальный
        кап выключал бы детонатор на пике каскада РАЗНЫХ целей — предохранитель против
        дребезга одного фида, не против каскада). -> (порог, dist|None)."""
        if not SPEC_FIRE_DET_SENSE:
            return thr, None
        try:
            d = self._min_flip_dist(feed, direction)
        except Exception:                                # noqa: BLE001
            return thr, None
        if d is None or d >= thr:
            return thr, d
        # ГАРД ОБРАТНОЙ НЕСВЯЗНОСТИ (26.08): детонатор связывает порог ТОЛЬКО если его цель
        # реально планируема — иначе окно открывается ради цели, которую доска не возьмёт, и
        # получаются холостые пробы без плана (замер: 135 проб / 29 отказов арма). Цель
        # планируема, когда у неё есть живой долг в shared (то же условие, по которому доска
        # строит план). Нет цели/долга -> порог остаётся УНИВЕРСАЛЬНЫМ (fail-closed к окну).
        _dk = (getattr(self, "_det_key_by_feed", None) or {}).get(feed)
        if not (_dk and _dk[0]):
            self.stats["det_no_target"] = self.stats.get("det_no_target", 0) + 1
            return thr, d
        try:
            with self.shared.lock:
                _ok = float(self.shared.debt_by.get(_dk[0], 0.0) or 0.0) > 0
        except Exception:                                    # noqa: BLE001
            _ok = False
        if not _ok:
            self.stats["det_unplannable"] = self.stats.get("det_unplannable", 0) + 1
            return thr, d
        n = self._now()
        dq = self.stats.setdefault("_det_win_ts::%s" % feed, [])
        dq[:] = [t for t in dq if n - t < 60.0]
        capped = self.__dict__.setdefault("_det_capped", set())
        if len(dq) >= SPEC_FIRE_DET_WIN_CAP_MIN:
            if feed not in capped:                       # счётчик считает ПЕРЕХОДЫ, не рефреши
                capped.add(feed)
                self.stats["det_win_capped"] = self.stats.get("det_win_capped", 0) + 1
            return thr, d
        capped.discard(feed)
        return max(SPEC_FIRE_DET_NOISE_FLOOR, d), d

    def _det_push_once(self) -> int:
        """Один проход пушера det-dist: свежие flip_dist всех фидов — предиктору (min по
        направлениям; направление судит огневой порог окна). -> сколько фидов запушено."""
        try:
            from chain import predict as _pr
        except Exception:                                # noqa: BLE001
            return 0
        n = 0
        for f in list(self.dev_by):
            try:
                ds = [d for d in (self._min_flip_dist(f, "down"),
                                  self._min_flip_dist(f, "up")) if d is not None]
                if ds:
                    _pr.note_det_dist(f, min(ds))
                    n += 1
            except Exception:                            # noqa: BLE001
                pass
        return n

    def _det_push_loop(self):
        """Линза 22.08 (находка 1): пушер живёт С ПЕРВОЙ СЕКУНДЫ и НЕЗАВИСИМО от ленивого
        движка — детонаторы зреют в ШТИЛЬ (hf дрейфует к 1 часами), и lead предикта
        покупается именно там; пуш из аудита движка молчал бы до первой сборки движка и в
        штиле, а TTL 180с гасил бы сигнал. Период 30с << TTL. time.sleep НАСТОЯЩИЙ
        намеренно: инжектированный фейк self._sleep дал бы busy-loop в стендах."""
        while True:
            try:
                self._det_push_once()
            except Exception:                            # noqa: BLE001
                pass
            time.sleep(30.0)

    def _bonus_of(self, mid: str) -> float:
        """LIF-1 рынка из covered-снапшота (гейт по призу); 0.0 = неизвестен -> долг-гейт."""
        with self.shared.lock:
            m = self.shared.by_id.get(mid)
        return float(getattr(m, "bonus", 0.0) or 0.0)

    def _prio_ok(self, feed: str, claim: float) -> bool:
        """Пакет B (B1): True = слот наш — нет более богатой СВЕЖЕЙ заявки другого окна.
        Ничья -> round-robin по временным слотам DENSE-интервала (детерминированно, без
        координации). Заявки пишутся окнами GIL-атомарными присваиваниями (без лока —
        ноль общих локов с fire-путём, инвариант A4)."""
        if not SPEC_FIRE_SCHED:
            return True
        n = self._now()
        fresh = {f: d for f, (d, ts) in list(self._prio.items()) if n - ts <= SPEC_FIRE_PRIO_TTL_SEC}
        fresh[feed] = claim
        mx = max(fresh.values())
        if claim < mx:
            return False
        tied = sorted(f for f, d in fresh.items() if d >= mx)
        if len(tied) <= 1:
            return True
        return tied[int(n / max(0.25, SPEC_FIRE_DENSE_INTERVAL_SEC)) % len(tied)] == feed

    # ---- П.3 (22.08): коллекторная модель квитанций ОКНА (см. SPEC_FIRE_RCPT_MODE) ----
    def _res_from_receipt(self, r):
        """Кортеж исхода из квитанции — ТА ЖЕ математика, что в _receipt (один источник формы)."""
        gas_usd = (int(r.get("gasUsed") or 0) * int(r.get("effectiveGasPrice") or 0)
                   * float(self.cfg.eth_price_usd) / 1e18)
        return (int(r.get("status") or 0), gas_usd, r.get("blockNumber"),
                r.get("transactionIndex"), _receipt_has_win(r, self.cfg.liquidator_address))

    def _rcpt_coll(self):
        """Коллектор квитанций окна: ОДИН тред партиями вместо треда-на-пробу. Переиспользован
        обстрелянный fire_engine.ReceiptCollector с той же проводкой узлов (bg->D->платный,
        индекс первым #110). Ленивая сборка."""
        col = getattr(self, "_rcpt_col", None)
        if col is not None:
            return col
        with self._lock:
            if getattr(self, "_rcpt_col", None) is None:
                from chain import fire_engine as _fe

                def _combat_url():
                    return getattr(self.rpc, "rpc_url", None)
                self._rcpt_col = _fe.ReceiptCollector(
                    receipts_fn=self._receipts_fn(_combat_url), index_fn=self._index_fn(),
                    on_result=self._rcpt_result, on_timeout=self._rcpt_timeout,
                    timeout_sec=SPEC_FIRE_RECEIPT_TIMEOUT,
                    max_pending=SPEC_FIRE_RCPT_MAX_PENDING, log=self._log)
                self._rcpt_col.start()
            return self._rcpt_col

    def _rcpt_dispatch(self, h, kind, args):
        """Точка ветвления режима: thread — легаси бит-в-бит; collector — очередь;
        shadow — оба на одном хэше (деньги ведёт ЛЕГАСИ, коллектор лишь сверяет исход).
        Переполнение/отказ коллектора в режиме collector НЕ теряет исход — фолбэк
        легаси-тредом (учётный дроп в collector_overflow)."""
        target = self._collect if kind == "probe" else self._collect_volley
        mode = SPEC_FIRE_RCPT_MODE
        if mode not in ("shadow", "collector"):                # thread и любой опечатанный
            threading.Thread(target=target, args=(h,) + args, daemon=True).start()
            return
        if mode == "shadow":
            threading.Thread(target=target, args=(h,) + args, daemon=True).start()
        ok = False
        try:
            ok = self._rcpt_coll().track(
                h, ("shadow" if mode == "shadow" else "live", kind, args, self._now()))
        except Exception as e:                               # noqa: BLE001
            self.stats["collector_dispatch_fail"] = \
                self.stats.get("collector_dispatch_fail", 0) + 1
            self._log("SPECFIRE rcpt-коллектор dispatch fail tx=%s: %s" % (h, type(e).__name__))
        if not ok:
            # Линза 22.08: НЕ один счётчик на два разных факта (омонимия колонки). В shadow
            # переполнение значит лишь «тень не всё сверила» (деньги ведёт легаси-тред,
            # спавнутый выше); в collector — «фолбэк-тред спас исход».
            if mode == "collector":
                self.stats["collector_overflow"] = self.stats.get("collector_overflow", 0) + 1
                threading.Thread(target=target, args=(h,) + args, daemon=True).start()
            else:
                self.stats["rcpt_shadow_dropped"] = self.stats.get("rcpt_shadow_dropped", 0) + 1

    def _rcpt_result(self, meta, h, r):
        src, kind, args, t0 = meta
        lat = self._now() - t0
        ring = self.stats.setdefault("rcpt_lat_ring", [])
        ring.append(lat)
        del ring[:-400]
        res = self._res_from_receipt(r)
        if src == "shadow":
            self._rcpt_shadow_note(h, "коллектор", res[0])
            return
        if kind == "probe":
            self._collect_core(res, h, *args)
        else:
            self._collect_volley_core(res, h, *args)

    def _rcpt_timeout(self, meta, h):
        """TTL-свипер инварианта: квитанция не собрана за таймаут — исход «NO-RECEIPT» по
        худшему случаю (нонс-инвалидация ноги = ресинк её потока) случается РОВНО ОДИН РАЗ."""
        src, kind, args, t0 = meta
        if src == "shadow":
            self._rcpt_shadow_note(h, "коллектор", None)
            return
        if kind == "probe":
            self._collect_core(None, h, *args)
        else:
            self._collect_volley_core(None, h, *args)

    def _rcpt_shadow_note(self, h, who, status):
        """Тень миграции: первый пришедший кладёт исход, второй сверяет. Расхождение — в лог
        и счётчик (деньги не трогаются: их в shadow ведёт только легаси)."""
        with self._lock:
            seen = getattr(self, "_rcpt_shadow_seen", None)
            if seen is None:
                seen = self._rcpt_shadow_seen = {}
            other = seen.pop(h, None)
            if other is None:
                seen[h] = (who, status, self._now())
                # КАП БУФЕРА СВЕРКИ (разбор 26.08): было 512 — и тень НЕ СВЕРИЛА НИ ОДНОЙ
                # пары за сутки. Арифметика: коллектор резолвит за 4-6с, легаси-полл ждёт до
                # SPEC_FIRE_RECEIPT_TIMEOUT (45с), а за эти ~40с в плотном окне проходит
                # 150-600 проб — метка первого вытеснялась ДО прихода второго. Кап поднят до
                # 8192 (память копеечная: кортеж на хэш) + чистка по ВОЗРАСТУ, чтобы буфер не
                # рос без границы при мёртвом втором источнике.
                if len(seen) > 8192:
                    _cut = self._now() - (SPEC_FIRE_RECEIPT_TIMEOUT * 2)
                    for _k in [k for k, v in seen.items()
                               if len(v) > 2 and v[2] < _cut][:4096]:
                        seen.pop(_k, None)
                    while len(seen) > 8192:
                        seen.pop(next(iter(seen)))
                return
        if other[0] == who:                                  # дубль своей же стороны — не суд
            return
        if other[1] == status:
            self.stats["rcpt_shadow_agree"] = self.stats.get("rcpt_shadow_agree", 0) + 1
        elif other[1] is None or status is None:
            # Линза 22.08: КРАЕВОЙ класс, не расхождение — у легаси и коллектора РАЗНЫЕ часы
            # дедлайна (спавн треда vs track+poll+min_age), квитанция у границы таймаута даёт
            # «таймаут vs статус» законно. Судить годность коллектора по счётчику, замусоренному
            # краевыми, нельзя — потому отдельное имя и тихий учёт.
            self.stats["rcpt_shadow_edge"] = self.stats.get("rcpt_shadow_edge", 0) + 1
        else:
            self.stats["rcpt_shadow_diverged"] = self.stats.get("rcpt_shadow_diverged", 0) + 1
            self._log("SPECFIRE RCPT-SHADOW РАСХОЖДЕНИЕ tx=%s: %s=%s %s=%s"
                      % (h, who, status, other[0], other[1]))

    def _collect(self, h, mid, borrower, debt_usd, feed=""):
        """ЛЕГАСИ-обёртка (тред-на-пробу): полл квитанции блокирует тред, исход ведёт core.
        В shadow-режиме записывает свой исход для сверки с коллектором."""
        res = (self._receipt_fn or self._receipt)(h)
        if SPEC_FIRE_RCPT_MODE == "shadow":
            self._rcpt_shadow_note(h, "легаси", res[0] if res else None)
        self._collect_core(res, h, mid, borrower, debt_usd, feed)

    def _collect_core(self, res, h, mid, borrower, debt_usd, feed=""):
        """ДЕНЬГИ исхода пробы главного кошелька: res = кортеж _receipt/_res_from_receipt
        либо None (NO-RECEIPT/таймаут). Ровно один вызов на отправку — инвариант П.3."""
        from chain.execute import specfire_gas_add, mark_recent_send, canary_invalidate_nonce
        if res is None:
            canary_invalidate_nonce(self.rpc, self.cfg)   # дроп? nonce вперёд чейна -> инвалидация
            self._log("SPECFIRE probe NO-RECEIPT tx=%s (nonce инвалидирован)" % h)
            return
        status, gas_usd = res[0], res[1]
        pos = (" blk=%s idx=%s" % (res[2], res[3])) if len(res) >= 4 and res[2] is not None else ""
        specfire_gas_add(gas_usd)
        if status == 1:
            self.stats["wins"] += 1
            mark_recent_send(mid, borrower)               # жертва взята — глушим реактивный дубль
            self._set_cooldown(feed, "probe", proven=True)   # #46: скоуп/триггер — ручками env
            if feed:                                      # приз взят — окно не жжёт кап ревертами
                with self._lock:
                    stop = self._windows.pop(feed, None)
                if stop is not None:
                    stop.set()
            log.warning("SPECFIRE WIN!!! %s/%s debt=$%.0fk tx=%s gas=$%.2f%s — предочередь взята "
                        "(окна на паузе %.0fс)",
                        mid[:10], borrower[:10], debt_usd / 1e3, h, gas_usd, pos,
                        SPEC_FIRE_WIN_COOLDOWN_SEC)
        else:
            self._log("SPECFIRE probe revert (healthy, ожидаемо) tx=%s gas=$%.3f%s" % (h, gas_usd, pos))

    # ---- каскадный тир (07.08): залп той же пробой с залповых EOA ----
    def _cascade_active(self) -> bool:
        """Каскад-флаг тира: армы за час >= порога И свежий факт-флаг — ровно тот же гибрид,
        что у бустера бакета (армы = надежда, факты = подтверждение; калибровка 31.07)."""
        n = self._now()
        return (len([t for t in self._arm_ts if n - t < 3600.0]) >= SPEC_FIRE_CASCADE_WINDOWS
                and _facts_fresh())

    def note_push(self, feed, t=None, updated_at=None):
        """Отметить севший оракульный апдейт: буфер меток кормит фазовый гейт И его же
        онлайн-валидатор. Дедуп 5с — confirmed и push об одном апдейте приходят парой.

        #49 (ревью 08.08): метка обязана стоять на времени ОРАКУЛА (`updatedAt`), а не на
        моменте, когда её увидел наш полл. Полл ходит раз в 4с при толерансе фазы ±2с — метки
        были квантованы грубее самого гейта: доля гэпов на решётке падала до ~0.72 против
        порога 0.80 (фича молча мертва), а при флуктуационном подтверждении фаза уезжала до
        4с и `lattice_skips` глушили огонь в истинную секунду транзита. Хуже всего, что
        валидатор hits/misses мерил теми же смещёнными часами и выглядел здоровым.
        Переводим unix-время оракула в монотонный кадр буфера — сравниваются только разности,
        поэтому кадр обязан быть ОДИН."""
        t = self._now() if t is None else float(t)
        if updated_at:
            try:
                _skew = time.time() - float(updated_at)     # возраст апдейта на момент детекта
            except Exception:
                _skew = None
            if _skew is not None and 0.0 <= _skew <= SPEC_FIRE_LATTICE_MAX_SKEW_SEC:
                t = t - _skew                               # момент САМОГО апдейта
                self.stats["lattice_oracle_ts"] = self.stats.get("lattice_oracle_ts", 0) + 1
            else:
                # часы узла/оракула разъехались — честно живём на времени детекта и говорим
                # об этом: молчаливый фолбэк вернул бы ровно тот дефект, что чиним
                self.stats["lattice_skew_bad"] = self.stats.get("lattice_skew_bad", 0) + 1
        ts = self._push_ts.setdefault(feed, [])
        if ts and t - ts[-1] < 5.0:
            return
        if ts and self._lattice_ready(feed):
            # был ли гейт открыт В СЕКУНДУ ПУША — считаем ДО добавления метки. Это и есть
            # закрытие предела «замер на пуш, а не на приз»: счётчик живой и наш.
            key = "lattice_hits" if self._gate_open(feed, now=t) else "lattice_misses"
            self.stats[key] = self.stats.get(key, 0) + 1
            if key == "lattice_misses":
                self._log("SPECFIRE решётка: пуш feed=%s ВНЕ фазы (+%.1fс от узла) — "
                          "попадания %d, промахи %d" % (
                              feed, (t - ts[-1]) % SPEC_FIRE_LATTICE_P,
                              self.stats.get("lattice_hits", 0),
                              self.stats.get("lattice_misses", 0)))
        ts.append(t)
        if len(ts) > 64:
            del ts[:-64]

    def _lattice_frac(self, feed) -> float:
        """Доля гэпов, легших на решётку (±TOL). Считаем ТОЛЬКО по гэпам в пределах горизонта:
        за MAX_AGE фаза уплывает, и такие гэпы не свидетельствуют ни за, ни против."""
        ts = self._push_ts.get(feed) or []
        gaps = [b - a for a, b in zip(ts, ts[1:]) if 0 < b - a <= SPEC_FIRE_LATTICE_MAX_AGE]
        if len(gaps) < SPEC_FIRE_LATTICE_MIN_N:
            return -1.0
        ok = 0
        for g in gaps:
            ph = g % SPEC_FIRE_LATTICE_P
            if min(ph, SPEC_FIRE_LATTICE_P - ph) <= SPEC_FIRE_LATTICE_TOL:
                ok += 1
        return ok / float(len(gaps))

    def _lattice_ready(self, feed) -> bool:
        """Решётка подтверждена НАШИМ потоком: хватает гэпов И доля выше порога. Пока не
        подтверждена — гейт не действует (fail-open), но счётчики уже не считаются."""
        return self._lattice_frac(feed) >= SPEC_FIRE_LATTICE_MIN_FRAC

    def _gate_open(self, feed, now=None) -> bool:
        """Открыт ли фазовый слот. Любое сомнение -> True (стреляем как раньше)."""
        if not SPEC_FIRE_LATTICE_GATE:
            return True
        ts = self._push_ts.get(feed) or []
        if not ts or not self._lattice_ready(feed):
            return True                                   # решётка не доказана нашим потоком
        age = (self._now() if now is None else now) - ts[-1]
        if age < 0 or age > SPEC_FIRE_LATTICE_MAX_AGE:
            return True                                   # фаза уплыла — гейт снимается
        ph = age % SPEC_FIRE_LATTICE_P
        return min(ph, SPEC_FIRE_LATTICE_P - ph) <= SPEC_FIRE_LATTICE_TOL

    def _board_ready(self, mid, b) -> bool:
        """Доска армлена ИМЕННО под эту цель и ещё жива? Только тогда 1-байт проба осмысленна."""
        if not SPEC_FIRE_V2_BOARD:
            return False
        st = self._board
        return bool(st and st.get("key") == (mid, b)
                    and self._now() < st.get("until", 0.0))

    def _hf_of(self, mid, b):
        """HF цели из shared (Morpho API). None = ключа нет. Одиночный get под GIL — без лока
        (порядок shared.lock->_board_lock в файле не встречается, обратной вложенности нет)."""
        return (getattr(self.shared, "hf_by", {}) or {}).get((mid, b))

    def _arm_board(self, probe, mid, b, feed, debt=0.0, direction=None) -> bool:
        """Записать armed-план в контракт (owner-tx с главного кошелька). Возврат: доска готова?

        Вызывается ЗАРАНЕЕ (пока окно взведено, но горячая фаза не началась) — плану надо сесть
        в блок ДО того, как полетят однобайтовые ноги, иначе они бьют в пустую доску.
        Идемпотентно: если та же цель уже армлена и не протухла — молчим. Любая осечка = False,
        и залп уходит по V1 с полной калдатой (деградация, а не отказ от огня)."""
        if not SPEC_FIRE_V2_BOARD or not isinstance(probe, dict):
            return False
        plan = probe.get("plan")
        if not plan:
            return False
        if not self._board_lock.acquire(blocking=False):
            return self._board_ready(mid, b)      # другой поток уже пишет — не толкаемся
        try:
            if self._board_ready(mid, b):
                st = self._board
                if self._now() - st.get("armed_ts", 0.0) < SPEC_FIRE_V2_REARM_SEC:
                    return True                   # свежая и та же цель — переписывать нечего
            # --- ЦЕННОСТНОЙ ГАРД #88 + ГИСТЕРЕЗИС (пакет B1) ---
            # Один слот доски арбитрируется по EV (долг × близость к флипу), а не «кто последний».
            # Живого владельца НЕ вытесняет: (а) план с нечитаемым HF (незнание не вытесняет);
            # (б) читаемый план, не превосходящий инкумбента на порог SPEC_FIRE_V2_EV_MARGIN
            # (демпфер флапа: 0.1%-качели EV не молотят setPlan). Порог — доля EV ИНКУМБЕНТА
            # (subject-scaled, канон gate-input-from-subject). Протухшего (за until) вытесняет
            # любой свежий — иначе труп заклинил бы слот навечно (A1). Штатные смены слота
            # (_clear_board/_verify_board/_arm_retry) идут мимо этой ветки. Учёта/Thread здесь
            # нет — EV обеих сторон считается _plan_ev_val сбоку от денежного пути (dict-get
            # + арифметика, без Thread). direction сюда НЕ прокидывается: сигнатуру
            # _arm_board(p,m,b,f,debt=0.0) пинят юнит-стабы prearm (test_prearm_warm_and_reach
            # :48, test_prearm_publishes_board:40, test_board_gone_and_warm:105,
            # test_board_arm_retry:34, test_fire_engine:298 + их зеркала redstand/) — они
            # подменяют метод лямбдой БЕЗ параметра direction, и прокидка direction= сорвала
            # бы их TypeError. Поэтому и plan_ev челленджера (:1108), и _inc_ev инкумбента
            # считаются в ОДНОМ базисе direction=None (down-формула _flip_dist). РЕЗ р-2:
            # прежняя лемма «ранг EV инвариантен к направлению» ЛОЖНА — алгебраически
            # ev_down = hf × ev_up (пер-целевой множитель hf), порядок НЕ сохраняется
            # (контрпример: A debt 0.5/hf 1.05, B debt 4.75/hf 1.5 — up-порядок A>B,
            # down-порядок B>A). Но раз ОБА сравниваемых EV в одном базисе, сравнение
            # внутри слота самосогласовано. Остаточный перекос — лишь при контенции слота
            # разнонаправленными фидами (up-цель против down-цели): их истинные базисы
            # различаются, а хранимого direction инкумбента в _board нет, чтобы свести их
            # точно. Редкий кейс (один слот, противоположные стороны), назван в named_limits.
            plan_ev = _plan_ev_val(debt, self._hf_of(mid, b), direction)
            _st = self._board
            if (_st and _st.get("key") and _st.get("key") != (mid, b)
                    and self._now() < _st.get("until", 0.0)):
                # РЕЗ #88 (раунд-2): EV инкумбента ПЕРЕСЧИТЫВАЕТСЯ ЖИВЫМ, а не читается из
                # _st["ev"] — замороженного в момент арма якоря. Инкумбент дрейфует к своему
                # флипу (или от него) весь TTL ~870с; замороженный EV арм-момента заклинивал
                # слот против свежего top-1 (арм при HF 1.001 морозил ev≈1.001e9, при дрейфе к
                # HF 1.05 живой EV падает ~48x, а челленджер с реально бóльшим EV блокировался —
                # регресс против base-LWW, трекавшего fattest каждые 240с). Пересчёт по тому же
                # `direction`, что и plan_ev челленджера (см. блок гарда) — единый базис
                # сравнения. Живой None инкумбента (shared.hf_by опустел) падает в ту же матрицу
                # незнания: unknown-vs-unknown -> перезапись; читаемый челленджер vs
                # теперь-нечитаемый инкумбент -> перезапись (обе ветки ниже — новой семантики нет).
                _inc_ev = _plan_ev_val(_st.get("debt"), self._hf_of(*_st["key"]), direction)
                if plan_ev is None:
                    # Незнание близости не вытесняет ИЗВЕСТНО-ценного владельца (канон
                    # «незнание закрывает гард»). НО если EV инкумбента ТОЖЕ None
                    # (напр. shared.hf_by пуст — легальное состояние, тот же защитный
                    # getattr, что и на base), ценностной основы предпочесть застоявшийся
                    # слот НЕТ: держать его весь until (~870с) против свежего top-1 — регресс
                    # против base, который трекает fattest каждые 240с (LWW). Оба EV неизвестны
                    # → проваливаемся в перезапись (base-трекинг), а не морозим слот на until.
                    if _inc_ev is not None:
                        return True
                elif _inc_ev is not None and plan_ev < _inc_ev * (1.0 + SPEC_FIRE_V2_EV_MARGIN):
                    return True               # не лучше живого инкумбента на порог — держим слот
            # --- РАЗВИЛКА v5/v6 (#135). ВЫШЕ неё всё общее (дедуп, гард #88) — расходятся
            # ровно ЗАПИСЬ и её приёмка. При SPEC_FIRE_V6=0 ветка не исполняется вовсе, и
            # ниже идёт прежний тракт v5 бит-в-бит.
            import chain.board_v6 as _v6mod
            if _v6mod.v6_enabled():
                # §9/#133: экстры берутся ИЗ СТЭША и ровно ОДИН РАЗ (pop). Котировки, из которых
                # посчитаны их minOut, сняты прогревом секунды назад; доехать до ДРУГОГО арма
                # они не имеют права — состав группы пересобирается новым прогоном сборщика.
                #
                # ИДЕНТИЧНОСТЬ ПЛАНА, а не только ключа (mid,b) — линза денежного пути. Два
                # прогрева РАЗНЫХ фидов могут выбрать ОДНОГО владельца; второй перезапишет стэш,
                # и первый принёс бы к СВОЕМУ (мутированному им же) плану ЧУЖИЕ экстры — тогда
                # quote_fn владельца, снятый на своих размерах, встретил бы чужие точки состава
                # и кинул KeyError прямо на пути арма. Стэш несёт id(плана), которому он
                # принадлежит; чужой прогон молча деградирует к n=1 (безопасная сторона).
                _ent = self._group_extra.pop((mid, b), None)
                _extras = _ent[1] if (_ent and _ent[0] == id(plan)) else None
                try:
                    return self._arm_board_v6(plan, mid, b, feed, debt=debt, plan_ev=plan_ev,
                                              extra_plans=_extras)
                except (_v6mod.SamePoolInfeasible, KeyError) as e:
                    # ДВЕРЬ §9 ОТБИЛА ГРУППУ — это отказ АРМА, а не отказ прогрева. Исключение,
                    # выпущенное наверх, вынесло бы вместе с собой хвост `_prearm_board`:
                    # публикацию probe_board (#47) и подъём движка (#78) — то есть один
                    # неудачный расчёт запаса гасил бы и детект транзита, и склад лестниц.
                    self.stats["board_v6_group_refused"] = self.stats.get(
                        "board_v6_group_refused", 0) + 1
                    self.stats["board_fails"] += 1
                    self._log("SPECFIRE v6 ОТКАЗ ДВЕРИ §9 feed=%s %s/%s: %s — арм не сел, "
                              "ретрай штатный" % (feed, str(mid)[:10], str(b)[:10], _diag(e)))
                    return False
            import chain.execute as _ex
            dl = int(time.time()) + SPEC_FIRE_V2_PLAN_TTL_SEC
            cd = _ex.encode_set_plan(
                plan["mp"], plan["borrower"], plan["repaid_shares"], plan["router"],
                plan["swap_calldata"], plan["min_profit"], dl, plan["trigger"])
            # #84 (аудит 10.08) — КОРНЕВОЙ ДЕФЕКТ ВСЕГО ТРАКТА. Прежняя формула
            # `120_000 + 22*байт` была МЕНЬШЕ стоимости самой записи, и арм не садился НИ РАЗУ
            # за всю историю: на боевой калдате 772 Б она даёт лимит 137 006 при estimate
            # 505 718 (×3.69). Проверено на цепи — все 4 setPlan (0x3e73d952, 0xf25f8369,
            # 0x6c6dcc8c, 0x754ec513) имеют status=0 и gasUsed == gasLimit == 137 006 ровно,
            # логов ноль. Наклон 22/байт был взят как «16 калдата + ~6 стораджа», но байт
            # роута ложится в bytes-поле стораджа: холодный SSTORE = 20k на слово, то есть
            # ~625 газа НА БАЙТ, плюс ~12 холодных слотов фиксированных полей (240k).
            # Отсюда: постоянная 300k и наклон 800/байт (запас ~1.8x к замеренному estimate).
            # Щедрый лимит здесь ничего не стоит: по EIP-1559 платим за gasUsed, а не за
            # лимит; цена ошибки в другую сторону — мёртвый тракт, что и было три недели.
            _nb = len(cd) // 2                     # байт калдаты (cd — hex со схемой 0x)
            gas = max(700_000, 300_000 + 800 * _nb)
            h = (self._board_arm_fn or (lambda c, g, tag: _ex.send_board_tx(
                self.rpc, self.cfg, c, g, log=log, tag=tag)))(cd, gas, "setPlan")
            if h is None:
                self.stats["board_fails"] += 1
                return False
            self._board = {"key": (mid, b), "armed_ts": self._now(), "debt": float(debt),
                           # РЕЗ р-2: поле теперь ДИАГНОСТИКА (EV арм-момента для журнала),
                           # гард #88 его больше НЕ читает — инкумбентский EV пересчитывается
                           # живым при каждой контенции слота (см. _inc_ev выше).
                           "ev": plan_ev,
                           # доска считается годной только ПОСЛЕ того, как tx могла сесть;
                           # до этого 1-байт пробы ушли бы в пустоту (плана в сторадже нет)
                           "until": self._now() + SPEC_FIRE_V2_PLAN_TTL_SEC - 30.0,
                           "ready_at": self._now() + SPEC_FIRE_V2_BOARD_SETTLE_SEC,
                           # #84: ХЭШ — НЕ ПОСАДКА. Пока план не прочитан С КОНТРАКТА, доска
                           # не живая: иначе осечка арма хуже отсутствия доски (ноги бьют 1
                           # байтом в пустой сторадж ~840с, а штатная деградация в V1 не
                           # срабатывает, потому что код считает доску исправной).
                           # РЕЗ #110: поля «владелец плана» здесь БОЛЬШЕ НЕТ. Оно жило ровно
                           # для одного читателя — решения «чьё окно гасить при победе», — и
                           # ушло вместе со слоем победы. Доска отвечает на вопрос «какой план
                           # лежит», а не «кто его положил».
                           "verified": False, "tx": h, "dl": int(dl)}
            self.stats["board_arms"] += 1
            threading.Thread(target=self._verify_board, args=((mid, b), feed, h, int(dl)),
                             daemon=True).start()
            self._log("SPECFIRE доска armed feed=%s %s/%s trigger=%s TTL=%dс tx=%s" % (
                feed, mid[:10], b[:10],
                ("%.4g" % (plan["trigger"] / 1e36)) if plan["trigger"] else "нет(fail-open)",
                SPEC_FIRE_V2_PLAN_TTL_SEC, h))
            return True
        except Exception as e:
            self.stats["board_fails"] += 1
            self._log("SPECFIRE доска arm fail feed=%s: %s" % (feed, _diag(e)))
            return False
        finally:
            self._board_lock.release()

    # ==============================================================================================
    # v6-D4 (#135): ГРУППА + ГОРЯЧИЙ УКАЗАТЕЛЬ. Живёт ТОЛЬКО под SPEC_FIRE_V6=1.
    # ==============================================================================================
    def _v6_io(self):
        """(call_fn, send_fn, head_fn, addr) боевого тракта v6. Швы (`_v6_*_fn`) существуют
        для стенда — в бою None, и берётся настоящий транспорт."""
        import chain.execute as _ex
        addr = self.cfg.liquidator_address
        call_fn = self._v6_call_fn or (
            lambda to, data: bytes(self.rpc.eth_call({"to": to, "data": data})))
        send_fn = self._v6_send_fn or (
            lambda cd, gas: _ex.send_owner_tx_v6(self.rpc, self.cfg, cd, gas, log=log, tag="v6"))
        # ГАРД ОТСТАВАНИЯ УЗЛА (#129, боевой урок 16.08): читать состояние с узла, чья голова
        # НИЖЕ блока нашей записи, нельзя — его «нет» это НЕЗНАНИЕ, а не факт. Балансируемый
        # боевой RPC дал два ложных красных за один прогон деплоя. Прокидывается ОБЯЗАТЕЛЬНО:
        # без head_fn модуль читает сразу и трактует отставание как «арм не сел» -> гасит огонь
        # на живой доске.
        head_fn = self._v6_head_fn or (lambda: int(self.rpc.block_number()))
        return call_fn, send_fn, head_fn, addr

    @staticmethod
    def _v6_target(plan):
        """План (сырые компоненты v5) -> ABI-цель v6. §6: дефолт repaidShares (seizedAssets=0),
        то есть заявка ИНВАРИАНТНА к падению оракула — направлению каскада."""
        import chain.board_v6 as _v6mod
        return _v6mod.make_target(
            plan["borrower"], repaid_shares=int(plan["repaid_shares"]),
            swap_target=plan["router"], swap_calldata=plan["swap_calldata"],
            min_profit=int(plan["min_profit"]),
            unwrap_target=plan.get("unwrap_target") or _v6mod.ZERO_ADDR,
            trigger_price=int(plan.get("trigger") or 0))

    # --- §9/#133: СБОРЩИК МУЛЬТИЦЕЛЕВОЙ ГРУППЫ (same-pool) ------------------------------------
    # Каркас §9 стоял целиком (математика худшего порядка, единая дверь, кумулятивный квотер),
    # но extra_plans не заполнял НИКТО — группа всегда была n=1, то есть мультицель существовала
    # только на бумаге. Здесь звено замыкается: кандидаты ТОГО ЖЕ рынка -> котировки одного пула
    # -> minOut каждой цели от ХУДШЕГО порядка -> выпечка в калдату.
    #
    # ГЛАВНОЕ СВОЙСТВО: осечка сборщика безопасна ПО ПОСТРОЕНИЮ. Всё, что он делает, — добавляет
    # цели; отказ на любом шаге возвращает None, дверь §9 при n=1 не спрашивается, и тракт
    # остаётся прежним бит-в-бит. Поэтому весь метод под широким except — но КАЖДЫЙ отказ
    # печатается и считается: тихая деградация к одной цели неотличима от исправной работы.
    def _assemble_group(self, feed, direction, mid, b, owner_probe):
        """(mid,b) владельца слота + его проба -> список ПЛАНОВ экстра-целей (или None).

        Побочный эффект (намеренный): план ВЛАДЕЛЬЦА мутируется по месту — в него кладутся
        ключи двери (pool/amount_in/floor/quote_fn) и перепечённая калдата свопа. Иначе никак:
        дверь читает pools/amounts/floors со ВСЕХ планов группы, а владелец уходит в арм
        отдельным аргументом. Мутация — ПОСЛЕДНИМ шагом и только когда пересборка свопов
        удалась ЦЕЛИКОМ: полу-мутированный владелец (полы записаны, калдата старая) хуже,
        чем отсутствие группы вовсе.
        """
        try:
            import chain.board_v6 as _v6mod
            # (а) ГЕЙТ РЕЖИМА. Константа берётся ИЗ МОДУЛЯ, а не перечитывается из env: у режима
            # один источник истины, и он же читается дверью — разъехаться они не могут. В
            # строгом disjoint-режиме сборщик не стоит НИЧЕГО (ни одного RPC): цели одного рынка
            # делят пул по построению, и дверь отбила бы группу целиком.
            if not _v6mod.v6_enabled():
                return None
            _mode = str(_v6mod.SPEC_FIRE_V6_POOL_MODE or "").strip().lower()
            if _mode != _v6mod.POOL_MODE_SAME_POOL:
                return None
            # (б) KYBER-ВЛАДЕЛЕЦ = СТОП. Его своп идёт агрегатом: путь размазан по нескольким
            # пулам, minOut считает сервер, и пул для §9 НЕИЗВЕСТЕН. Собрав такую группу, мы
            # довели бы до двери план без `pool` — а она обязана отбить это ГРОМКО, то есть
            # осечка арма на живом окне. Отказываемся здесь, где это стоит одну строку журнала.
            if owner_probe.get("swap_meta") is None:
                self.stats["group_skipped_kyber_owner"] = self.stats.get(
                    "group_skipped_kyber_owner", 0) + 1
                self._log("SPECFIRE §9 группа НЕ собрана %s: владелец идёт через Kyber-агрегат — "
                          "пул неизвестен, запас худшего порядка считать не из чего" % mid[:10])
                return None
            owner_plan = owner_probe.get("plan") or {}
            # ВЛАДЕЛЕЦ БЕЗ ГРАНИЦЫ ЗДОРОВЬЯ — ТОЖЕ СТОП, и по той же причине, что и экстра:
            # gate группы обнуляется ЛЮБЫМ нулевым триггером, а gate==0 выключает чтение цены
            # для ВСЕХ целей спана. Одиночная доска такое переживает (лишняя проба), группа —
            # нет. Проверка стоит ЗДЕСЬ, до всякой RPC-работы.
            if int(owner_plan.get("trigger") or 0) <= 0:
                self.stats["group_skipped_no_trigger"] = self.stats.get(
                    "group_skipped_no_trigger", 0) + 1
                self._log("SPECFIRE §9 группа НЕ собрана %s: у владельца нет границы здоровья "
                          "(trigger=0) — gate группы обнулится и погасит фильтр цены ВСЕЙ "
                          "группы; арм идёт одной целью" % mid[:10])
                return None
            coll, loan = owner_plan.get("coll"), owner_plan.get("loan")
            if not coll or not loan or not owner_plan.get("seized"):
                self.stats["group_skipped_no_extras"] = self.stats.get(
                    "group_skipped_no_extras", 0) + 1
                self._log("SPECFIRE §9 группа НЕ собрана %s: в плане владельца нет сырья "
                          "(coll/loan/seized) — старая проба под новым сборщиком" % mid[:10])
                return None
            # (в) КАНДИДАТЫ ТОГО ЖЕ РЫНКА. `_top_fat` НЕ трогаем: его контракт (top-1 по долгу +
            # отдельная кромка) запинен test_spec_fire_edge_slot, и расширять его под группу
            # значило бы менять арбитраж ОДНОГО слота ради состава группы. Отдельный проход:
            # снимок под локом, фильтр и ранг — вне лока (ноль общих локов с fire-путём, A4).
            with self.shared.lock:
                borrowers = list(self.shared.groups.get(mid) or [])
                debt_by = dict(self.shared.debt_by)
                hf_by = dict(getattr(self.shared, "hf_by", {}) or {})
            _min_usd = _market_min_repaid_usd(self._bonus_of(mid))
            cands = []
            for b2 in borrowers:
                if b2 == b:
                    continue
                d2 = float(debt_by.get((mid, b2), 0.0) or 0.0)
                if d2 < _min_usd:                 # тот же пер-рыночный безубыток, что и в _top_fat
                    continue
                ev2 = _plan_ev_val(d2, hf_by.get((mid, b2)), direction)
                # None-EV (HF нечитаем) — в НИЖНИЙ бакет, а не в отказ: незнание близости не
                # обязано выкидывать жирную цель из группы, но и вперёд известной её не пускает.
                cands.append((0 if ev2 is None else 1, float(ev2 or 0.0), d2, b2))
            cands.sort(key=lambda t: (-t[0], -t[1], -t[2]))
            cands = cands[:7]                     # <=8 целей в группе: владелец + 7 (индексы 0..7)
            # (г) СБОРКА ЭКСТР. Kyber-цели отсеиваются по той же причине, что и Kyber-владелец.
            extras = []                           # [(ev_rank, ev, plan)]
            for _k, ev2, d2, b2 in cands:
                p2 = (self._build_fn or self._build)(mid, b2, d2)
                if not isinstance(p2, dict):
                    continue                      # "gone"/None — цели нет либо не собралась
                if p2.get("swap_meta") is None:
                    continue
                pl2 = p2.get("plan") or {}
                if not pl2.get("seized") or not pl2.get("repaid_assets"):
                    continue
                # Идентичность прямого роута: группа котируется ОДНИМ пулом, и цель с другой
                # парой токенов в этой таблице квот не считается вовсе (один рынок ⇒ одна пара,
                # но проверка стоит один сравнительный if, а её отсутствие — неверный запас).
                if str(pl2.get("coll", "")).lower() != str(coll).lower() or \
                        str(pl2.get("loan", "")).lower() != str(loan).lower():
                    continue
                # СЛЕПАЯ ЦЕЛЬ ОТРАВЛЯЕТ ВСЮ ГРУППУ (линза денежного пути). Гейт группы в
                # `_arm_board_v6` = 0, если хоть у одной цели trigger==0 (fail-open на уровне
                # ОДНОЙ цели), а контракт при gate==0 не читает цену ВООБЩЕ — и тогда
                # ПЕРСОНАЛЬНЫЕ триггеры остальных целей тоже не применяются (`pxKnown` ложь).
                # Одна цель без границы здоровья превращает 110 ног в молотилку по здоровым
                # позициям всей группы. В одиночной доске цена этого решения — одна лишняя
                # проба, в группе — вся группа.
                if int(pl2.get("trigger") or 0) <= 0:
                    continue
                extras.append((_k, ev2, pl2))
            if not extras:
                self.stats["group_skipped_no_extras"] = self.stats.get(
                    "group_skipped_no_extras", 0) + 1
                self._log("SPECFIRE §9 группа НЕ собрана %s: кандидатов рынка %d, годных экстр 0 "
                          "— арм идёт одной целью" % (mid[:10], len(cands)))
                return None
            # (д)-(е) КОТИРОВКИ И РАСЧЁТ. Состав может УРЕЗАТЬСЯ: цель, не выживающая худший
            # порядок, ВЫНОСИТСЯ из группы, а не отправляется в реверт по minOut. Смена состава
            # = НОВЫЙ квотер: таблица квот снята ровно в точках {T, T−aᵢ, aᵢ} этого состава, и
            # старый qf на новых точках кинет KeyError (это его контракт, а не дефект).
            from chain.route_depth import make_cumulative_quote_fn
            # ЗАПАС (линза денежного пути). ПОЧЕМУ НЕ 0: котировки снимаются ПРОГРЕВОМ, когда
            # цель ещё ЗДОРОВА, а огонь идёт ПОСЛЕ просадки за триггер — просадка не шум, она
            # систематична и по масштабу равна арм-расстоянию (300-450 bps). При hr=0 весь
            # допуск между worst и полом (14-137 bps на замерах) съедается этой просадкой, и
            # ВЗЯТАЯ гонка превращается в реверт по minOut: приз мимо, газ сожжён. Реверт хуже
            # тонкой прибыли — прибыль стережёт minProfit КОНТРАКТА, а не minOut роутера.
            # ПОЧЕМУ 1300: это больше максимального бонуса карты роутов (12.68%, cbLTC/cbDOGE),
            # то есть клэмп `max(floor, worst*(1-hr))` связывает ВЕЗДЕ и minOut садится ровно на
            # пол — сегодняшнюю боевую семантику. Вся ценность §9 при этом цела: она в ВЫНОСЕ
            # целей, у которых `worst < floor`, а этот критерий от hr не зависит вовсе.
            # Отрицательное значение подняло бы minOut ВЫШЕ worst (запас наоборот) — режем.
            hr = max(0, int(os.environ.get("SPEC_FIRE_SAME_POOL_HEADROOM_BPS", "1300")))
            plans, qf, rows = [owner_plan] + [e[2] for e in extras], None, None
            while True:
                amounts = [int(p["seized"]) for p in plans]
                floors = [int(p["repaid_assets"]) + int(p.get("min_profit") or 0) for p in plans]
                qf = make_cumulative_quote_fn(self.rpc, coll, loan, amounts)
                if qf is None:
                    # НЕТ РОУТА либо молчит транспорт. Это НЕЗНАНИЕ, а не «запас нулевой»:
                    # отдельный счётчик от infeasible намеренно — первое чинится сетью/картой
                    # роутов, второе есть факт о глубине пула.
                    self.stats["group_skipped_quotes_none"] = self.stats.get(
                        "group_skipped_quotes_none", 0) + 1
                    self._log("SPECFIRE §9 группа НЕ собрана %s: котировок %s->%s НЕТ (роут "
                              "агрегатный либо транспорт молчит) — арм одной целью"
                              % (mid[:10], str(coll)[:8], str(loan)[:8]))
                    return None
                try:
                    rows = _v6mod.same_pool_min_outs(amounts, qf, floors=floors, headroom_bps=hr)
                except _v6mod.SamePoolInfeasible as e:
                    # Ступень, которую пул НЕ ТЯНЕТ, ревертит у квотера -> None в таблице ->
                    # отказ. Отдельного гарда «суммарный кап пула» здесь нет и не нужно: §9
                    # закрывает его по построению, а дубль-гард со своей формулой разъехался бы
                    # с настоящей глубиной.
                    self.stats["group_skipped_infeasible"] = self.stats.get(
                        "group_skipped_infeasible", 0) + 1
                    self._log("SPECFIRE §9 группа НЕ собрана %s: расчёт худшего порядка "
                              "невозможен (%s)" % (mid[:10], _diag(e)))
                    return None
                bad = [i for i, r in enumerate(rows) if not r["ok"]]
                if not bad:
                    break
                # Кого выносить. Владельца — НИКОГДА (слот доски выбран арбитром EV выше, и
                # менять его состав группы не вправе). Из экстр берём ХУДШУЮ ПО EV среди
                # непроходных; если непроходной оказался только владелец — худшую по EV вообще
                # (вынос любой соседки поднимает его худший выход: конкурентов за глубину меньше).
                rem = [i for i in bad if i > 0] or list(range(1, len(plans)))
                if not rem:
                    self.stats["group_skipped_infeasible"] = self.stats.get(
                        "group_skipped_infeasible", 0) + 1
                    self._log("SPECFIRE §9 группа НЕ собрана %s: даже одиночный владелец не "
                              "выживает собственный пол — группы нет" % mid[:10])
                    return None
                worst = min(rem, key=lambda i: (extras[i - 1][0], extras[i - 1][1]))
                self._log("SPECFIRE §9 %s: цель %s не выживает худший порядок (выход %s < пола "
                          "%s) — ВЫНОСИМ из группы, пересчёт на составе %d"
                          % (mid[:10], str(plans[worst].get("borrower"))[:10],
                             rows[worst]["worst_out"], rows[worst]["floor"], len(plans) - 1))
                plans.pop(worst)
                extras.pop(worst - 1)
                if len(plans) < 2:
                    self.stats["group_skipped_infeasible"] = self.stats.get(
                        "group_skipped_infeasible", 0) + 1
                    self._log("SPECFIRE §9 группа НЕ собрана %s: после выносов остался один "
                              "владелец — мультицели нет" % mid[:10])
                    return None
            # (ж) ВЫПЕЧКА minOut В КАЛДАТУ. Сперва СОБИРАЕМ все свопы и только потом пишем: живой
            # кап роута мог сжаться между стройкой пробы и этим моментом (consume_live_cap), и
            # direct_swap законно вернёт None — половинчатая мутация владельца была бы хуже
            # отсутствия группы.
            from chain.execute import direct_swap
            liq = self.cfg.liquidator_address
            baked = []
            for p, r in zip(plans, rows):
                sw = direct_swap(coll, loan, int(p["seized"]), liq, liq,
                                 repaid_assets=int(p["repaid_assets"]), min_out=int(r["min_out"]))
                if sw is None:
                    self.stats["group_skipped_infeasible"] = self.stats.get(
                        "group_skipped_infeasible", 0) + 1
                    self._log("SPECFIRE §9 группа НЕ собрана %s: своп с групповым minOut не "
                              "пересобрался для %s (кап роута сжался?) — арм одной целью"
                              % (mid[:10], str(p.get("borrower"))[:10]))
                    return None
                baked.append(sw)
            # (з) КЛЮЧИ ДВЕРИ — В КАЖДЫЙ план, включая владельца: дверь читает pools/amounts/
            # floors со ВСЕХ планов и падает на первом же None. `quote_fn` — только у plans[0]
            # (владельца), таким её и читает дверь; он же соответствует ФИНАЛЬНОМУ составу.
            pool_key = ["%s->%s" % (str(coll).lower(), str(loan).lower())]
            for p, r, sw in zip(plans, rows, baked):
                p["router"], p["swap_calldata"] = sw["router"], sw["calldata"]
                p["pool"] = list(pool_key)
                p["amount_in"] = int(r["amount_in"])
                p["floor"] = int(r["floor"])
            plans[0]["quote_fn"] = qf
            # ВЛАДЕЛЬЦУ НЕ ПЕРЕСОБИРАЕМ probe["calldata"] (полная V1-калдата запасного пути)
            # НАМЕРЕННО: V1 стреляет ОДНОЙ целью, и одиночная семантика minOut=долг там верна.
            # Групповой пол в одиночном выстреле лишь ужесточил бы условие без причины.
            self.stats["group_assembled"] = self.stats.get("group_assembled", 0) + len(plans)
            self._log("SPECFIRE §9 группа собрана %s: целей %d (владелец %s + %d), пул %s, "
                      "minOut от худшего порядка=[%s] запас=%dbps"
                      % (mid[:10], len(plans), str(b)[:10], len(plans) - 1, pool_key[0],
                         " ".join(str(r["min_out"]) for r in rows), hr))
            return plans[1:]
        except Exception as e:
            # Деградация к n=1 безопасна (дверь §9 при одной цели не спрашивается), но МОЛЧА
            # деградировать нельзя — иначе мультицель «работает» на группе из одного.
            self._log("SPECFIRE §9 сборщик группы упал %s: %s — арм идёт одной целью"
                      % (str(mid)[:10], _diag(e)))
            return None

    def _arm_board_v6(self, plan, mid, b, feed, debt=0.0, plan_ev=None, extra_plans=None):
        """§2-§4: заармить ГРУППУ и навести на неё горячий указатель. Возврат: доска готова?

        Отличия от v5-ветки, каждое из ТЗ:
          * пишется ГРУППА (`setGroup`), а не один план — в ней от 1 до 8 целей ОДНОГО рынка;
          * приёмка синхронная и ПО ЦЕПИ (`verify_arm`/`verify_hot` внутри board_v6): своего
            треда `_verify_board` тут нет и быть не должно — арм признан только чтением;
          * `until` указателя берётся С ЦЕПИ (min дедлайнов спана), а не из наших часов;
          * `head_fn` прокинут, поэтому отставание узла даёт «состояние НЕИЗВЕСТНО», а не
            ложное «арм не сел».

        Зовётся ИЗ-ПОД `_board_lock` и из ФОНОВОГО треда прогрева (`_prearm_board`) — петля
        окна на этих RTT не стоит. НАЗВАННЫЙ ПРЕДЕЛ: путь синхронный, и на зависшем узле он
        держит `_board_lock` до таймаута квитанции; параллельные армы при этом не копятся —
        они видят занятый лок и уходят (`acquire(blocking=False)` выше).
        """
        import chain.board_v6 as _v6mod
        call_fn, send_fn, head_fn, addr = self._v6_io()
        # ГАРД АДРЕСА (§0, шаг 4). Флаг включён, а LIQUIDATOR_ADDRESS остался на v5 — тогда
        # setGroup ушёл бы в fallback v5, приёмка сказала бы «не сел», и три часа искали бы
        # газ вместо опечатки в .env. Один eth_call, отказ ГРОМКИЙ.
        if not _v6mod.is_v6_contract(call_fn, addr):
            self.stats["board_v6_wrong_addr"] += 1
            self.stats["board_fails"] += 1
            self._log("SPECFIRE v6 ОТКАЗ: контракт %s не отвечает на hotInfo() — это НЕ v6. "
                      "SPEC_FIRE_V6=1 при адресе v5: арм не пойдёт, огонь остаётся на V1"
                      % str(addr)[:12])
            return False
        plans = [plan] + list(extra_plans or [])
        targets = [self._v6_target(p) for p in plans]
        # §9: цели одной группы делят пул -> minOut второй посчитан ДО свопа первой. Проверку
        # ведёт board_v6 (два режима, #133); для группы из ОДНОЙ цели вопрос не стоит.
        if len(targets) > 1:
            # §9 (#133). Два режима, дефолт СТРОГИЙ (disjoint). Режим `same-pool` считает
            # minOut каждой цели с запасом на n−1 предыдущих свопов ТОГО ЖЕ пула и требует
            # трёх входов, которых в `plan` сегодня нет: пул цели, размер входа свопа и пол
            # (repaid_assets+minProfit). Их обязан положить СБОРЩИК мультицелевой группы —
            # ключи `pool` / `amount_in` / `floor`. Пусто = отказ ГРОМКИЙ (не тихий v5-minOut).
            _pools = [p.get("pool") for p in plans]
            _amts = [p.get("amount_in") for p in plans]
            _flrs = [p.get("floor") for p in plans]
            _qf = plans[0].get("quote_fn")
            _v6mod.assert_group_min_out_safe(
                _pools, amounts_in=None if any(x is None for x in _amts) else _amts,
                floors=None if any(x is None for x in _flrs) else _flrs, quote_fn=_qf)
        g = int(_v6mod.SPEC_FIRE_V6_GROUP)
        dl = int(time.time()) + SPEC_FIRE_V2_PLAN_TTL_SEC
        # Грубый гейт группы = МАКСИМУМ персональных порогов, но НУЛЬ, если хоть у одной цели
        # порога нет: 0 значит «фильтра нет», и max затёр бы это в запрет для той самой цели,
        # у которой мы не смогли посчитать границу здоровья (fail-open, как в v5).
        _trigs = [int(t[7]) for t in targets]
        gate = 0 if any(x == 0 for x in _trigs) else max(_trigs)
        # §1: перезарядка группы ВНУТРИ живого спана ревертит HotSpanLive (гард в контракте).
        # Штатный путь — снять указатель ПЕРЕД перезарядкой. Читаем состояние, а не гадаем:
        # лишний clearHot стоит tx и nonce общего кошелька.
        try:
            rg0, rcnt, runtil = _v6mod.read_hot_info(call_fn, addr)
            if rcnt and runtil > int(time.time()) and rg0 <= g < rg0 + rcnt:
                self._log("SPECFIRE v6: указатель жив над группой %d — снимаем (clearHot) "
                          "перед перезарядкой" % g)
                send_fn(_v6mod.encode_clear_hot(), 80_000)
        except Exception as e:
            self._log("SPECFIRE v6: hotInfo не прочитан (%s) — перезарядка может законно "
                      "откатиться HotSpanLive" % _diag(e))
        ok, rec, why = _v6mod.arm_group(send_fn, call_fn, addr, g, plan["mp"], dl, gate,
                                        targets, head_fn=head_fn)
        if not ok:
            return self._v6_arm_failed(feed, "setGroup", why)
        ok_h, rec_h, why_h, until = _v6mod.set_hot_pointed(send_fn, call_fn, addr, g, 1,
                                                           plan["mp"], head_fn=head_fn)
        if not ok_h:
            return self._v6_arm_failed(feed, "setHot", why_h)
        # Доска признана боевой ТОЛЬКО здесь: обе записи прочитаны с цепи. Поэтому
        # `verified=True` и `ready_at=сейчас` — окна оседания вслепую (v5) больше нет,
        # мы уже ЗНАЕМ, что сторадж полон.
        _left = max(0, int(until) - int(time.time()))
        self._board = {"key": (mid, b), "armed_ts": self._now(), "debt": float(debt),
                       "ev": plan_ev, "until": self._now() + _left - 30.0,
                       "ready_at": self._now(), "verified": True,
                       "tx": (rec or {}).get("transactionHash"), "dl": int(dl)}
        self._board_v6 = {"g": g, "count": 1, "until": int(until), "dl": int(dl),
                          "mp": plan["mp"],
                          "slots": {(str(mid).lower(), str(t[0]).lower()): (g, i)
                                    for i, t in enumerate(targets)}}
        self.stats["board_arms"] += 1
        self.stats["board_v6_arms"] += 1
        self._log("SPECFIRE v6 доска armed feed=%s g=%d целей=%d %s/%s until=%d (%s; %s)" % (
            feed, g, len(targets), str(mid)[:10], str(b)[:10], until, why, why_h))
        return True

    def _v6_arm_failed(self, feed, step, why):
        """Разбор осечки v6-арма. ТРИ исхода, и мешать их нельзя.

        «состояние НЕИЗВЕСТНО» (узел не дорос до блока нашей записи) — НЕ «арм не сел»: доска
        могла сесть, и объявлять её мёртвой значит гасить огонь на живой. Огонь при этом всё
        равно деградирует в V1 (незнание закрывает гард), но СЧЁТЧИК и ЖУРНАЛ обязаны назвать
        разницу — иначе следующая сессия будет чинить газ вместо балансировщика RPC."""
        unknown = "НЕИЗВЕСТНО" in str(why)
        self.stats["board_v6_unknown" if unknown else "board_v6_unlanded"] += 1
        self.stats["board_fails"] += 1
        self._board = {}
        self._board_v6 = {}
        self._log("SPECFIRE v6 %s feed=%s: %s — %s" % (
            step, feed, why,
            "состояние НЕИЗВЕСТНО, доска снята консервативно, залп по V1" if unknown
            else "не село, залп деградирует в V1"))
        self._arm_retry(feed, "v6 %s: %s" % (step, why))
        return False

    def v6_on_liquidate(self, bn, liq_events):
        """§7: ЧУЖАЯ ПОБЕДА по цели живой группы -> `clearTarget(g,i)`.

        Труп в доске крадёт ~1/n огня группы (ротация старта смягчает, но не отменяет): в v5
        протухшая цель стоила одного плана, в v6 стоит доли ВСЕЙ группы. Источник факта —
        подписчик `Liquidate` фонового индекса (#110/#123), НЕ наш журнал: журнал знает лишь
        про наши отправки, а забрать цель мог кто угодно.

        Зовётся из треда индекса. Всё под except: прибор не имеет права ронять ни индекс, ни
        огонь (канон «прибор висит СБОКУ от денежного пути»)."""
        try:
            import chain.board_v6 as _v6mod
            if not _v6mod.v6_enabled():
                return
            st = self._board_v6 or {}
            slots = st.get("slots") or {}
            if not slots or not liq_events:
                return
            from chain.execute import _is_ours
            call_fn, send_fn, _head_fn, addr = self._v6_io()
            for ev in liq_events:
                if not isinstance(ev, dict):
                    continue                     # мусор не обрывает соседние события
                key = (str(ev.get("mid") or "").lower(), str(ev.get("borrower") or "").lower())
                gi = slots.get(key)
                if gi is None:
                    continue
                caller = str(ev.get("caller") or "")
                if _is_ours(caller, caller, self.cfg):
                    # Взяли САМИ. Цель контракт уже погасил сам (`delete ts[i]` в fallback) —
                    # тратить owner-tx не на что, но из раскладки её убрать надо.
                    # ОГРЫЗОК: это ЛОГ ПРОТОКОЛА с нашим caller — доказательство сильнее
                    # квитанции. Если цель была кап-планом, с этого момента её остаток пыли
                    # читается как труп (chain.hotpath.cap_corpse).
                    try:
                        from chain.hotpath import note_cap_shot_confirmed
                        note_cap_shot_confirmed(key[0], key[1])
                    except Exception:                       # noqa: BLE001
                        pass
                    slots.pop(key, None)
                    continue
                g, i = gi
                rec = send_fn(_v6mod.encode_clear_target(g, i), 80_000)
                slots.pop(key, None)
                self.stats["board_v6_cleared_targets"] += 1
                self._log("SPECFIRE v6 §7 clearTarget(%d,%d) блок %d: цель %s/%s забрал %s "
                          "tx=%s — труп больше не крадёт огонь группы" % (
                              g, i, bn, key[0][:10], key[1][:10], caller[:12],
                              str((rec or {}).get("transactionHash"))[:14]))
        except Exception:
            log.exception("v6 §7 clearTarget: прибор упал (индекс и огонь не затронуты)")

    def _verify_board(self, key, feed, txh, dl):
        """#84: ПОДТВЕРДИТЬ, что план ДЕЙСТВИТЕЛЬНО лежит в контракте.

        Своим тредом — путь огня не платит за это чтение. Отправка идёт без ожидания
        квитанции (латентность), поэтому единственное доказательство посадки — прочитать
        planInfo() с контракта. Три недели `_arm_board` признавал арм по возвращённому хэшу
        и писал «доска armed» на транзакциях, сгоревших по газу: 4 из 4 боевых setPlan имели
        status=0 при gasUsed == gasLimit. Ложноположительный арм ХУЖЕ отсутствия арма."""
        import time as _t
        try:
            _t.sleep(max(1.0, float(SPEC_FIRE_V2_BOARD_SETTLE_SEC)))
            from chain.execute import batch_receipts, read_plan_info
            # #84 хвост (форк-приёмка 10.08): сверки одного borrower МАЛО. Кит держится в
            # top-1 часами, поэтому переарм всегда идёт по ТОЙ ЖЕ цели — и несевший арм
            # засчитывался по ПРЕЖНЕМУ плану того же заёмщика (проверено на стенде:
            # verified=True при том, что setPlan не доехал). Доказательств теперь два, и оба
            # привязаны к НАШЕЙ tx: (а) квитанция нашего хэша со status==1; (б) дедлайн в
            # слоте равен НАШЕМУ dl — прежний план несёт другой, поэтому сверка ловит и
            # чужой слот, и протухший.
            _url = getattr(self.rpc, "rpc_url", "") or ""
            info = None
            landed = None
            for _i in range(3):
                if landed is not True:
                    try:
                        _rc = (batch_receipts(_url, [txh]) or {}).get(txh)
                    except Exception:
                        _rc = None
                    if _rc is not None:
                        _s = _rc.get("status")
                        _s = int(_s, 16) if isinstance(_s, str) else int(_s or 0)
                        landed = (_s == 1)
                info = read_plan_info(self.rpc, self.cfg.liquidator_address)
                if landed and info and int(info[1] or 0) == int(dl):
                    break
                if _i < 2:
                    _t.sleep(1.0)
            st = self._board
            if st.get("key") != key or int(st.get("dl", -1)) != int(dl):
                return                            # доску переписал другой арм — вердикт не наш
            ok = bool(landed and info and int(info[1] or 0) == int(dl)
                      and info[0] and str(info[0]).lower() == str(key[1]).lower())
            if ok:
                st["verified"] = True
                self.stats["board_verified"] = self.stats.get("board_verified", 0) + 1
                self._log("SPECFIRE доска ПОДТВЕРЖДЕНА на цепи feed=%s %s/%s dl=%s tx=%s" % (
                    feed, key[0][:10], key[1][:10], info[1], txh))
                return
            # Не села. Громко и с деградацией: доску снимаем, залп уходит по V1.
            self._board = {}
            self.stats["board_fails"] += 1
            self.stats["board_unlanded"] = self.stats.get("board_unlanded", 0) + 1
            self._log("SPECFIRE доска НЕ СЕЛА feed=%s %s/%s — квитанция=%s ждали dl=%s "
                      "в слоте=%s tx=%s; доска снята, залп деградирует в V1" % (
                          feed, key[0][:10], key[1][:10],
                          {True: "status=1", False: "status=0", None: "нет"}.get(landed),
                          dl, (info[1] if info else None), txh))
            self._arm_retry(feed, "план не подтверждён на цепи")
        except Exception as e:
            # Незнание закрывает гард: не подтвердили — значит не доверяем.
            try:
                if (self._board or {}).get("key") == key:
                    self._board = {}
                    self.stats["board_fails"] += 1
                self._log("SPECFIRE доска: проверка посадки не удалась feed=%s: %s — "
                          "доска снята (незнание = запрет)" % (feed, _diag(e)))
                self._arm_retry(feed, "проверка посадки не удалась")
            except Exception:
                pass

    def _clear_board(self, mid, b, feed, why):
        """#94: СНЯТЬ план с контракта, когда жертву забрали.

        `encode_clear_plan()` был написан и не вызывался НИКЕМ. Последствие дорогое: после
        проигранной гонки план лежит на цепи весь TTL (900с) с УЖЕ ВЫПОЛНЕННЫМ триггером —
        значит фильтр `px > trig` больше не отсекает, и каждая следующая проба ноги проходит
        внутрь и платит полные 445-710k вместо 23 619 холостых. Это и есть механизм, которым
        проигранная гонка выжигает бакет: сценарий не редкий, а базовый (0 побед из 9794).

        Зовём только если доска армлена ИМЕННО под эту цель — чужой план снимать нельзя."""
        st = self._board or {}
        if st.get("key") != (mid, b):
            return False
        try:
            import chain.execute as _ex
            import chain.board_v6 as _v6mod
            if _v6mod.v6_enabled():
                # #135: у v6 функции clearPlan НЕТ ВООБЩЕ — прежняя калдата ушла бы в fallback
                # (4 байта > 1 => revert()) и «снятие доски» было бы молчаливой фикцией.
                # Эквивалент снятия для мультислота — погасить УКАЗАТЕЛЬ: спан гаснет разом,
                # пробы 0xFF становятся no-op'ом на двух SLOAD.
                _cf, _sf, _hf, _addr = self._v6_io()
                rec = _sf(_v6mod.encode_clear_hot(), 80_000)
                h = (rec or {}).get("transactionHash")
                self._board = {}
                self._board_v6 = {}
                self.stats["board_cleared"] = self.stats.get("board_cleared", 0) + 1
                self._log("SPECFIRE v6 доска СНЯТА feed=%s %s/%s (%s) clearHot tx=%s" % (
                    feed, mid[:10], b[:10], why, h))
                return True
            cd = _ex.encode_clear_plan()
            h = (self._board_arm_fn or (lambda c, g, tag: _ex.send_board_tx(
                self.rpc, self.cfg, c, g, log=log, tag=tag)))(cd, 120_000, "clearPlan")
            self._board = {}                  # локально доска мертва независимо от исхода tx
            self.stats["board_cleared"] = self.stats.get("board_cleared", 0) + 1
            self._log("SPECFIRE доска СНЯТА feed=%s %s/%s (%s) tx=%s — план больше не пускает "
                      "пробы внутрь" % (feed, mid[:10], b[:10], why, h))
            return True
        except Exception as e:
            self._board = {}                  # не смогли снять на цепи — хотя бы не стреляем
            self._log("SPECFIRE доска: снятие не удалось feed=%s: %s (локально снята)" % (
                feed, _diag(e)))
            return False

    def _board_live(self, mid, b) -> bool:
        """Доска армлена, ПРОТУХНУТЬ не успела, запись села И ПОДТВЕРЖДЕНА чтением контракта."""
        st = self._board
        return bool(self._board_ready(mid, b) and self._now() >= st.get("ready_at", 0.0)
                    and st.get("verified"))

    def _board_plan_live(self):
        """(mid, b) ЖИВОГО армленного плана (запись успела сесть) или None.

        Ключ права огня движку: keepalive ведётся по цели ПЛАНА, а не по цели текущего тика —
        handoff 07.08 пришёл по $1k-жертве, пока доска держала план по $31k, и проверка по
        цели тика оставила бы движок немым ровно в блоке транзита."""
        k = (self._board or {}).get("key")
        return k if (k is not None and self._board_live(k[0], k[1])) else None

    def _engine_fat_keepalive(self, feed) -> bool:
        """Право огня движку от САМОГО fat-окна (см. SPEC_FIRE_ENGINE_FAT_KEEPALIVE).
        Возврат True = продлили. Зовётся из тика окна и из pending-handoff: огонь ведёт ОКНО,
        а не удача кадансовой пробы — гейт _INFLIGHT глушит пробу главного кошелька на время
        боевой tx, и keepalive из залпа погас бы ровно в горячие секунды каскада."""
        if not SPEC_FIRE_ENGINE_FAT_KEEPALIVE:
            return False
        plan = self._board_plan_live()
        if plan is None:
            return False
        eng = self._engine()
        if eng is None:
            return False
        eng.keepalive(target=(feed, plan[0], plan[1], (self._board or {}).get("debt", 0.0)))
        n = self._now()
        if n - getattr(self, "_fat_ka_logged", 0.0) > 60.0:   # DIAG раз в минуту, не на тик
            self._fat_ka_logged = n
            self._log("SPECFIRE движок: право огня от fat-окна feed=%s план=%s/%s" % (
                feed, str(plan[0])[:10], str(plan[1])[:10]))
        return True

    def _prearm_board(self, feed, direction, dev):
        """Положить план по самой жирной достижимой цели ЗАРАНЕЕ — пока окно взведено, но
        горячая фаза не началась. Именно ради этого запаса времени доска и существует: запись
        успевает сесть, и к моменту огня ноги залпа уже несут 1 байт вместо полной калдаты.
        Крутится в своём треде — петля окна не ждёт RPC сборки."""
        try:
            # #90 (аудит 10.08): ПРОГРЕВ ПЕРВЫМ, до всякого гейта. Прежде все точки создания
            # движка стояли НИЖЕ проверки досягаемости, и безусловного фонового прогрева не
            # было вовсе — значит один и тот же гейт решал и «класть ли план», и «греть ли
            # флот». Осечка означала разом ни доски, ни движка, ни лестниц, ни залпа, а
            # следующая попытка через 240с. Склад и лестницы к цели отношения не имеют:
            # подпись 110 лестниц стоит 28-32с и обязана идти в спокойное время, а не в
            # горячей фазе. Окно уже взведено предиктом — этого достаточно, чтобы греться.
            self._engine()
            # #92: досягаемость считалась как 3xdev от СТАТИЧЕСКОЙ константы фида (BTC 0.30%,
            # ETH 0.45%, альты 1.50%) и не смотрела на живое движение. При сегодняшних
            # расстояниях (BTC 2.01-2.29%, XRP 2.24%) план не клался НИКОГДА. Берём не меньше
            # того порога, которым окно само себя армит: если фид сочтён достойным арма, доска
            # обязана планировать на ту же дистанцию. Откат: SPEC_FIRE_PREARM_MIN_REACH=0.
            reach = max(dev * (SPEC_FIRE_THRESHOLD + SPEC_FIRE_DIST_MARGIN_DEVS),
                        SPEC_FIRE_PREARM_MIN_REACH)
            tgts, _hold, _edge = self._top_fat(feed, direction, max_dist=reach, k=1)
            # СВЯЗНОСТЬ ДЕТОНАТОР→ДОСКА (26.08, класс «осевое расслоение»): если окно открыл
            # ДЕТОНАТОР, доска обязана планировать НА ЕГО ЦЕЛЬ, а не искать свою по «жир ×
            # досягаемость» — иначе окно живёт без плана («без доски флот нем»), что и
            # замерено боем: 135 проб при 29 отказах арма подряд, все «жир вне досягаемости».
            # reach здесь становится СПРАВКОЙ в строке, а не гейтом. Универсальные окна (без
            # детонатора) идут прежней веткой БИТ-В-БИТ. Свежесть ключа 120с — протухший
            # детонатор не имеет права навязывать цель.
            _dk = (getattr(self, "_det_key_by_feed", None) or {}).get(feed)
            if _dk and _dk[0] and (self._now() - _dk[2]) <= 120.0:
                _dmid, _db = _dk[0]
                _ddebt = 0.0
                try:
                    with self.shared.lock:
                        _ddebt = float(self.shared.debt_by.get((_dmid, _db), 0.0) or 0.0)
                except Exception:                            # noqa: BLE001
                    pass
                if _ddebt > 0 and not tgts:
                    self._log("SPECFIRE доска: план ПОД ЦЕЛЬ ДЕТОНАТОРА %s/%s (dist %.3f%%, "
                              "жир вне reach %.2f%% — справка, не гейт)"
                              % (str(_dmid)[:10], str(_db)[:10], (_dk[1] or 0.0) * 100.0,
                                 reach * 100.0))
                    tgts = [(_dmid, _db, _ddebt)]
                    self.stats["board_det_target"] = self.stats.get("board_det_target", 0) + 1
                    self.__dict__.setdefault("_arm_fail_series", {})[feed] = 0
            if not tgts:
                # #92: САМАЯ ЧАСТАЯ ветка отказа была ЕДИНСТВЕННОЙ без переспроса. Попытка одна
                # на окно, в момент t~0, когда |ret| минимален ПО ПОСТРОЕНИЮ, а расписание уже
                # стоит на +240с — то есть цена сходится к цели весь следующий час, а мы больше
                # не смотрим. Осечка сборки ретраилась за 5с, а эта — не ретраилась вовсе.
                self._arm_retry(feed, "жир вне досягаемости (reach %.2f%%)" % (reach * 100.0))
                return
            mid, b, d = tgts[0]
            # --- ПЕР-ФИДНЫЙ ВЫБОР ВЛАДЕЛЬЦА СЛОТА ПО EV (пакет B1) ---
            # _top_fat отдаёт top-1 по ДОЛГУ и, ОТДЕЛЬНО, кромку-по-dist (_edge). Владельца
            # ОДНОГО слота доски выбираем по EV = долг × близость к флипу: близкая к кромке цель
            # с меньшим долгом бьёт далёкий жир (гонка №2 cbXRP: 119 проб ушли в top-по-долгу,
            # флипнулась ближайшая мелочь с 0 проб). Арбитр POST-selection — _top_fat и контракт
            # edge-слота не тронуты. Кромку берём ТОЛЬКО если её EV читаем и СТРОГО выше EV
            # жир-топа: незнание близости (ev=None) в нижний бакет, обе неизвестны → держим жир.
            # `_edge is not None` первым в условии — при пустой кромке (юнит-стабы _top_fat без
            # shared) HF не читаем и AttributeError не возникает. Один getattr HF сбоку от
            # денежного пути: без Thread, без учёта под широким except.
            if _edge is not None and _edge[:2] != (mid, b):
                ev_top = _plan_ev_val(d, self._hf_of(mid, b), direction)
                ev_edge = _plan_ev_val(_edge[2], self._hf_of(_edge[0], _edge[1]), direction)
                if ev_edge is not None and (ev_top is None or ev_edge > ev_top):
                    mid, b, d = _edge
            if self._board_ready(mid, b):
                # HIGH N1 (ревью 09.08): ранний выход стоял ДО публикации probe_board, и после
                # фикса #57 он стал ЖИВЫМ путём — окна 2..N каскада доходят сюда гарантированно
                # (план жив по TTL ~870с ⇒ доска «готова» ⇒ публикация пропущена), а запись
                # первого окна снял его же finally. Освежение отметки раз в 4с не спасает: оно
                # обновляет СУЩЕСТВУЮЩУЮ запись, а её нет. Итог был бы прежний: ws-handoff и
                # pending-tier2 выбрасывают уже пойманный транзит — ровно в окнах, ради которых
                # чинили кулдаун. Публикуем из кэша пробы (сборка не нужна, setPlan не уходит).
                _c = self._board_probe_cache.get((mid, b))
                if _c is not None:
                    self.probe_board[feed] = (mid, b, _c[0], _c[1], _c[2], self._now())
                    # ЧЕЙ ЭТО ПЛАН (блокер C р-6): по этому ключу окно судит свою ПРИЁМКУ (б).
                    # Это ИЗМЕРЕНИЕ и только оно — решений по огню на этом ключе больше нет.
                    self._note_plan_key(feed, mid, b)
                    self._engine()          # склад и прогрев патрона нужны и здесь
                    return
                # кэша нет (рестарт под живым планом) — НЕ выходим: собираем пробу ради
                # публикации; повторного setPlan не будет, дедуп стоит внутри _arm_board.
            # ВИДИМОСТЬ ПОРОГА (#138): применённый порог — величина ПЕР-РЫНОЧНАЯ, и если её не
            # печатать, «почему цель не взяли» будет неотличимо от «цели не было». Одна строка
            # на арм, не на цель. ПРИБОР ВИСИТ СБОКУ: свой try, потому что цена ошибки здесь —
            # не строка в журнале, а весь прогрев (урок 13.08: учёт внутри _prearm_board молча
            # гасил арм; стенды без by_id ловят это первым же прогоном).
            try:
                _bn = self._bonus_of(mid)
                self._log("SPECFIRE порог рынка %s: бонус %s -> кандидат от $%.0f (цель $%.0f)"
                          % (mid[:10], ("%.2f%%" % (_bn * 100)) if _bn else "НЕИЗВЕСТЕН",
                             _market_min_repaid_usd(_bn), d))
            except Exception:                     # noqa: BLE001
                pass
            probe = (self._build_fn or self._build)(mid, b, d)
            # §9/#133: СТЭШ ГРУППЫ СНИМАЕТСЯ ЗДЕСЬ — ДО развилки «проба собралась», а не внутри
            # неё. Иначе есть живой путь протухания: проход N собрал группу, арм придержал слот
            # (дедуп либо ценностной гард #88 — оба выходят ДО pop), проход N+1 получил "gone" и
            # прошёл мимо ветки dict, а следующий арм той же цели вытащил бы квоты возрастом в
            # каденс прогрева. Котировки — величина мгновения; не снять их значит доехать до
            # двери §9 с чужой глубиной.
            self._group_extra = {}
            if not isinstance(probe, dict):
                if probe == "gone":
                    # #78 хвост (ревьюер 09.08): здесь "gone" был неотличим от осечки сборки и
                    # уходил в БЫСТРЫЙ переспрос #57. Но переспрос существует для случая, когда
                    # план МОГ бы встать (сеть моргнула, setPlan не сел), а у цели без долга или
                    # без залога брать нечего ни сейчас, ни через 5с — каденс жжётся зря, и в
                    # журнал идёт неверная причина. Ждём обычного каденса: к следующему проходу
                    # _top_fat выдаст другую вершину.
                    self._log("SPECFIRE доска prearm feed=%s %s/%s: цель мертва (нет долга либо "
                              "залога) — быстрый переспрос не нужен" % (feed, mid[:10], b[:10]))
                else:
                    self._arm_retry(feed, "проба не собралась")
                # #78: склад и прогрев патрона НЕ зависят от того, собралась ли эта цель.
                # Раньше _engine() жил только внутри ветки dict, и одна несобираемая цель на
                # вершине _top_fat (k=1) оставляла пул на пустых лестницах — ~0.8с молчания
                # ровно на старте окна победы, при том что подписывать можно было заранее.
                self._engine()
            if isinstance(probe, dict):
                # §9/#133: МУЛЬТИЦЕЛЬ СОБИРАЕТСЯ ЗДЕСЬ — до арма и в том же фоновом треде
                # прогрева, потому что стоит она RPC (сборка экстр + пачка котировок), а петля
                # окна на этих RTT стоять не должна. Запись КЛАДЁТСЯ только на успех; снятие
                # прошлой стоит выше и безусловно (см. комментарий у `self._group_extra = {}`).
                _grp = self._assemble_group(feed, direction, mid, b, probe)
                if _grp:
                    # id ПЛАНА в ключе записи: экстры годны только тому объекту плана, который
                    # мутировал этот же прогон сборщика (см. развилку v6 в `_arm_board`).
                    self._group_extra = {(mid, b): (id(probe.get("plan")), _grp)}
                if not self._arm_board(probe, mid, b, feed, debt=d):
                    self._arm_retry(feed, "setPlan не подтвердился")
                # #47: ПУБЛИКУЕМ probe_board уже на прогреве. Раньше он заполнялся ТОЛЬКО при
                # пересборке в горячей фазе (|ret|>=1.0*dev), а pending-detect tier-2 и
                # ws-handoff при пустой доске делают return, ВЫБРАСЫВАЯ уже обнаруженный
                # транзит: в классе каскадов, где оракульный базис держит наш ret ниже порога
                # (cbXRP: оракул -0.50% при ret -0.43%), окно молчало сквозь реальный транзит.
                # Прогрев строит ровно тот же probe-dict — публикация здесь открывает оба
                # детект-пути, не трогая порог огня.
                self.probe_board[feed] = (mid, b, d, probe["calldata"], probe["gas"], self._now())
                self._note_plan_key(feed, mid, b)         # ключ приёмки (б), блокер C р-6
                # кэш пробы под живой план: из него публикуются окна 2..N, не платя за сборку
                self._board_probe_cache = {(mid, b): (d, probe["calldata"], probe["gas"])}
                # СКЛАД НАБИВАЕТСЯ ЗДЕСЬ, а не в первом огне. Движок поднимается лениво, и если
                # ждать первого тика горячей фазы, пул выйдет на пустые лестницы: подписать
                # 5 ног x 40 проб — это ~0.8с молчания ровно на старте окна победы. Арм доски —
                # и есть то самое спокойное время, ради запаса которого доска существует:
                # поднимаем движок вместе с планом, и фоновое пополнение наполняет склад,
                # пока горячая фаза ещё не началась. Стрелять он всё равно не может — права
                # на огонь даёт только keepalive из горячего тика.
                self._engine()
        except Exception as e:
            self._arm_retry(feed, _diag(e))
            self._log("SPECFIRE доска prearm fail feed=%s: %s" % (feed, _diag(e)))

    def _set_cooldown(self, feed, src, proven=False):
        """WIN-пауза по решению владельца (#46): триггер и скоуп — ручками env.

        src: "combat" (наша боевая tx) | "probe" (спек/движок/залп). proven=True означает
        положительное доказательство захвата (Liquidated/repaidAssets>0), а НЕ «status==1» и
        не «uncertain»: фантомная победа, гасящая нас посреди живой возможности, — тот же класс,
        что мёртвый сторож. Возврат: пауза взведена?"""
        if SPEC_FIRE_COOLDOWN_TRIGGER == "combat" and not (src == "combat" and proven):
            return False                          # победа пробы инвентарь не тратит — не гасим
        if SPEC_FIRE_COOLDOWN_TRIGGER != "any" and not proven:
            return False                          # без доказательства захвата паузу не ставим
        until = self._now() + SPEC_FIRE_WIN_COOLDOWN_SEC
        if SPEC_FIRE_COOLDOWN_SCOPE == "global":
            self._cooldown_until = until
        elif feed:
            self._cooldown_feed[feed] = until
        else:
            return False                          # пер-фид без фида гасить нечего
        self._log("SPECFIRE WIN-пауза %s: скоуп=%s src=%s на %.0fс" % (
            feed or "—", SPEC_FIRE_COOLDOWN_SCOPE, src, SPEC_FIRE_WIN_COOLDOWN_SEC))
        return True

    def _cooldown_active(self, feed) -> bool:
        n = self._now()
        if n < self._cooldown_until:              # глобальная пауза (SCOPE=global / откат)
            return True
        return n < self._cooldown_feed.get(feed, 0.0)

    def note_combat_win_by_market(self, mid, borrower, proven=True):
        """#58: диспатч знает рынок и заёмщика, но не фид — резолвим сами.

        Ищем по опубликованной доске и по армленным окнам; не нашли — паузу НЕ ставим (скоуп
        пер-фид, гасить нечего) и говорим об этом, чтобы молчание не читалось как работа."""
        feed = None
        for f, b in list(self.probe_board.items()):
            if str(b[0]).lower() == str(mid).lower():
                feed = f
                break
        if feed is None:
            _k = (self._board or {}).get("key") or ()
            if _k and str(_k[0]).lower() == str(mid).lower():
                feed = next(iter(self._windows), None)
        if feed is None:
            self._log("SPECFIRE WIN-пауза: фид для рынка %s не найден — пауза не ставится"
                      % str(mid)[:10])
            return False
        return self.note_combat_win(feed, proven=proven)

    def note_combat_win(self, feed=None, proven=False):
        """Точка входа боевой победы (#46): зовётся из разбора квитанции БОЕВОЙ tx, когда захват
        подтверждён (repaidAssets>0). proven=False (например, SEND-3 uncertain) паузу НЕ ставит —
        иначе фантом глушил бы нас посреди живой возможности."""
        return self._set_cooldown(feed, "combat", proven=proven)

    def _arm_retry(self, feed, why):
        """#57: осечка арма = быстрый переспрос, а не ожидание каденса 240с. Доска — единственная
        точка входа флота: без севшего плана движок не получает права огня вовсе, а V1-деградация
        сидит за тир-гейтом, ложным в решающий блок. Молчаливая осечка = немой флот при здоровом
        на вид движке, поэтому она ещё и громкая (счётчик виден в close-строке окна)."""
        self._board_next_try[feed] = self._now() + SPEC_FIRE_V2_ARM_RETRY_SEC
        self.stats["board_arm_fails"] = self.stats.get("board_arm_fails", 0) + 1
        # СЧЁТЧИК ПОРОГА РЕШЕНИЯ (26.08): серии отказов арма ПРИ ЖИВОМ ДЕТОНАТОРЕ — это и
        # есть «окно голодает без плана». Порог из Plan: доля таких окон >=30% ⇒ спека.
        try:
            _dk = (getattr(self, "_det_key_by_feed", None) or {}).get(feed)
            if _dk and _dk[0]:
                _ser = self.__dict__.setdefault("_arm_fail_series", {})
                _ser[feed] = _ser.get(feed, 0) + 1
                if _ser[feed] == 5:
                    self.stats["det_windows_starved"] = \
                        self.stats.get("det_windows_starved", 0) + 1
        except Exception:                                    # noqa: BLE001
            pass
        self._log("SPECFIRE доска: арм НЕ ВЗВЁЛСЯ feed=%s (%s) — переспрос через %.0fс "
                  "(без доски флот нем)" % (feed, why, SPEC_FIRE_V2_ARM_RETRY_SEC))

    def _note_collector_fallback(self, why):
        """Страховка сработала — это ГРОМКО. Молчание уже стоило суток: коллектор уходил на
        боевой Alchemy на 100% поллов (замер 12.08: collector_fallback == polls в 134 окнах
        подряд), а в журнале не было ни строки, и по нулю НАШЕГО же счётчика был вынесен
        вердикт «трафик квитанций на Alchemy не наш». Печатаем с прореживанием: при отказе
        узла строка иначе идёт каждую секунду."""
        n = self.stats.get("collector_fallback", 0) + 1
        self.stats["collector_fallback"] = n
        now = self._now()
        last = getattr(self, "_collector_fb_logged", 0.0)
        if now - last < SPEC_FIRE_COLLECTOR_FALLBACK_LOG_SEC and n > 1:
            return
        self._collector_fb_logged = now
        self._log("SPECFIRE коллектор: партия уведена на БОЕВОЙ узел — %s (узел=%s, "
                  "срабатываний %d). Увод #99 в этот момент не работает: квитанции жгут "
                  "платную квоту" % (why, _collector_node_kind(), n))

    def _receipts_fn(self, combat_url):
        """Шов квитанций для коллектора. МЕТОД, а не замыкание внутри _engine: замыкание
        нельзя позвать из теста, и приёмка сползала на пересказ боевой ветки."""
        from chain import execute as _ex
        return lambda hs: collect_receipts(hs, SPEC_FIRE_COLLECTOR_RPC_URL, combat_url(),
                                           _ex.batch_receipts,
                                           on_fallback=self._note_collector_fallback,
                                           dedicated_chunk=SPEC_FIRE_COLLECTOR_BATCH_CHUNK,
                                           second_url=SPEC_FIRE_COLLECTOR_RPC_URL_2,
                                           second_chunk=SPEC_FIRE_COLLECTOR_BATCH_CHUNK_2,
                                           on_second=self._note_collector_second)

    def _note_collector_second(self, why):
        """22.08: партия спасена ВТОРЫМ бесплатным (ключ D) — платный ключ не тронут. Прибор
        сбоку: счётчик + строка с прореживанием, отказ глотается вызывающим collect_receipts.
        Судит эффект НЕ этот счётчик, а CU-атрибуция после рестарта (свой счётчик слеп)."""
        n = self.stats["collector_second"] = self.stats.get("collector_second", 0) + 1
        now = time.time()
        if now - getattr(self, "_collector_2_logged", 0.0) < SPEC_FIRE_COLLECTOR_FALLBACK_LOG_SEC:
            return
        self._collector_2_logged = now
        self._log("SPECFIRE коллектор: партия спасена бесплатным-2 (D) — %s "
                  "(спасений %d, платный не тронут)" % (why, n))

    def _index_fn(self):
        """Шов ИНДЕКСА ЦЕПИ для коллектора (#110) либо None.

        None — это и есть ручка отката: механизм снимается целиком (индекса не спрашивают
        вовсе), а не подкручивается параметром. Индекс не поднялся / выключен — то же самое.
        """
        if not SPEC_FIRE_COLLECTOR_INDEX:
            return None
        from chain import chain_index as _ci

        def _ask(hs):
            idx = _ci.get_index()
            if idx is None:
                return {}
            got = idx.receipts_for(hs)
            if got:
                self.stats["index_receipts"] = self.stats.get("index_receipts", 0) + len(got)
            return got
        return _ask

    # ---- движок огня (#32, 07.08): постоянный пул вместо порождения залпа на тик ----
    def seed_on_start(self) -> bool:
        """#140: ПОСЕВ СКЛАДА — поднять движок ДО первого окна, а не в нём.

        ЗАМЕР, ради которого это делается: с рестарта 22:16 движок не поднимался НИ РАЗУ —
        8 часов склад пуст при 445 армах предикта и 2502 прогревах PREARM, потому что окно
        spec-fire не армилось («ближ. жир dist > потолок»). Немота длится не «50 минут после
        рестарта», а ДО ПЕРВОГО ОКНА, и детонатор-класс (мгновенный флип cbADA-типа) встречает
        пустой склад плюс 28-32с подписи ровно в горячий момент.

        ЭТО НЕ НОВЫЙ ПУТЬ ПОДПИСИ. Весь посев — «поднять движок раньше»: дальше работает тот
        же фоновый `_refill_loop`, который уступает огню и капнут ENGINE_SIGN_BUDGET за проход.
        Ни одной строки подписи здесь нет и быть не должно.

        ПРАВА ОГНЯ ПОСЕВ НЕ ДАЁТ. Единственный источник права — keepalive горячего тика
        (см. коммент склада в `_prearm_board` и гарды движка): поднятый движок без keepalive
        молчит по построению. Посев трогает СКЛАД, не спусковой крючок.

        ПРИБОР СБОКУ: любая осечка = строка в журнале и деградация к сегодняшней лени (движок
        поднимется первым окном, как и сейчас), но НЕ падение старта.
        """
        if not SPEC_FIRE_SEED_ON_START:
            return False
        try:
            if getattr(self, "_fire_engine", None) is not None:
                return False                      # уже поднят окном/армом — сеять нечего
            eng = self._engine()
            if eng is None:
                self._log("SPECFIRE посев склада: движок выключен (SPEC_FIRE_ENGINE=0) — "
                          "склад остаётся пуст, путь залпа прежний")
                return False
            self._log("SPECFIRE посев склада: движок поднят ПОСЛЕ первого candidate refresh, "
                      "не дожидаясь окна — лестницы подписываются статическими тирами "
                      "(кольца зеркала на старте пусты). Права огня это НЕ даёт: спусковой "
                      "крючок — keepalive горячего тика")
            return True
        except Exception as e:                    # noqa: BLE001
            self._log("SPECFIRE посев склада НЕ УДАЛСЯ (%s) — деградация к прежнему подъёму "
                      "первым окном, старт не затронут" % _diag(e))
            return False

    def _engine(self):
        """Ленивый подъём движка. Выключен -> None, и путь залпа идёт как прежде бит-в-бит."""
        from chain import fire_engine as _fe
        if not _fe.ENGINE_ON:
            return None
        eng = getattr(self, "_fire_engine", None)
        if eng is not None:
            return eng
        with self._lock:
            eng = getattr(self, "_fire_engine", None)
            if eng is not None:
                return eng
            from chain import execute as _ex
            seq = str(getattr(self.cfg, "sequencer_rpc", "") or "")
            bcast = [seq] if (seq and seq.lower() not in ("off", "none", "0")) else None
            rpc_url = getattr(self.cfg, "rpc_url", None) or seq

            def _legs():
                return [a for a, _k in (self._volley_accounts_fn or _ex.volley_accounts)()]

            def _send(addr):
                h = _ex.send_presigned_probe(self.rpc, self.cfg, addr, log=log,
                                             broadcast_raw_urls=bcast)
                if h is not None:
                    # #56: огонь движка был НЕВИДИМ — board_probes не рос, и согласованный
                    # критерий приёмки «board_probes>0 при включённом движке» был недостижим
                    # ПО ПОСТРОЕНИЮ. Считаем там же, где приёмка их ищет.
                    self.stats["board_probes"] = self.stats.get("board_probes", 0) + 1
                    self.stats["engine_probes"] = self.stats.get("engine_probes", 0) + 1
                    # #110: заявляем хэш индексу СРАЗУ при отправке. С этого момента индекс
                    # читает блоки ЦЕЛИКОМ (иначе позицию нашей пробы взять неоткуда) и
                    # запоминает голову цепи — от неё считается право сказать «tx не села».
                    try:
                        from chain import chain_index as _ci
                        _ci.note_hash(h)
                    except Exception:
                        pass
                return h

            # #112 MAJOR-3: слот кэша базы — одна АТОМАРНАЯ ссылка (bf, monotonic_ts). Писатель —
            # _audit (раз в проход), читатели — депт-долив на треде fire-refill И тред входа окна
            # (spec_fire_live._refill зовётся обоими). Один слот исключает рваное чтение.
            self._audit_base_fee = None
            # #127 R2: слот курсора ротации аудита (см. _audit) — рядом с кэшем базы, оба суть
            # состояние прохода аудита. None => первый проход стартует с головы протухшего списка.
            self._audit_resign_cursor = None

            def _refill(addr, base_fee=None):
                # #112 MAJOR-3: депт-долив зовёт БЕЗ base_fee, и presign_ladder тогда делает свой
                # get_block RTT в боевой ключ на КАЖДЫЙ долив (шторм в узкой полосе [39,40] на всю
                # 180с-фазу удержания). Берём базу из кэша аудита, пока свежа (TTL ~блок Base);
                # иначе fail-open — presign_ladder читает свою (корректность важнее экономии).
                if base_fee is None and SPEC_FIRE_BASE_FEE_TTL_SEC > 0:
                    cached = self._audit_base_fee
                    if cached is not None and (
                            time.monotonic() - cached[1]) <= SPEC_FIRE_BASE_FEE_TTL_SEC:
                        base_fee = cached[0]
                for a, k in (self._volley_accounts_fn or _ex.volley_accounts)():
                    if a == addr:
                        _ex.presign_ladder(self.rpc, self.cfg, addr, k,
                                           SPEC_FIRE_V2_FIRE_GAS, base_fee=base_fee, log=log)
                        return

            def _audit(addrs):
                """#63: аудит ЦЕНЫ лестниц. База читается ОДИН раз на весь флот (иначе это
                110 запросов вместо одного — урок квоты 09.08), подпись жжём только у ног,
                чья лестница действительно протухла: вздута (гейт патрона закрыт) либо ниже
                нынешней базы (tx не включаема). Обе формы САМИ останавливают огонь, поэтому
                триггер по глубине склада тут не срабатывает никогда."""
                try:
                    # 20.08 раскидка квот: аудит — фоновое чтение, уходит с боевого ключа
                    bf = int(_ex.volley_bal_read_rpc(self.rpc)._web3()
                             .eth.get_block("latest").get("baseFeePerGas") or 0)
                except Exception as e:
                    self._log("SPECFIRE аудит лестниц: база не прочитана (%s)" % _diag(e))
                    return
                # #112 MAJOR-3: аудит — ПИСАТЕЛЬ кэша базы. Депт-долив читает его вместо своего
                # get_block, поэтому пишем даже когда протухших ног нет (свежая база нужна доливу).
                self._audit_base_fee = (bf, time.monotonic())
                # #91: лестница подписана ПОЛОМ рынка, значит и аудит цены обязан считать по
                # полу. Сверка с боевым cfg.tip_gwei объявила бы протухшими ВСЕ 110 ног разом
                # и запустила бы вечную пересборку — регрессия, пойманная тестом.
                # Ш24: у каждой ноги СВОЙ тир — аудит обязан сверять лестницу с ЕЁ tip,
                # иначе весь флот мерился бы по чужой цене и половина объявлялась протухшей.
                stale = [a for a in (addrs or [])
                         if _ex.ladder_resign_needed(a, bf, _ex.probe_tip_for(a))]
                if not stale:
                    return
                # #127: учёт «пересборка по tip» — строго СБОКУ (свой try; ни подписи, ни
                # отправки, ни лестниц внутри). Сбой прибора не имеет права тронуть пересборку —
                # урок 13.08: счётчик атрибуции внутри _prearm_board молча гасил арм. Ноги со
                # сменившимся tip уже вошли в stale (триггер в execute), здесь только счёт и лог.
                try:
                    _tip_mm = []
                    for a in stale:
                        _have = _ex.ladder_tip(a)
                        _want = _ex.probe_tip_for(a)
                        if _have is None or int(_have) != int(_want):
                            _ex.note_tip_resign(a, _have, _want)
                            _tip_mm.append("%s %s->%d" % (
                                a[:8], _have if _have is not None else "?", _want))
                    if _tip_mm:
                        self._log("SPECFIRE аудит: пересборка по tip у %d ног (%s)"
                                  % (len(_tip_mm), "; ".join(_tip_mm[:5])))
                except Exception:
                    pass
                self._log("SPECFIRE аудит лестниц: %d ног с протухшей ценой (база %.4f gwei) — "
                          "пересборка" % (len(stale), bf / 1e9))
                # #112 MAJOR-1: пересборка серийна и на ОДНОМ ядре монополизировала бы GIL на
                # ~2.08с (110×40 подписей) в решающие 2-4с каскада, лишив CPU воркеров огня и
                # боевой dispatch. Между ногами УСТУПАЕМ ядро явным сном (лока тут не держим —
                # invalidate/presign берут лок ноги внутри). #112 R2: сверх этого — КАП размера
                # бёрста SPEC_FIRE_AUDIT_MAX_RESIGN (дефолт 5 ног = один 200мс-сегмент ядра, вывод
                # у константы @220): один проход трогает <=5 ног, остаток протухших добивается
                # следующими проходами (их лестницы остаются протухшими). 0 = откат к «без капа».
                # #127 R2 (СТАРВАЦИЯ ХВОСТА): при устойчивом дребезге зеркала (мода<->статика<->
                # вторая мода в probe_tip_for) первые SPEC_FIRE_AUDIT_MAX_RESIGN ног списка пере-
                # протухают на КАЖДОМ проходе и кап всегда уходит на них — 105/110 ног не
                # пересобираются НИКОГДА, хвост флота застывает на старом tip (а при экскурсии
                # базы — с невключаемым max_fee). Круговой курсор ПО АДРЕСУ (состав stale
                # плавает, индекс не годится): проход стартует с ноги, СЛЕДУЮЩЕЙ за последней
                # обслуженной в прошлом проходе. Гарантия: устойчиво протухшая нога ждёт
                # пересборки не дольше ceil(N/кап) проходов. Кап и порядок legs_fn (stale
                # строится обходом addrs выше) НЕ тронуты.
                _cursor = getattr(self, "_audit_resign_cursor", None)
                _start = 0
                if _cursor is not None:
                    try:
                        _start = (stale.index(_cursor) + 1) % len(stale)
                    except ValueError:
                        _start = 0            # курсор выпал из протухшего множества — с головы
                order = stale[_start:] + stale[:_start]
                n_resign = 0
                for i, a in enumerate(order):
                    if SPEC_FIRE_AUDIT_MAX_RESIGN > 0 and n_resign >= SPEC_FIRE_AUDIT_MAX_RESIGN:
                        self._log("SPECFIRE аудит: пересобрано %d/%d ног за проход (кап "
                                  "SPEC_FIRE_AUDIT_MAX_RESIGN=%d) — остаток на следующий проход"
                                  % (n_resign, len(stale), SPEC_FIRE_AUDIT_MAX_RESIGN))
                        break
                    if i > 0 and SPEC_FIRE_AUDIT_YIELD_SEC > 0:
                        time.sleep(SPEC_FIRE_AUDIT_YIELD_SEC)   # уступка ядра МЕЖДУ ногами
                    try:
                        _ex.invalidate_ladder(a)      # иначе compat удержит старую цену
                        _refill(a, base_fee=bf)
                        n_resign += 1
                        self._audit_resign_cursor = a   # обслужена — курсор на неё; следующий проход
                        # стартует со СЛЕДУЮЩЕЙ ноги (ротация против старвации хвоста)
                    except Exception as e:
                        self._log("SPECFIRE аудит %s: %s" % (a[:10], _diag(e)))

            def _combat_url():
                # #66: url берём У RPC В МОМЕНТ ВЫЗОВА — failover переключает его на живой
                # узел, а фиксированный на старте адрес держал бы коллектор на мёртвом
                return getattr(self.rpc, "rpc_url", None) or rpc_url

            self._log("SPECFIRE коллектор квитанций: узел=%s (страховка боевым ТОЛЬКО на "
                      "отказе выделенного — иначе брони #93 не снимутся и гейт огня закроется "
                      "на нас; откат SPEC_FIRE_COLLECTOR_FALLBACK_ON_EMPTY=1)"
                      % _collector_node_kind())
            col = _fe.ReceiptCollector(
                receipts_fn=self._receipts_fn(_combat_url),
                index_fn=self._index_fn(),
                on_result=self._engine_result, on_timeout=self._engine_timeout,
                log=self._log)
            eng = _fe.FireEngine(legs_fn=_legs, send_fn=_send, collector=col,
                                 refill_fn=_refill, depth_fn=_ex.ladder_depth,
                                 fleet_warm_fn=lambda addrs: _ex.volley_bal_warm_fleet(
                                     self.rpc, addrs, log=log),
                                 audit_fn=_audit, log=self._log)
            self._fire_engine = eng
            eng.start()
        # П.3/линза: коллектор ОКНА греется на сборке движка, а не лениво в первом dispatch
        # (иначе RTT сборки лёг бы в горячий путь первого выстрела). ВНЕ `with self._lock`
        # НАМЕРЕННО (регрессия 23-26.08, поймана py-spy): _rcpt_coll берёт ТОТ ЖЕ
        # нерекурсивный self._lock — вложенный захват давал САМОДЕДЛОК, лок не отпускался
        # никогда, и predict-driver вставал на нём в первом же handle_event: окна не армились
        # 2.5 суток, флот молчал, работала одна реактивная лента. Лок здесь уже отпущен.
        if SPEC_FIRE_RCPT_MODE in ("shadow", "collector"):
            try:
                self._rcpt_coll()
            except Exception as _e:                          # noqa: BLE001
                self._log("SPECFIRE rcpt-коллектор прогрев fail: %s" % type(_e).__name__)
        return eng

    def _engine_result(self, meta, h, r):
        """ИСХОД ПРОБЫ ПО КВИТАНЦИИ. ДЕНЬГИ В `try`, БРОНЬ #93 — В `finally`.

        ФОРМА ЗЕРКАЛЬНА `_engine_timeout` (L1 р-8) — и это не косметика. Гарантия #93 была
        закрыта только у одного из двух братьев: у пути таймаута снятие брони стоит в
        `finally`, а здесь оно стояло ПОСЛЕ денежного `_probe_win` без всякого `finally`.
        Хэш к этому моменту УЖЕ снят коллектором с `_pending` (`tick` делает `pop` до вызова
        обработчика), поэтому второго шанса нет: таймаут по нему не сработает НИКОГДА. Любой
        бросок в вердикте — шов журнала, `_set_cooldown`, `disarm` — оставлял бронь висеть
        навсегда, а `_VOLLEY_GAS_RESERVED` вычитается из суточного бакета
        `CASCADE_TIER_GAS_USD`: это ровно самозапирание гейта огня, которое код называет
        регрессией #101 («брони не снимаются НИКОГДА -> гейт закрыт до рестарта или полуночи
        UTC»). Гарантия обязана держаться на КАЖДОМ выходе функции, а не на счастливом.

        РАЗБОР ГАЗА ОСТАЛСЯ ПЕРЕД ВЕРДИКТОМ, и это осознанно. Он не учёт, а ВХОД: цена
        печатается в строке победы и она же уходит в ФАКТ расхода. Бросить он не может по
        построению — целиком закрыт своим `except` и на любом отказе даёт нули (вынести из
        этого `except` хоть одну строку значило бы поставить перед вердиктом то, что умеет
        бросать). Зато держать его ЗДЕСЬ, а не внутри вердикта, значит: даже если вердикт
        ляжет, ФАКТ спишется настоящим числом, а не нулём «на всякий случай».
        """
        addr, tgt = (meta or (None, None))
        _wei, gas_usd = 0, 0.0
        try:
            # ОДИН разбор на ОБА источника. Сеть отдаёт '0x...', индекс — тоже (см.
            # chain_index.receipt_like): прежде здесь стоял голый int(), сетевая квитанция
            # падала ValueError, ветка глоталась общим except и газ МОЛЧА книжился нулём —
            # то есть само включение индекса меняло поведение суточного kill-switch.
            from chain.chain_index import rcpt_int
            _wei = rcpt_int(r.get("gasUsed"), 0) * rcpt_int(r.get("effectiveGasPrice"), 0)
            gas_usd = _wei * float(self.cfg.eth_price_usd) / 1e18
        except Exception:
            _wei, gas_usd = 0, 0.0        # цена неизвестна — но она НЕ решает, победа ли это
        try:
            self._engine_result_verdict(meta, h, r, gas_usd)
        finally:
            # #93: записываем ФАКТ и освобождаем бронь, поставленную при отправке этой же
            # пробы. Бронь покрывает только окно «в полёте» (учёт отставал от отправок
            # вшестеро), поэтому суточный факт от неё не растёт — она ограничивает мгновенную
            # экспозицию. Стоит в `finally` и НЕ ОБОРАЧИВАЕТ денежный путь: собственный отказ
            # снятия называется ГРОМКО через `_accounted` и наверх не летит.
            def _book():
                from chain.execute import volley_bal_charge, volley_gas_settle
                volley_gas_settle(h, gas_usd)
                volley_bal_charge(addr, _wei)  # #45: патрон списывается по ФАКТУ, не по оценке
            self._accounted("бронь газа и патрон ноги", h, _book)

    def _engine_result_verdict(self, meta, h, r, gas_usd=0.0):
        """ДЕНЬГИ квитанции: вердикт победы и учёт позиции. Вердикт — ТОЛЬКО по событию
        Liquidated (см. LIQUIDATED_TOPIC0): у пробы доски status=1 бывает и у холостой, и у
        неудачной попытки.

        ВЕРДИКТ — ПЕРВОЙ СТРОКОЙ, ДО ЕДИНОГО ИМПОРТА (структурное правило р-7). Прежде выше
        стояли два импорта, разбор газа и ТРИ учётных вызова, и вопрос «если это БРОСИТ — что
        перестанет стрелять?» имел ответ «ВСЁ»: исключение измерителя уносило вердикт, disarm,
        закрытие окна и wins, а коллектор глотал его до имени типа («FIRE collect handler
        fail: RuntimeError»). Лечится это ПОРЯДКОМ, а не ещё одним except. `_receipt_has_win`
        — функция этого же модуля, импорта не требует.
        """
        addr, tgt = (meta or (None, None))
        _won = _receipt_has_win(r, self.cfg.liquidator_address) is True
        if _won:
            self._probe_win(tgt, h, addr, gas_usd, src="движок", receipt=r)
            # #54: выручка победы — СБОКУ, ПОСЛЕ денег (правило р-7); бросок не трогает огонь
            self._accounted("выручка победы", h, self._book_probe_revenue, h, r)
        else:
            self.stats["board_noop"] = self.stats.get("board_noop", 0) + 1
        # #110: метрика №1 — ГДЕ мы встали
        self._accounted("позиция пробы", h, self._note_probe_position, h, r, meta=meta)

    def _book_probe_revenue(self, h, r):
        """#54: провести выручку победы пробы в store (виден kill-switch'у). Профит — из
        события Liquidated(borrower, loan, profit) нашего контракта (parse_batch_receipt:
        фантомная прибыль запрещена, только СВОИ события). Газ пробы уже в specfire_gas_today
        — здесь gas_usd=0, двойного счёта нет."""
        if _REVENUE_BOOK is None:
            return                                            # канал не армирован (канон)
        from chain.execute import parse_batch_receipt
        wins, _fails = parse_batch_receipt(r, self.cfg.liquidator_address)
        for (borrower, loan), profit_raw in (wins or {}).items():
            usd = _loan_profit_usd(loan, profit_raw, self.cfg)
            if usd is None:
                log.warning("#54 выручка НЕ книжится: неизвестный займ %s (profit_raw=%d tx=%s)"
                            " — незнание не приписывает", str(loan)[:12], int(profit_raw), h)
                continue
            _REVENUE_BOOK(borrower, float(usd), h)
            self.stats["revenue_booked_usd"] = self.stats.get("revenue_booked_usd", 0.0) + float(usd)
            log.info("#54 ВЫРУЧКА ПОБЕДЫ: $%.2f borrower=%s tx=%s — проведена в kill-switch",
                     usd, str(borrower)[:12], h)

    def _accounted(self, what, h, fn, *a, **kw):
        """ИЗМЕРЕНИЕ В СВОЕЙ ВЕТКЕ, с ГРОМКИМ следом. Возврат: измерение прошло?

        Правило раунда-7: учёт никогда не стоит перед деньгами и не оборачивает их. У каждого
        учётного вызова на денежном пути обязан быть ответ на вопрос «если он БРОСИТ — что
        перестанет стрелять?», и ответ обязан быть «ничего». Отсюда две вещи разом: вызов идёт
        ПОСЛЕ вердикта и в своём try, а бросок печатается С ХЭШЕМ И ТИПОМ — невидимый отказ
        есть отказ, который никто никогда не починит (за сутки два таких: голый `except: pass`
        в `_engine_timeout` и общий except коллектора в `_engine_result`).
        """
        try:
            fn(*a, **kw)
            return True
        except Exception as e:
            try:
                log.warning("SPECFIRE УЧЁТ УПАЛ (%s) tx=%s: %s: %s — ДЕНЬГИ НЕ ТРОНУТЫ "
                            "(вердикт, разоружение и окно отработали до этого места)",
                            what, h, type(e).__name__, e)
            except Exception:
                pass
            return False

    def _probe_win(self, tgt, h, addr, gas_usd=0.0, src="движок", receipt=None):
        """ПОБЕДА ПРОБЫ ПО КВИТАНЦИИ: считаем, гасим огонь, закрываем окно, ставим паузу.

        СЛОЙ ПОБЕДЫ ЗАМОРОЖЕН И СРЕЗАН (решение архитектора, рез #110). Здесь стоит РОВНО ТО,
        что уже живёт в бою (origin/main), и ни строкой больше. Три раунда подряд правка этой
        клетки давала новый дефект того же класса: р-6 гасил окно НЕ ТОЙ цели (ложное
        действие), р-7 повесил решение на ключ, планом доски не являющийся (бездействие), р-8
        стирал владение ЖИВОГО соседа гонкой `handle_event('arm')` против `finally` уходящего
        окна. Проектировать четвёртую редакцию, не зная требования, запрещено: слой вернётся
        отдельным пакетом ПОСЛЕ решений владельца по двум развилкам — политика победы в
        каскаде и семантика `SPEC_FIRE_COOLDOWN_TRIGGER`.

        ИЗВЕСТНЫЙ ДЕФЕКТ ЭТОЙ РЕДАКЦИИ НАЗВАН, А НЕ ЗАКРЫТ. `tgt[0]` — ЯРЛЫК, который ставит
        ПОСЛЕДНИЙ тикнувший keepalive любого окна каскада (`FireEngine._target` — одно
        перезаписываемое поле), а приз берётся под планом ОДНОЙ цели. В каскаде это гасит окно
        случайного фида. Ложность ярлыка замерена (59% проб несут чужой) и она же — вход в
        первую развилку владельца. До его решения бот ведёт себя так, как вёл: цена известна,
        новых механизмов под неё не строится.

        АТРИБУЦИЯ ПО КЛЮЧУ ПЛАНА ОСТАЛАСЬ ТАМ, ГДЕ ОНА ИЗМЕРЯЕТ (`_note_probe_position`,
        `_probe_window_report`), и снята оттуда, где она РЕШАЛА, гасить ли огонь. Граница
        именно здесь: измерение ошибается в цифре отчёта, решение — в живом окне.
        """
        feed, mid, b, dbt = (tgt if tgt else ("", "?", "?", 0.0))
        # ДЕНЬГИ ПЕРВЫМИ (структурное правило р-7): вердикт, разоружение и закрытие окна не
        # имеют права стоять за учётом — бросок счётчика их не отменяет.
        self.stats["wins"] = self.stats.get("wins", 0) + 1
        eng = getattr(self, "_fire_engine", None)
        if eng is not None:
            eng.disarm()                 # приз взят — огонь гасим немедленно, не ждём TTL
        # П.3 (приказ владельца 21.08, снявший заморозку рез #110 МИНИМАЛЬНЫМ ходом):
        # ярлык tgt СВЕРЯЕТСЯ с жертвой ИЗ КВИТАНЦИИ (Liquidated нашего контракта — тот же
        # источник, что вердикт _won). Ярлык лжив в 59% (замер в докстринге ниже): keepalive
        # ЛЮБОГО окна каскада перезаписывает FireEngine._target, а приз берётся под планом
        # ОДНОЙ цели — гашение по ярлыку глушило окно СЛУЧАЙНОГО фида. Правило: гасим окно и
        # ставим cooldown ТОЛЬКО если жертва квитанции совпала с ярлыком; несовпадение или
        # незнание (parse пуст при победном topic0) — НЕ гасим ЧУЖОЕ окно (незнание закрывает
        # гард на гашение; цена бездействия — окно доживёт TTL, цена ложного гашения — немой
        # фид в каскаде). Три прежние редакции (р-6/7/8) падали, потому что СТРОИЛИ новую
        # атрибуцию; эта — только запрещает действие по недоказанному ярлыку. receipt=None
        # (пути вне движка/стабы) => поведение прежнее бит-в-бит.
        _label_ok = True
        if receipt is not None:
            try:
                from chain.execute import parse_batch_receipt
                _wins, _ = parse_batch_receipt(receipt, self.cfg.liquidator_address)
                _victims = {bw for (bw, _ln) in (_wins or {})}
                _label_ok = bool(_victims) and str(b).lower() in _victims
            except Exception:
                _label_ok = False        # незнание закрывает гард на гашение
            if not _label_ok:
                log.warning("SPECFIRE WIN: ярлык окна ЛЖИВ (ярлык %s/%s, жертвы квитанции %s)"
                            " — чужое окно НЕ гашу, cooldown не ставлю (п.3)",
                            str(mid)[:10], str(b)[:10],
                            [v[:10] for v in sorted(_victims)] if receipt is not None else "?")
        if _label_ok:
            self._set_cooldown(feed, "probe", proven=True)   # #46: победа пробы не гасит флот
            if feed:
                with self._lock:
                    stop = self._windows.pop(feed, None)
                if stop is not None:
                    stop.set()

        def _mark():
            from chain.execute import mark_recent_send
            mark_recent_send(mid, b)
        self._accounted("метка «недавно отправляли»", h, _mark)
        log.warning("SPECFIRE WIN!!! [%s %s] %s/%s debt=$%.0fk tx=%s gas=$%.2f — "
                    "план доски исполнен (окно %s на паузе %.0fс)",
                    src, (addr or "?")[:10], str(mid)[:10], str(b)[:10], (dbt or 0) / 1e3, h,
                    gas_usd, feed or "НЕТ", SPEC_FIRE_WIN_COOLDOWN_SEC)
        # РИТУАЛ ПЕРВОЙ ПОБЕДЫ, п.2 (ревьюер 21.08): победа = ДВИЖЕНИЕ КАПИТАЛА, то есть
        # HIL-случай №1 канона алертов — человеку уходит ГОТОВЫЙ шаблон с фактами и одним
        # решением, чтобы не импровизировать в три часа ночи. Прибор сбоку: канал армится
        # снаружи (notify_fn), отказ шаблона не трогает деньги — он стоит ПОСЛЕ них.
        try:
            _al = self._alert
            if _al is not None:
                _pf = self.stats.get("revenue_booked_usd")
                _al("\U0001F3C6 ПЕРВАЯ ПОБЕДА (капитал двинулся — нужно ваше решение)\n"
                    "tx: %s\nрынок/жертва: %s / %s\nдолг: $%.0f | газ: $%.2f%s\n"
                    "Профит УЖЕ у owner'а (контракт шлёт его в той же tx; sweep нужен только "
                    "застрявшим токенам — путь отрепетирован 21.08).\n"
                    "РЕШЕНИЕ: (а) вывести на холодный адрес сейчас, либо (б) оставить до конца "
                    "каскада. Скажите «а» или «б» — остальное сделаю сам."
                    % (h, str(mid)[:12], str(b)[:12], float(dbt or 0.0), float(gas_usd or 0.0),
                       ("" if _pf is None else " | выручка книжки: $%.2f" % _pf)),
                    "first-win")
        except Exception:                                    # noqa: BLE001
            pass

    def _board_key(self):
        """Ключ плана, лежащего на доске, в каноне `plan_key` — либо None."""
        try:
            k = (getattr(self, "_board", None) or {}).get("key")
            return self.plan_key(k[0], k[1]) if k and len(k) >= 2 else None
        except Exception:
            return None

    def _agg_of_market(self, mid):
        """ВЛАДЕЛЬЦЫ транзита нашей цели: НАБОР watch-ног рынка (не одна BF1) либо None.

        Без владельца метрика №1 считалась против ЧУЖОГО транзита: `transit_of` без agg берёт
        «предшествующий победе, иначе первый», а в блоке без Liquidate (подавляющее
        большинство блоков) первый транзит — чей угодно.

        Но и ОДНОЙ BF1-ноги мало, и это не мелочь: цену композита двигает ЛЮБАЯ живая нога
        рынка (ради этого 07-23 и вводился multi-leg watch), поэтому в up-окне, которое армит
        ETH/USD-нога рынка cbBTC/WETH, собственный транзит по BF1-ключу опознавался как
        `foreign` — строка ПОЗИЦИИ не печаталась вовсе, и жирное окно уходило без замера.
        Ключ владения теперь по НАБОРУ ног (`feeds.legs_map()`), BF1 остаётся запасным
        источником для до-multi-leg резолвов. Watch-паттерны (композиты, длина != 42)
        отсеивает `chain_index.agg_set` — с адресом лога они не сравнимы.
        """
        try:
            from chain.feeds import legs_map, primary_map
            from chain.chain_index import agg_set
            legs = agg_set(legs_map().get(mid) or ())
            if not legs:
                legs = agg_set(primary_map().get(mid))
        except Exception:
            return None
        return legs or None

    # СЧЁТЧИКИ ПОЗИЦИЙ — ОКОННЫЕ, а не пожизненные (ревью р-3, условие 3). Критерий приёмки
    # (б) «probe_no_agg==0» стоял на кумулятиве процесса: ОДИН законный слепой суд (рынок с
    # watch-паттерном длины !=42, напр. LBTC_FUNDAMENTAL — agg_set его отбрасывает) защёлкивал
    # приёмку ПРОВАЛЕННОЙ на всю жизнь процесса, а 200 последующих ЗРЯЧИХ окон не могли это
    # снять ничем. Репро ревьюера: probe_judged=201, in_band=200, tip_match=200, probe_no_agg=1.
    # Поэтому снимок берётся на АРМЕ окна, а в закрывающую строку идёт ДЕЛЬТА.
    _PROBE_KEYS = ("probe_landed", "probe_idx_off", "probe_uncovered", "probe_no_transit",
                   "probe_foreign_transit", "probe_judged", "probe_judged_blind",
                   "probe_no_agg", "probe_in_band", "probe_tip_match",
                   "probe_in_band_blind", "probe_tip_match_blind")
    # Эти три печатаются ВСЕГДА, даже нулями: приёмка (б) читается по НУЛЮ probe_no_agg, а
    # отсутствие ключа в словаре нулём не является — «не мерили» и «ноль» неразличимы.
    _PROBE_ALWAYS = ("probe_judged", "probe_no_agg", "probe_judged_blind")

    @staticmethod
    def plan_key(mid, b):
        """КЛЮЧ ПЛАНА (mid, borrower) в каноне нижнего регистра, либо None.

        Один ключ на всю проводку: под ним ходит доска (`self._board['key']`), под ним же
        считаются пробы. Пустая половина = ключа НЕТ (незнание закрывает гард): такая проба
        уйдёт в None-бакет и будет НАЗВАНА, а не приписана чужому плану.
        """
        if not mid or not b:
            return None
        return (str(mid).lower(), str(b).lower())

    def _note_plan_key(self, feed, mid, b):
        """ЧЕЙ ПЛАН У ЭТОГО ОКНА — запомнить ключ, по которому окно судит свою приёмку (б).

        ИЗМЕРЕНИЕ, А НЕ РЕШЕНИЕ (рез #110). Прежнее имя обещало вторую роль — «по этому ключу
        решим, чьё окно гасить при победе», — и она отсюда СРЕЗАНА вместе со слоем победы.
        Ошибка в этом словаре теперь стоит неверной цифры в закрывающей строке окна и лишнего
        ключа в кольце; погасить живое окно или замутить фид она не может ничем.

        ЧЕРЕЗ getattr, А НЕ ПРЯМЫМ ПРИСВАИВАНИЕМ, И ЭТО НЕ МЕЛОЧЬ. Точки записи стоят внутри
        `_prearm_board` — ДЕНЕЖНОГО пути, обёрнутого широким `except Exception`. Объект,
        собранный в стенде через `__new__` (или любой будущий путь, где поле не заведено), дал
        бы здесь AttributeError, тот молча ушёл бы в `_arm_retry`, и УЧЁТНАЯ правка убила бы
        публикацию доски. Ровно этот класс («измерительный код уронил боевой») стенд и поймал:
        три теста прогрева покраснели на прямом присваивании. Учёт не имеет права ронять огонь.
        """
        d = getattr(self, "_plan_key_by_feed", None)
        if d is None:
            d = self._plan_key_by_feed = {}
        d[feed] = self.plan_key(mid, b)

    def _probe_keys(self):
        """Учёт ПО КЛЮЧУ ПЛАНА, заводя его при первом обращении.

        Лок МОДУЛЬНЫЙ, а не свой на объект, и словарь заводится лениво НАМЕРЕННО: путь
        `_note_probe_position` — ИЗМЕРИТЕЛЬНЫЙ, он идёт из треда коллектора по денежному
        исходу пробы, и уронить его AttributeError'ом ради учёта нельзя. Цена общего лока —
        одно обновление словаря на пробу (сотни в секунду в пике), контенции здесь нет.
        """
        d = getattr(self, "_probe_by_key", None)
        if d is None:
            d = self._probe_by_key = {}
        return d

    def _probe_bump(self, key, name, n=1):
        """+1 в ОБА учёта: пожизненный self.stats и по КЛЮЧУ ПЛАНА (окно судит только свой)."""
        self.stats[name] = self.stats.get(name, 0) + n
        with _PROBE_FEED_LOCK:
            m = self._probe_keys()
            d = m.get(key)
            if d is None:
                if len(m) > 64:
                    # Ключей столько же, сколько целей, под которые мы клали план. Кольцо на
                    # 64 держит память постоянной, но «самый старый» — это ровно ключ окна,
                    # открытого РАНЬШЕ ВСЕХ, то есть жирного (р-7). Вытеснив его, мы теряли
                    # базу отсчёта: снимок на арме помнил числа, которых в карте больше нет,
                    # и окно печатало ОТРИЦАТЕЛЬНЫЕ пробы (-40 при истине 10), а разницу
                    # записывало в probe_foreign_plan (120 при истине 70). Ключи ЖИВЫХ окон
                    # (`_plan_key_by_feed`) и ключ доски щадим — по ним ещё будут печататься
                    # приёмки, и вытеснить их значит соврать в отчёте закрывающегося окна.
                    _live = self._live_plan_keys()
                    _claim = getattr(self, "_probe_claim", None)
                    _n = 0
                    for _k in list(m):
                        if _n >= 32:
                            break
                        if _k is None or _k in _live:
                            continue
                        m.pop(_k, None)
                        # L2 р-8: КЛЕЙМО УХОДИТ ВМЕСТЕ СО СЧЁТЧИКАМИ, НА КОТОРЫЕ ССЫЛАЕТСЯ.
                        # Пол отсчёта соседа имеет смысл только пока в кольце лежат те самые
                        # числа, от которых он отсчитан. Пережив их, он превращал ШТАТНОЕ
                        # второе окно той же цели (каскад) в probe_landed=-41: отрицательные
                        # счётчики, ради устранения которых кольцо и чинили в р-7, вернулись
                        # через новый механизм. Срок жизни клейма обязан быть КОГЕРЕНТЕН
                        # кольцу, и единственная точка выхода ключа из кольца — вот эта.
                        if _claim is not None:
                            _claim.pop(_k, None)
                        _n += 1
                d = m[key] = {}
            d[name] = d.get(name, 0) + n

    def _live_plan_keys(self):
        """КЛЮЧИ, КОТОРЫЕ ЕЩЁ БУДУТ СУДИТЬСЯ: планы открытых окон + план на доске.

        Зовётся из-под `_PROBE_FEED_LOCK` в `_probe_bump`, поэтому не берёт `self._lock` и не
        трогает сеть: читает два словаря по ссылке и молча отдаёт пустое множество на любой
        неожиданности — вытеснение это оптимизация памяти, и уронить ею учёт нельзя.
        """
        out = set()
        try:
            for _k in (getattr(self, "_plan_key_by_feed", None) or {}).values():
                if _k is not None:
                    out.add(_k)
            _bk = self._board_key()
            if _bk is not None:
                out.add(_bk)
        except Exception:
            return out
        return out

    def _probe_window_report(self, snap, key):
        """ПРИЁМКА ОКНА: дельта по ключу СВОЕГО плана, где проба засчитана РОВНО ОДИН РАЗ.

        ДВЕ ВЕЩИ, КОТОРЫХ ПРЕЖНЯЯ СТРОКА НЕ УМЕЛА.

        1. КЛЮЧА НЕТ (окно не публиковало плана) — печаталась дельта КУМУЛЯТИВА ПРОЦЕССА,
           то есть ЧУЖИЕ пробы выдавались за приёмку этого окна (прогон р-7: план_окна=НЕТ
           при judged=301 у окна, которое не мерило ничего, при 160 у соседа). Незнание
           обязано ЗАКРЫВАТЬ гард: печатаем слова, а не число. Ноль — тоже число.
        2. ДВА ОКНА С ОДНИМ ПЛАНОМ (запрета на совпадение вершин `_top_fat` нет) печатали
           ОДНУ И ТУ ЖЕ дельту — сумма оконных приёмок выходила ВДВОЕ больше числа фактов
           индекса (82 при 41). Ключ теперь КЛЕЙМИТСЯ: засчитанное закрывшимся соседом
           второму окну повторно не засчитывается, и это видно полем `учтено_соседом`.
           Клеймо — не «раз в жизни ключа», а ПОЛ ОТСЧЁТА: окно, армленное позже и закрытое
           позже, свои собственные пробы (те, что пришли после клейма соседа) увидит.
        """
        if key is None:
            return "не измерено (окно не публиковало плана — приёмке (б) не по чему судить)"
        with _PROBE_FEED_LOCK:
            m = self._probe_keys()
            own_c = dict((m.get(key) or {}))
            claim = getattr(self, "_probe_claim", None)
            if claim is None:
                claim = self._probe_claim = {}
            # ЧИСТКА ПО ФАКТУ КОЛЬЦА, А НЕ ПО СВОЕМУ СЧЁТУ (L2 р-8). Прежнее «если клейм >64,
            # выбросить первые 32» жило своей жизнью: оно и держало клеймо ключа, которого в
            # кольце давно нет (тогда пол отсчёта врёт), и могло выбросить клеймо ключа,
            # который в кольце ЕСТЬ (тогда сосед считается дважды). Клеймо теперь —
            # подмножество кольца по построению, и его размер ограничен размером кольца.
            for _k in [_k for _k in claim if _k not in m and _k != key]:
                claim.pop(_k, None)
            base = dict(claim.get(key) or {})
            claim[key] = dict(own_c)          # клеймим ровно то, что засчитываем ниже
        out = self._probe_delta(snap, key, floor=base)
        _s0 = int(((snap or {}).get("by_key") or {}).get(key, {}).get("probe_landed", 0) or 0)
        taken = max(0, int(base.get("probe_landed", 0) or 0) - _s0)
        if taken:
            out["учтено_соседом"] = taken
        return out

    def _probe_snap(self, key=None):
        """Снимок счётчиков позиций: ПОЛНАЯ карта по ключам + кумулятив процесса.

        Снимок берётся на АРМЕ окна, когда ключ плана ещё может быть неизвестен (доску кладёт
        отдельный тред прогрева), поэтому он не привязан к ключу: дельта выберет нужный ключ
        ПОТОМ. Аргумент `key` оставлен для совместимости вызовов и на снимок не влияет.
        """
        with _PROBE_FEED_LOCK:
            m = self._probe_keys()
            return {"by_key": {k: dict(v) for k, v in m.items()},
                    "all": {k: int(self.stats.get(k, 0) or 0) for k in self._PROBE_KEYS}}

    def _probe_delta(self, snap, key=None, floor=None):
        """Дельта счётчиков позиций ЗА ОКНО И ПО КЛЮЧУ СВОЕГО ПЛАНА. snap — снимок на арме.

        key=None — кумулятив ПРОЦЕССА за окно (для читателей, которым нужен весь тракт).

        Приёмка (б) читается ИМЕННО отсюда и ТОЛЬКО ПАРОЙ (ревью р-6): зрячее окно обязано
        показать `probe_no_agg==0` ПРИ `probe_judged>=1`, а слепой сосед того же каскада —
        свой законный `probe_no_agg>=1`. Односторонний ноль зеленеет вакуумно: если пробы
        вообще перестанут учитываться, ноль будет тем же нулём.

        Поэтому рядом печатаются два бакета, которые не дают прочитать ноль как «всё сужено
        зряче»: `probe_foreign_plan` — пробы, ушедшие под ЧУЖИМ планом (доску перехватило
        соседнее окно каскада), и `probe_no_key_proc` — пробы, у которых цели плана не было
        вовсе (движок армлен без цели). Второй ОБЩИЙ НА ПРОЦЕСС и назван суффиксом `_proc`
        именно поэтому: подмешивать его в дельту окна значило бы, что одна такая проба будет
        прочитана КАЖДЫМ окном каскада как своя (минор р-6).
        """
        snap = snap or {}
        s_by, s_all = (snap.get("by_key") or {}), (snap.get("all") or {})
        with _PROBE_FEED_LOCK:
            m = self._probe_keys()
            cur_by = {k: dict(v) for k, v in m.items()}
        cur_all = {k: int(self.stats.get(k, 0) or 0) for k in self._PROBE_KEYS}
        if key is None:
            out = {}
            for k in self._PROBE_KEYS:
                v = cur_all[k] - int(s_all.get(k, 0) or 0)
                if v or k in self._PROBE_ALWAYS:
                    out[k] = v
            return out
        own_c, own_s = (cur_by.get(key) or {}), (s_by.get(key) or {})
        # ПОЛ ОТСЧЁТА (`floor`) — то, что по этому ключу УЖЕ засчитал закрывшийся сосед с тем
        # же планом. Без него два окна одного плана печатают одну дельту дважды (сумма 82 при
        # 41 факте). Ниже в `own_landed` он НЕ участвует нарочно: чужой бакет считается от
        # СЫРОЙ дельты, иначе пробы, ушедшие под НАШИМ планом, назывались бы чужими.
        #
        # ОТРИЦАТЕЛЬНАЯ ДЕЛЬТА НЕВОЗМОЖНА ПО ПОСТРОЕНИЮ (L2 р-8), а не «маловероятна»: пол
        # отсчёта зажат текущим значением счётчика. Оба вычитаемых — и снимок на арме, и
        # клеймо соседа — сняты с карты, которая умеет ОБНУЛЯТЬСЯ (вытеснение ключа кольцом),
        # поэтому «пол больше факта» есть штатное состояние, а не авария. Зажим читается
        # честно: «всё, что у нас есть по этому ключу, уже кем-то засчитано» = 0.
        _fl = floor or {}
        out = {}
        for k in self._PROBE_KEYS:
            _cur = int(own_c.get(k, 0) or 0)
            v = _cur - min(_cur, max(int(own_s.get(k, 0) or 0), int(_fl.get(k, 0) or 0)))
            if v or k in self._PROBE_ALWAYS:
                out[k] = v
        own_landed = int(own_c.get("probe_landed", 0) or 0) - int(own_s.get("probe_landed", 0) or 0)
        none_landed = (int((cur_by.get(None) or {}).get("probe_landed", 0) or 0)
                       - int((s_by.get(None) or {}).get("probe_landed", 0) or 0))
        all_landed = cur_all["probe_landed"] - int(s_all.get("probe_landed", 0) or 0)
        # ПЕЧАТАЕМ ВСЕГДА, включая нули: отсутствие ключа нулём не является, а по этой паре
        # читатель понимает, куда делись пробы, которых нет в дельте окна.
        out["probe_foreign_plan"] = max(0, all_landed - own_landed - none_landed)
        out["probe_no_key_proc"] = none_landed
        return out

    def _note_probe_position(self, h, r, meta=None):
        """#110: позиция нашей пробы в блоке против транзита — метрика №1 плана.

        Раньше её взять было НЕОТКУДА: квитанция несёт `transactionIndex`, но не несёт ни tip
        транзита, ни ширины полосы ничьей, а полный блок в бою никто не читал. Разбор 13.08
        (позиции 48/49/51 и 4745 при победителе на 2267) делался офлайн, руками, через сутки
        после гонки — то есть в бою мы были слепы к единственной величине, которая решает.

        СЧЁТЧИКИ ЧИТАЮТСЯ КАК РАЗБИЕНИЕ, а не как набор. Инвариант держится тождеством:

            probe_landed = probe_idx_off + probe_uncovered + probe_no_transit
                           + probe_foreign_transit + probe_judged

        и по нему ВИДНО, работает механизм или снят: probe_landed==probe_idx_off означает
        «индекса нет» (прежде landed рос и при снятом механизме, и ноль в in_band читался как
        проигрыш позицией). in_band/tip_match — подмножества probe_judged, то есть считаются
        ТОЛЬКО против транзита НАШЕГО рынка в блоке, прочитанном ЦЕЛИКОМ.

        ОТДЕЛЬНО probe_judged_blind (+ in_band_blind / tip_match_blind): владелец транзита
        неизвестен, судили эвристикой «транзит перед первой ликвидацией, иначе первый». Такие
        замеры в денежные счётчики НЕ идут — иначе приёмка (б) проходится против ЧУЖОГО
        транзита, а это ровно тот класс, из-за которого метрика №1 три недели была нечитаема.
        Критерий приёмки (б) требует probe_no_agg==0: судить обязаны ЗНАЯ, чей транзит.
        """
        from chain.chain_index import rcpt_int
        try:
            bn = rcpt_int(r.get("blockNumber"), None)
            idx = rcpt_int(r.get("transactionIndex"), None)
            if bn is None or idx is None:
                return
        except Exception:
            return                        # квитанция без позиции — считать нечего, молча выходим
        _tgt0 = (meta or (None, None))[1]
        # КЛЮЧ ПЛАНА = ЦЕЛЬ, ПОД КОТОРОЙ ПРОБА УШЛА (tgt = (feed, mid, borrower, debt)).
        #
        # ЯРЛЫК ФИДА (tgt[0]) для этого НЕ ГОДИТСЯ, и это блокер C р-6: `FireEngine._target` —
        # ОДНО перезаписываемое поле, в него пишет ПОСЛЕДНИЙ тикнувший keepalive любого окна
        # каскада, а сама доска в этот момент держит план ОДНОЙ цели. Поэтому в бою ярлык
        # говорил «BTC» про пробы, летевшие под планом соседнего окна, и приёмка (б) читалась
        # ПРОВАЛЕННОЙ ровно на жирном окне (дрель L3: no_agg=428 при judged=428).
        # Ключ (mid, borrower) берётся из ТОГО ЖЕ кортежа, но он описывает КАЛДАТУ пробы, а не
        # порядок тиков, — и потому от гонки keepalive не зависит.
        _mid0 = _tgt0[1] if (_tgt0 and len(_tgt0) > 1) else None
        _bor0 = _tgt0[2] if (_tgt0 and len(_tgt0) > 2) else None
        _pkey = self.plan_key(_mid0, _bor0)
        self._probe_bump(_pkey, "probe_landed")
        try:
            from chain import chain_index as _ci
            ci = _ci.get_index()
            if ci is None:
                self._probe_bump(_pkey, "probe_idx_off")
                return
            agg = self._agg_of_market(_mid0) if _mid0 else None
            blind = agg is None
            if blind:
                self._probe_bump(_pkey, "probe_no_agg")
            st, tr = ci.transit_report(bn, agg=agg)
            if st != "transit" or not tr:
                _k = {"uncovered": "probe_uncovered", "no_transit": "probe_no_transit",
                      "foreign": "probe_foreign_transit"}.get(st, "probe_uncovered")
                self._probe_bump(_pkey, _k)
                return
            self._probe_bump(_pkey, "probe_judged")
            t_idx, t_tip = tr["index"], tr["tip"]
            # ВСЛЕПУЮ — ОТДЕЛЬНЫМИ СЧЁТЧИКАМИ. Владельца транзита мы не знаем (рынок не
            # резолвился / фид не Chainlink), значит `transit_report` выбрал транзит
            # ЭВРИСТИКОЙ — он с высокой вероятностью ЧУЖОЙ. Класть такие замеры в
            # in_band/tip_match означало бы «пройти приёмку (б) против чужого транзита»: числа
            # растут, а измеряют они постороннее событие. Разбиение probe_landed при этом не
            # ломается — judged остаётся пятым классом, blind это его ПОДМНОЖЕСТВО-МАРКЕР.
            _band = "probe_in_band_blind" if blind else "probe_in_band"
            _tipm = "probe_tip_match_blind" if blind else "probe_tip_match"
            if blind:
                self._probe_bump(_pkey, "probe_judged_blind")
            if 1 <= idx - t_idx <= _ci.CHAIN_INDEX_PRIZE_WINDOW:
                self._probe_bump(_pkey, _band)
            fact = ci.lookup(h)
            if fact is not None and fact.get("tip") == t_tip:
                self._probe_bump(_pkey, _tipm)
            # Строка — одна на БЛОК И РЕЖИМ СУДА, а не на пробу: при 200 отправках/с строка
            # на пробу сделала бы журнал вторым источником нагрузки на одном ядре. Но ключ
            # именно ПАРА: дедуп по одному номеру блока прятал ЗРЯЧИЙ суд за напечатанным
            # раньше слепым — то есть ровно ту строку, по которой снимается приёмка (б).
            seen = getattr(self, "_pos_logged", None)
            if seen is None:
                seen = self._pos_logged = {}
            _key = (bn, bool(blind))
            if _key not in seen:
                seen[_key] = True
                if len(seen) > 64:
                    for k in sorted(seen)[:32]:
                        seen.pop(k, None)
                rep = ci.our_position_report(bn, agg=agg)
                if rep:
                    self._log("SPECFIRE %s" % rep)
                    # ГЕЙТ ЖЕРТВЫ для TG: была ли в блоке РЕАЛЬНАЯ ликвидация (наша/чужая).
                    # Источник — факты индекса того же блока (без сети).
                    _victim = None
                    try:
                        _bf = ci.block_facts(bn) or {}
                        _victim = bool(_bf.get("liquidate"))
                    except Exception:                        # noqa: BLE001
                        _victim = None
                    self._pos_alert(rep, blind, victim=_victim)
                    # П.1/П.2 (kelbic 21.08): пересечение ПО ХЭШАМ + метрика «FCFS-полоса
                    # на верном классе». Тред индекса (не recv-петля); лог КАПИРОВАН —
                    # только delta в [-3..25] или match (урок «строка-на-пробу = вторая
                    # нагрузка»). Кольцо delta-по-match кормит p50/p90 закрытия окна.
                    if not blind:
                        self._pos_table(ci, bn, agg)
        except Exception:
            pass

    def _pos_table(self, ci, bn, agg):
        """П.1: таблица пересечения по хэшам; П.2: копилка delta по tip-match. Сбоку от денег:
        любой отказ глотается, деньги этот путь не трогает (прибор в треде индекса)."""
        try:
            t = ci.our_position_table(bn, agg=agg)
            if not t:
                return
            rows, (t_idx, t_tip) = t
            inter = [r for r in rows if 1 <= r[2] <= 20 and r[4]]
            # П.2б (ревьюер 26.08): МЕТРИКА ВЕДЁТСЯ ДВОЙНОЙ до вердикта боем.
            # СТАРАЯ (inter) — полоса И точный класс на одной tx: исторические победители
            # зеркалили tip ТОЧНО 10/10, поэтому равенство может быть НУЖНЫМ, и снимать её
            # нельзя. НОВАЯ (nearest) — наша ближайшая tx ПОСЛЕ транзита безотносительно
            # класса: гипотеза «достаточно быть сразу за транзитом при тонкой полосе tip».
            # П.2в: ПЛОТНОСТЬ ПОЛОСЫ — сколько ЧУЖИХ tx между транзитом и нашей ближайшей.
            # Это и есть прямая мера «тонкости», на которой держится вся гипотеза: чужих 0 —
            # мы фактически на transit+1; чужих много — быть «сразу за» недостаточно.
            _after = [r for r in rows if r[2] >= 1]
            _near = _after[0] if _after else None
            _foreign = (_near[2] - 1) if _near else None   # tx между транзитом и нашей
            _near_s = ("delta=+%d класс=%s чужих_между=%s"
                       % (_near[2], "ДА" if _near[4] else "нет", _foreign)) if _near else "нет"
            ring2 = self.stats.setdefault("nearest_delta_ring", [])
            if _near:
                ring2.append(_near[2])
                del ring2[:-400]
                self.stats["nearest_foreign_sum"] = \
                    self.stats.get("nearest_foreign_sum", 0) + (_foreign or 0)
                self.stats["nearest_n"] = self.stats.get("nearest_n", 0) + 1
            match_d = [r[2] for r in rows if r[4]]
            # Копилка kelbic 21.08: (а) транзит-класс МЕЖДУ слотами лестницы (наших tx есть,
            # на классе — ни одной) — если доля заметна, аргумент за ДРОБЛЕНИЕ сетки слотов,
            # не за интерполяцию; (б) низкая плотность (наших <10 в блоке с транзитом) —
            # ДРУГОЙ дефект, чем латентность (дыра арма/бёрста), маскировать друг друга не
            # должны. Оба — счётчиками, лечение только по замеренной доле.
            if rows and not match_d:
                self.stats["class_between_slots"] = self.stats.get("class_between_slots", 0) + 1
            if len(rows) < 10:
                self.stats["low_density_blocks"] = self.stats.get("low_density_blocks", 0) + 1
            ring = self.stats.setdefault("match_delta_ring", [])
            ring.extend(match_d)
            del ring[:-400]                       # кольцо ~400 последних значений
            # Ключ CLASS-CATCH — ФАКТИЧЕСКИЙ агрегатор транзита (строка-адрес), а НЕ `agg`:
            # тот приезжает НАБОРОМ watch-ног рынка (frozenset) для проверки владения, и в
            # ключе кольца давал «agg=frozenset(…)» + промах lookup'а по _TRANSIT_TIPS
            # (там ключ — str(agg).lower() из note_transit_tip). Отказ -> None (ключ "?").
            _t_agg = None
            try:
                _st, _tr = ci.transit_report(bn, agg=agg)     # из памяти индекса, без сети
                if _tr:
                    _t_agg = _tr.get("agg")
            except Exception:                                # noqa: BLE001
                pass
            self._class_catch(bn, _t_agg, t_tip, bool(match_d))
            shown = [r for r in rows if (-3 <= r[2] <= 25) or r[4]][:60]
            body = " ".join("%s:%+d@%d%s" % (h[:10], d, tip, "*" if m else "")
                            for h, _i, d, tip, m in shown)
            mm = sorted(match_d)
            p50 = mm[len(mm) // 2] if mm else None
            p90 = mm[int(len(mm) * 0.9)] if mm else None
            # П.7: профиль стадий НА ПЕРВУЮ пробу с tip_match — называет стадию-вкладчика
            _prof_s, _worst = "—", (None, None)
            _first_m = next((r for r in rows if r[4]), None)
            if _first_m is not None:
                try:
                    from chain.stage_probe import profile as _pf, format_profile as _fmt
                    _prof_s, _worst = _fmt(_pf(_first_m[0], feed=getattr(self, "_last_feed", None),
                                               bn=bn))
                except Exception:                            # noqa: BLE001
                    pass
            self._log("SPECFIRE СТАДИИ blk=%d проба=%s delta=%+d плотность=%d%s: %s | топ-вкладчик: %s%s"
                      % (bn, str(_first_m[0])[:12] if _first_m else "—",
                         _first_m[2] if _first_m else 0, len(rows),
                         " (НИЗКАЯ — дыра арма/бёрста, не латентность)" if len(rows) < 10 else "",
                         _prof_s,
                         _worst[0] or "—",
                         (" %.0fмс" % _worst[1]) if _worst[1] is not None else ""))
            # ТЕНЕВОЙ ЗАМЕР СЛОТА А1в3 (ревьюер 21.08, БЕЗ расконсервации — только журнал):
            # p50 feeHistory блока B-1 против фактического tip транзита. К моменту «го» kelbic
            # даёт готовую приёмочную выборку «слот угадал бы класс в N% блоков» вместо нуля
            # наблюдений; заодно последовательность строк показывает ФОРМУ затухания
            # эскалации (кандидат на второй слот). Вердикты редкие — один feeHistory на
            # вердикт, на узле индекса (не боевой ключ). Прибор сбоку: отказ глотается.
            # ЗАКРЫТО 22.08 (ОПРОВЕРГНУТО тенью 0/9): p50(B-1) занижает tip транзиттера в
            # ~2.6x — класс скачка не живёт в B-1. Тень выключена по умолчанию ради CU;
            # SHADOW_SLOT_A1V3=1 возвращает замер, если направление когда-нибудь оживёт.
            try:
                if os.environ.get("SHADOW_SLOT_A1V3", "0").lower() not in ("1", "true", "yes"):
                    raise RuntimeError("shadow-slot закрыт (0/9)")
                _fh = ci._rpc("eth_feeHistory", [1, hex(int(bn) - 1), [50]])
                _rw = (_fh.get("reward") or [[None]])[0]
                _p50 = int(_rw[0], 16) if isinstance(_rw[0], str) else (int(_rw[0]) if _rw[0] is not None else None)
                if _p50 is not None and t_tip:
                    _ratio = _p50 / float(t_tip)
                    self._log("SPECFIRE ТЕНЬ-СЛОТ blk=%d p50(B-1)=%d факт=%d ratio=%.2f "
                              "hit10=%s hit25=%s" % (bn, _p50, t_tip, _ratio,
                                                     0.9 <= _ratio <= 1.1, 0.75 <= _ratio <= 1.25))
            except Exception:                                # noqa: BLE001
                pass
            self._log("SPECFIRE БЛИЖАЙШАЯ blk=%d транзит=%d@%d: %s (гипотеза «равенство tip "
                      "не обязательно» — судится блоком С ЖЕРТВОЙ)" % (bn, t_idx, t_tip, _near_s))
            self._log("SPECFIRE ПЕРЕСЕЧЕНИЕ blk=%d транзит=%d@%d: полоса∩класс=%d "
                      "(вердикт «формула» пишет ТОЛЬКО это число), match=%d delta p50=%s "
                      "p90=%s | %s%s"
                      % (bn, t_idx, t_tip, len(inter), len(match_d), p50, p90, body,
                         " …" if len(rows) > len(shown) else ""))
        except Exception:
            pass

    def _class_catch(self, bn, agg, t_tip, matched):
        """П.2 ревьюера 22.08: class_catch_lag = число блоков от ПЕРВОГО tx с новым классом X
        (первый судимый блок с новым t_tip: судятся ровно блоки с транзитом, слепой суд сюда
        не попадает) до ПЕРВОЙ нашей пробы на X (первый блок с tip_match). Отвечает, где живёт
        лаг: кольцо_знало≥Nс при большом lag ⇒ переодевание лестниц (класс→пресайн); малое/
        отсутствующее кольцо_знало ⇒ подача (детект→кольцо). Вторая половина разреза — строка
        СТАДИИ рядом: её «возраст_лестницы» на первой match-пробе показывает, КОГДА лестница
        была переодета. Возраст кольца — от штампа стенки b0 В ЭТОМ ЖЕ треде (лаг индекса
        сокращается), и это НИЖНЯЯ граница: кольцо капировано, ранние записи вытесняются.
        Честный знаменатель (канон): пойманные — в class_catch_ring, непойманные смены — в
        class_catch_uncaught; приёмку читать ТОЛЬКО парой. Прибор сбоку: весь путь в try,
        отказ глотается, состояние — карта на агрегатора, капирована."""
        try:
            st_map = getattr(self, "_ccl", None)
            if st_map is None:
                st_map = self._ccl = {}
            # Ключ — ИМЯ агрегатора. Fail-safe 26.08: если приехал НАБОР ног рынка
            # (frozenset/set/list — так его несёт `agg` в _pos_table), берём ДЕТЕРМИНИРОВАННО
            # первый по сортировке, а не repr множества: иначе ключ читался «frozenset(…)» и
            # промахивался мимо _TRANSIT_TIPS (там ключ str(agg).lower()).
            if isinstance(agg, (frozenset, set, list, tuple)):
                _cands = sorted(str(a).lower() for a in agg if a)
                agg = _cands[0] if _cands else None
            key = str(agg).lower() if agg else "?"
            st = st_map.get(key)
            if st is not None and st[0] == t_tip and st[3]:
                return                          # класс тот же и уже пойман — тишина
            if st is None or st[0] != t_tip:
                if st is not None and not st[3]:
                    self.stats["class_catch_uncaught"] = \
                        self.stats.get("class_catch_uncaught", 0) + 1
                    self._log("SPECFIRE CLASS-CATCH agg=%s класс=%d СМЕНИЛСЯ НЕПОЙМАННЫМ "
                              "за %d блоков (b0=%d)" % (key[:10], st[0], bn - st[1], st[1]))
                st = st_map[key] = [t_tip, bn, time.time(), False]
                while len(st_map) > 8:
                    st_map.pop(next(iter(st_map)))
            if matched and not st[3]:
                st[3] = True
                lag = bn - st[1]
                cring = self.stats.setdefault("class_catch_ring", [])
                cring.append(lag)
                del cring[:-100]
                ring_s = None
                try:
                    from chain.execute import _TRANSIT_TIPS, _TRANSIT_TIPS_LOCK
                    with _TRANSIT_TIPS_LOCK:
                        rings = ([_TRANSIT_TIPS.get(key) or []] if agg
                                 else list(_TRANSIT_TIPS.values()))
                        for r in rings:
                            for ts, w in r:
                                if w == t_tip and (ring_s is None or ts < ring_s):
                                    ring_s = ts
                except Exception:                            # noqa: BLE001
                    pass
                extra = ""
                if ring_s is not None:
                    extra = " кольцо_знало≥%.1fс-до-b0" % (st[2] - ring_s) \
                        if ring_s <= st[2] else \
                        " кольцо_узнало_через=%.1fс-после-b0" % (ring_s - st[2])
                self._log("SPECFIRE CLASS-CATCH agg=%s класс=%d class_catch_lag=%d блоков "
                          "(b0=%d b1=%d, непойманных смен=%d)%s"
                          % (key[:10], t_tip, lag, st[1], bn,
                             self.stats.get("class_catch_uncaught", 0), extra))
        except Exception:
            pass

    # 20.08 (запрос kelbic): вердикт судимой гонки — В TG, не только в журнал. Это исход,
    # по которому человек принимает решение п.15 плана (tip-режим), — законный алерт по
    # канону «алерты только там, где нужен человек». Прибор ВИСИТ СБОКУ от денежного пути:
    # вызов стоит ЗА _log в ветке отчёта, канал _alert армится явно из main (канон
    # notify_fn: забыли армировать — молчание, не выстрел), собственный отказ глотается.
    # Слепой суд (транзит выбран эвристикой, скорее всего ЧУЖОЙ) не шлём — шум; форма
    # «судить не о чем» (нет транзита) — тоже. Кулдаун свой и явный: судимые блоки идут
    # пачкой ~10 за эпизод, человеку нужна ПЕРВАЯ строка эпизода. Победа кулдаун ПРОБИВАЕТ
    # всегда. Откат: SPEC_FIRE_RACE_ALERT=0 (снимает ПРИБОР, денежный путь не трогает).
    def _pos_alert(self, rep, blind, victim=None):
        """Вердикт гонки — В TG. ГЕЙТ ЖЕРТВЫ (kelbic 26.08): человеку идут только НАСТОЯЩИЕ
        гонки — блоки, где ликвидация ДЕЙСТВИТЕЛЬНО состоялась (наша или чужая). Фантомные
        транзиты (жертвы нет, приза не существовало) — их подавляющее большинство, и они
        приходили каждые 15 мин — остаются в ЖУРНАЛЕ, но человека не будят: канон «алерты
        только там, где человек действует». victim=None -> сигнала нет -> НЕ шлём (незнание
        закрывает алерт, а не открывает). Откат: SPEC_FIRE_RACE_ALERT_PHANTOM=1."""
        try:
            if blind or not rep or "транзит idx=" not in rep:
                return
            if not victim and os.environ.get(
                    "SPEC_FIRE_RACE_ALERT_PHANTOM", "0").lower() not in ("1", "true", "yes"):
                self.stats["race_alert_phantom_skips"] = \
                    self.stats.get("race_alert_phantom_skips", 0) + 1
                return
            if os.environ.get("SPEC_FIRE_RACE_ALERT", "1").lower() in ("0", "false", "no"):
                return
            al = self._alert
            if al is None:
                return
            import re as _re
            _m = _re.search(r"побед=(\d+)", rep)
            won = bool(_m and int(_m.group(1)) > 0)
            now = time.monotonic()
            cd = float(os.environ.get("SPEC_FIRE_RACE_ALERT_COOLDOWN_SEC", "900"))
            if not won and (now - float(getattr(self, "_pos_alert_ts", 0.0))) < cd:
                return
            self._pos_alert_ts = now
            if won:
                al("\U0001F3C6 ПОБЕДА в гонке: %s" % rep, "race-win")
            else:
                al("\U0001F3C1 вердикт гонки (первый блок эпизода): %s" % rep, "race-verdict")
        except Exception:
            pass

    def _engine_timeout(self, meta, h):
        """ТАЙМАУТ ПРОБЫ. ДЕНЬГИ ПЕРВЫМИ, УЧЁТ ПОСЛЕ, БРОНЬ #93 — В `finally`.

        L1 р-8, третий за сутки случай «УЧЁТ УРОНИЛ ОГОНЬ». Прежде первыми строками функции
        стояли импорт `chain.execute` и `volley_gas_settle(h, 0.0)`, то есть УЧЁТ ПЕРЕД
        ДЕНЬГАМИ. Вызов `_on_timeout` в коллекторе обёрнут `except` (`fire_engine.py`),
        поэтому бросок в этой одной учётной строке уносил всё, что ниже: учёт победы
        NO-RECEIPT (`wins`/`noreceipt_win`), книжку газа по факту индекса и
        `volley_invalidate_nonce` отставшей ноги — и не оставлял в журнале ни строки. Вопрос
        к каждому такому месту: «если счётчик БРОСИТ — что перестанет стрелять?» Ответ здесь
        обязан быть «ничего», и теперь он такой.

        ПРОСТО «ПЕРЕСТАВИТЬ СТРОКИ ВНИЗ» БЫЛО НЕЛЬЗЯ. У денежной части пять выходов, включая
        ранний `return` ветки «нога на цепи догнала», а гарантия #93 требует освобождать
        бронь на КАЖДОМ: иначе она копится и гейт огня самозапирается до полуночи UTC.
        Отсюда форма: деньги в `try`, снятие брони в `finally` (исполняется и на `return`, и
        на броске), и оно НЕ ОБОРАЧИВАЕТ денежный путь — собственный отказ снятия называется
        ГРОМКО через `_accounted` и наверх не летит.
        """
        try:
            self._engine_timeout_verdict(meta, h)
        finally:
            def _settle():
                # #93: квитанции не будет — бронь этой пробы обязана освободиться. ФАКТ при
                # этом НЕ пишем: расход неизвестен. Импорт стоит ЗДЕСЬ, а не в шапке функции,
                # намеренно: отказ импорта — это тоже отказ УЧЁТА, и он не имеет права стоять
                # перед деньгами (ровно так дефект и выглядел до р-8).
                from chain.execute import volley_gas_settle
                volley_gas_settle(h, 0.0)
            self._accounted("снятие брони газа #93 после таймаута", h, _settle)

    def _engine_timeout_verdict(self, meta, h):
        """ДЕНЬГИ таймаута: учёт победы NO-RECEIPT и защита nonce отставшей ноги.

        ОГНЁМ ЭТОТ ПУТЬ НЕ УПРАВЛЯЕТ (рез #110): факт победы считается, окно не гасится и
        WIN-пауза не ставится — слой победы заморожен до решений владельца.

        Квитанции нет за таймаут: nonce ноги под вопросом — склад этой ноги сбрасываем, иначе
        вся её лестница висит за возможной дырой. Учётного вызова ПЕРЕД вердиктом здесь нет
        ПО ПОСТРОЕНИЮ: снятие брони #93 живёт в `finally` обёртки выше, а импорт
        `chain.execute` спущен в ту ветку, которой он нужен (ниже, к защите ноги).
        """
        addr = (meta or (None, None))[0]
        # #110: ПЕРВЫМ спрашиваем индекс — он видел сами блоки. Это прямая заплата на ложь
        # 12-13.08: КАЖДАЯ проверенная проба с меткой «NO-RECEIPT (nonce инвалидирован)» была
        # ЗАМАЙНЕНА (j2 — в 49820480, j1 — в 49805074). Ценой той лжи был сброс склада живой
        # ноги (40 пред-подписанных проб + 28-32с пересборки флота) ровно в каскадные секунды.
        # Индекс различает три исхода, и приговор выносится ТОЛЬКО на "absent".
        ci = None                     # объявлено ДО try: иначе ветка except читала бы имя,
        try:                          # которого нет (NameError вместо диагноза)
            from chain import chain_index as _ci
            ci = _ci.get_index()
            st, fact = ci.state(h) if ci is not None else ("unknown", None)
        except Exception:
            st, fact = ("unknown", None)
        # ЧТО СКАЗАЛ ИНДЕКС — отдельным счётчиком на каждый исход. Без него приёмка нечитаема:
        # noreceipt_false при ИСПРАВНОМ пакете стремится к нулю по построению (коллектор
        # спрашивает индекс ПЕРВЫМ, и знакомая ему проба с газом до таймаута просто не
        # доживает), то есть ноль там означает и «всё хорошо», и «индекса нет». Разбиение
        # ниже отвечает на этот вопрос прямо.
        _sk = {"mined": "noreceipt_idx_mined", "absent": "noreceipt_idx_absent"}.get(
            st, "noreceipt_idx_off" if ci is None else "noreceipt_idx_unknown")
        self.stats[_sk] = self.stats.get(_sk, 0) + 1
        if st == "mined":
            self.stats["noreceipt_false"] = self.stats.get("noreceipt_false", 0) + 1
            # Раз tx СЕЛА, газ по ней потрачен. Прежний путь снимал бронь и записывал ноль —
            # дневной счётчик недосчитывал ровно те пробы, о которых узел молчал. Если индекс
            # принёс gasUsed (узел умеет getBlockReceipts) — книжим ФАКТ, не оценку; не принёс
            # — оставляем ноль и не выдумываем.
            self._log("SPECFIRE движок NO-RECEIPT tx=%s — ИНДЕКС ОПРОВЕРГ: tx в блоке %s поз %s "
                      "(квитанция не пришла, но проба СЕЛА, вердикт победы=%s). Склад ноги %s "
                      "СОХРАНЁН"
                      % (h, (fact or {}).get("block"), (fact or {}).get("index"),
                         (fact or {}).get("won"), (addr or "?")[:10]))
            # ХВОСТ #110-х1 (ДЕНЬГИ, РЕШЕНИЕ ПРИ РЕЗЕ): tx села — А ВЗЯЛА ЛИ ОНА ПРИЗ?
            #
            # ЧТЕНИЕ `won` ОСТАЁТСЯ — оно кормит УЧЁТ, а не огонь. Без него победа, о которой
            # узел квитанций промолчал (а он молчит регулярно: 889 «collect batch fail» за
            # сутки и ЛОЖНЫЕ NO-RECEIPT у замайненных проб j1/j2), не попадала бы ни в `wins`,
            # ни в суточную приёмку: единственный числитель win-rate брался бы только из
            # ветки квитанции, то есть знаменатель и числитель считались бы по РАЗНЫМ
            # источникам правды. Это деньги, и они остаются.
            #
            # ДЕЙСТВИЕ ПО ОГНЮ ОТСЮДА СНЯТО (рез #110). `_probe_win` — гашение окна, WIN-пауза,
            # disarm — на этом пути НИКОГДА не жило в бою: его добавил р-6 вместе со слоем
            # победы, а слой заморожен. Возвращать поведение к боевому значит: ФАКТ считаем,
            # огонь не трогаем. Цена названа прямо в строке ниже, чтобы владелец видел её в
            # журнале, а не выводил из кода: до конца TTL окна движок может жечь газ по уже
            # взятой цели. Ровно этот вопрос и есть первая из двух развилок, после которых
            # слой вернётся отдельным пакетом.
            #
            # Победой считается ТОЛЬКО `won is True` (наш хэш среди логов Liquidate у Morpho):
            # всё остальное — «не победа». СЧЁТЧИК «ВЕРДИКТ НЕИЗВЕСТЕН» СНЯТ (р-7) как
            # структурно нулевой: `won` остаётся None только если `build_facts` получил
            # logs=None, а `scan_block` читает логи ПЕРВЫМ вызовом и на отказе бросает
            # IndexUnavailable. Вместо счётчика вердикт ПЕЧАТАЕТСЯ в строке выше.
            if (fact or {}).get("won") is True:
                self.stats["noreceipt_win"] = self.stats.get("noreceipt_win", 0) + 1
                self.stats["wins"] = self.stats.get("wins", 0) + 1
                _t = (meta or (None, None))[1] or ("", "?", "?", 0.0)
                log.warning("SPECFIRE WIN!!! [NO-RECEIPT %s] %s/%s (ярлык тика=%s) tx=%s — ПРИЗ "
                            "ВЗЯТ (вердикт от индекса, квитанции не было): учтён в "
                            "wins/noreceipt_win. Окно НЕ гашу и WIN-паузу НЕ ставлю — слой "
                            "победы заморожен (рез #110), огонь по этой цели снимется по TTL "
                            "окна",
                            (addr or "?")[:10], str(_t[1] if len(_t) > 1 else "?")[:10],
                            str(_t[2] if len(_t) > 2 else "?")[:10],
                            (_t[0] if _t else "?"), h)
            # УЧЁТ — ПОСЛЕ ДЕНЕГ И В СВОЕЙ ВЕТКЕ (структурное правило р-7). Прежде обе учётные
            # записи (газ по факту индекса и позиция пробы) стояли ДО вердикта, причём газ — под
            # голым `except: pass`: бросок в измерении съедал победу ЦЕЛИКОМ и не оставлял в
            # журнале ни строки.
            _g = (fact or {}).get("gas_used")
            _p = (fact or {}).get("eff_gas_price")
            if _g and _p:
                def _book():
                    from chain.execute import volley_gas_add, volley_bal_charge
                    _wei = int(_g) * int(_p)
                    volley_gas_add(_wei * float(self.cfg.eth_price_usd) / 1e18)
                    if addr:
                        volley_bal_charge(addr, _wei)
                    self.stats["noreceipt_gas_booked"] = self.stats.get(
                        "noreceipt_gas_booked", 0) + 1
                self._accounted("газ по факту индекса", h, _book)
            self._accounted("позиция пробы", h, self._note_probe_position, h,
                            {"blockNumber": (fact or {}).get("block"),
                             "transactionIndex": (fact or {}).get("index")}, meta=meta)
            return
        if addr:
            # ИМПОРТ — ЗДЕСЬ, В СВОЕЙ ВЕТКЕ (L1 р-8). Наверху функции он стоял ПЕРЕД вердиктом
            # победы, то есть отказ импорта (или любой строки учёта рядом с ним) уносил и учёт
            # победы, и книжку газа по факту индекса. В этой ветке импорт нужен самим ДЕНЬГАМ
            # — защите ноги от дыры в nonce, — и стоять раньше вердикта ему незачем.
            from chain.execute import (volley_invalidate_nonce, invalidate_ladder,
                                       volley_leg_landed)
            # #102: СПЕРВА спрашиваем цепь. Сброс склада стоит 40 пред-подписанных проб и
            # 28-32с пересборки всего флота, поэтому «не знаю» не имеет права его запускать.
            if volley_leg_landed(self.rpc, addr):
                self.stats["noreceipt_spared"] = self.stats.get("noreceipt_spared", 0) + 1
                self._log("SPECFIRE движок NO-RECEIPT eoa=%s tx=%s — но nonce на ЦЕПИ догнал: "
                          "tx села, склад СОХРАНЁН" % (addr[:10], h))
                return
            self.stats["noreceipt_dropped"] = self.stats.get("noreceipt_dropped", 0) + 1
            if st == "absent":
                # Индекс сплошь прочитал все блоки с момента отправки — сброс склада обоснован
                # ФАКТОМ, а не молчанием узла квитанций. Разделяем счётчики: доля
                # dropped_confirmed в dropped и есть честный знаменатель «мы правда теряем ноги».
                self.stats["noreceipt_dropped_confirmed"] = self.stats.get(
                    "noreceipt_dropped_confirmed", 0) + 1
            volley_invalidate_nonce(addr)
            invalidate_ladder(addr)
            self._log("SPECFIRE движок NO-RECEIPT eoa=%s tx=%s — nonce на цепи ОТСТАЁТ, "
                      "склад ноги сброшен" % (addr[:10], h))

    def _volley(self, probe, mid, b, d, feed, simultaneous=False):
        """Залп вслед за успешной пробой главного кошелька: тот же calldata на v4 от каждого
        залпового EOA. Огонь и ожидания — в daemon-тредах: петля окна не тормозится ни на мс.

        Расстановка ног зависит от того, ЗНАЕМ ли мы момент:
          simultaneous=False (вслепую) — сдвиг фазы (i+1)*PHASE. N ног = N участков покрытия,
            модель P(win)=W/τ; синхронный залп здесь дал бы N-кратную избыточность на одном
            участке, т.е. выиграл бы ровно те гонки, что и один EOA — покрытие не растёт;
          simultaneous=True (транзит виден в pending) — момент известен, бьём разом.
        SPEC_FIRE_VOLLEY_PARALLEL=1: нога = свой тред, сдвиг держим мы, а не сеть (замер
        боевого send-пути — у константы). =0 — прежний последовательный цикл бит-в-бит."""
        from chain import execute as _ex
        if not _ex.SPEC_FIRE_VOLLEY or not self._cascade_active():
            return
        accts = (self._volley_accounts_fn or _ex.volley_accounts)()
        if not accts:
            return
        sync = bool(simultaneous) and SPEC_FIRE_VOLLEY_DETECT_SYNC
        # v5 доска: план УЖЕ в контракте под ЭТУ цель и запись успела сесть -> ноги несут 1 байт
        # (цель не палится, газ калдаты ~в 200 раз меньше). Иначе — прежний полный calldata.
        board = self._board_live(mid, b)
        # #135/§5: байт пробы зависит от флага (0x01 у v5, 0xFF = сентинел _hot у v6). Один
        # источник истины — execute.probe_calldata(), тот же, которым подписаны лестницы.
        _cd = _ex.probe_calldata() if board else probe["calldata"]
        _gas = SPEC_FIRE_V2_FIRE_GAS if board else probe["gas"]
        # ДВИЖОК ОГНЯ: план уже в контракте, значит пробе не нужен ни этот тик, ни эти треды —
        # тик лишь ПРОДЛЕВАЕТ право стрелять постоянному пулу. Порождать залп больше не нужно.
        # Только для доски: у V1 калдата зависит от цели, а склад подписан под 1 байт.
        if board:
            eng = self._engine()
            if eng is not None:
                eng.keepalive(target=(feed, mid, b, d))
                return

        def _leg(i, addr, key, mf, tip, bcast, wait_sec):
            try:
                if wait_sec > 0:
                    self._sleep(wait_sec)
                h = (self._volley_send_fn or _ex.send_volley_probe)(
                    self.rpc, self.cfg, addr, key, _cd, _gas,
                    log=log, max_fee=mf, tip=tip, broadcast_raw_urls=bcast)
                if h is None:
                    return
                self.stats["volley_probes"] += 1
                if board:
                    self.stats["board_probes"] += 1
                self._log("SPECFIRE volley leg=%d/%d%s%s eoa=%s feed=%s %s/%s tx=%s" % (
                    i + 1, len(accts), " [sync]" if sync else "", " [доска]" if board else "",
                    addr[:10], feed, mid[:10], b[:10], h))
                self._rcpt_dispatch(h, "volley", (mid, b, d, feed, addr, board))
            except Exception as e:
                self._log("SPECFIRE volley leg fail feed=%s eoa=%s: %s" % (
                    feed, addr[:10], type(e).__name__))

        def _run():
            try:
                from chain.hotpath import _fresh_basefee
                fb = _fresh_basefee()                     # один фетч на залп, не на ногу
                tip = _probe_tip_wei(self.cfg.tip_gwei)   # тот же tip-кап: FCFS, место не покупается
                mf = (fb * 2 + tip) if fb is not None else None
                seq = str(getattr(self.cfg, "sequencer_rpc", "") or "")
                bcast = [seq] if (seq and seq.lower() not in ("off", "none", "0")) else None
                if not SPEC_FIRE_VOLLEY_PARALLEL:          # прежний путь: сдвиг ПЕРЕД каждой ногой
                    for i, (addr, key) in enumerate(accts):
                        _leg(i, addr, key, mf, tip, bcast,
                             0.0 if sync else SPEC_FIRE_VOLLEY_PHASE_SEC)
                    return
                # Флот: ног может быть десятки, а ядер два. Тред-на-ногу тут душит боевой контур,
                # поэтому ноги режутся на ПАЧКИ — не больше MAX_THREADS тредов на залп. Внутри
                # пачки ноги идут подряд, но КАЖДАЯ держит свой накопленный сдвиг от начала залпа
                # (сдвиг считается по индексу ноги, а не по позиции в пачке) — расстановка фаз
                # остаётся той же, что при треде-на-ногу.
                n = len(accts)
                nthr = max(1, min(SPEC_FIRE_VOLLEY_MAX_THREADS, n))
                t0 = self._now()

                def _batch(idxs):
                    for i in idxs:
                        addr, key = accts[i]
                        want = 0.0 if sync else SPEC_FIRE_VOLLEY_PHASE_SEC * (i + 1)
                        _leg(i, addr, key, mf, tip, bcast, max(0.0, want - (self._now() - t0)))

                for t in range(nthr):
                    threading.Thread(target=_batch, args=(range(t, n, nthr),),
                                     daemon=True, name="volley-b%d" % (t + 1)).start()
            except Exception as e:
                self._log("SPECFIRE volley fail feed=%s: %s" % (feed, type(e).__name__))

        threading.Thread(target=_run, daemon=True, name="volley-%s" % feed).start()

    def _collect_volley(self, h, mid, borrower, debt_usd, feed, addr, board=False):
        """ЛЕГАСИ-обёртка ноги залпа (тред-на-пробу); исход ведёт core, shadow сверяется."""
        res = (self._receipt_fn or self._receipt)(h)
        if SPEC_FIRE_RCPT_MODE == "shadow":
            self._rcpt_shadow_note(h, "легаси", res[0] if res else None)
        self._collect_volley_core(res, h, mid, borrower, debt_usd, feed, addr, board)

    def _collect_volley_core(self, res, h, mid, borrower, debt_usd, feed, addr, board=False):
        """ДЕНЬГИ ноги залпа: газ — в бакет тира; WIN — та же семантика, что у главной пробы
        (дедуп-маркер, кулдаун, окно закрыть); NO-RECEIPT инвалидирует nonce СВОЕГО EOA.

        board=True — проба ДОСКИ: статус tx о победе не говорит ничего (три исхода дают
        status=1, см. LIQUIDATED_TOPIC0), поэтому вердикт выносит только событие Liquidated."""
        from chain.execute import volley_gas_add, volley_invalidate_nonce, mark_recent_send
        if res is None:
            volley_invalidate_nonce(addr)
            self._log("SPECFIRE volley NO-RECEIPT eoa=%s tx=%s (nonce EOA инвалидирован)" % (addr[:10], h))
            return
        status, gas_usd = res[0], res[1]
        pos = (" blk=%s idx=%s" % (res[2], res[3])) if len(res) >= 4 and res[2] is not None else ""
        won = res[4] if len(res) >= 5 else None
        volley_gas_add(gas_usd)
        if board and status == 1 and won is not True:
            # холостая проба доски (или неудачная попытка, съеденная catch): приза нет.
            # Молча — таких строк в каскаде будут тысячи.
            self.stats["board_noop"] = self.stats.get("board_noop", 0) + 1
            return
        if status == 1:
            self.stats["wins"] += 1
            mark_recent_send(mid, borrower)               # жертва взята — глушим реактивный дубль
            self._set_cooldown(feed, "probe", proven=True)   # #46
            if feed:
                with self._lock:
                    stop = self._windows.pop(feed, None)
                if stop is not None:
                    stop.set()
            log.warning("SPECFIRE WIN!!! [volley %s] %s/%s debt=$%.0fk tx=%s gas=$%.2f%s — залп "
                        "взял предочередь (окна на паузе %.0fс)",
                        addr[:10], mid[:10], borrower[:10], debt_usd / 1e3, h, gas_usd, pos,
                        SPEC_FIRE_WIN_COOLDOWN_SEC)
        else:
            self._log("SPECFIRE volley revert (healthy) eoa=%s tx=%s gas=$%.3f%s" % (
                addr[:10], h, gas_usd, pos))

    def _window_loop(self, feed: str, direction: str, stop: threading.Event):
        dev = self.dev_by.get(feed, 0.005)
        _thr_uni = dev * SPEC_FIRE_THRESHOLD
        thr, _det_d = self._det_thr(feed, direction, _thr_uni)
        if thr < _thr_uni:                       # детонатор связал порог — окно близости
            self.stats.setdefault("_det_win_ts::%s" % feed, []).append(self._now())
            self.stats["det_windows"] = self.stats.get("det_windows", 0) + 1
            self._log("SPECFIRE ДЕТОНАТОР feed=%s: порог огня %.3f%% (жир в %.3f%% от флипа; "
                      "универсальный %.3f%%)" % (feed, thr * 100.0,
                                                 (_det_d or 0.0) * 100.0, _thr_uni * 100.0))
        # ГЕЙТ ИСКЛЮЧЕНИЯ — НА АРМЕ ОКНА (kelbic 26.08): детонатор снимает малый кап только
        # если ПРИЗ его цели >= SPEC_FIRE_DET_PRIZE_USD. Считается один раз и подписывается в
        # close-строку: состояние окна не должно «мерцать» вместе с ценой внутри окна.
        _det_prize = 0.0
        try:
            _dk0 = (getattr(self, "_det_key_by_feed", None) or {}).get(feed)
            if _dk0 and len(_dk0) > 3:
                _det_prize = float(_dk0[3] or 0.0)
        except Exception:                                # noqa: BLE001
            pass
        _det_exempt = bool(thr < _thr_uni and (SPEC_FIRE_DET_PRIZE_USD <= 0
                                               or _det_prize >= SPEC_FIRE_DET_PRIZE_USD))
        _det_state = "det=%s приз=$%.0f кап=%s" % (
            "да" if thr < _thr_uni else "нет", _det_prize,
            "снят" if _det_exempt else "малый")
        _det_next = self._now() + 5.0            # цели дышат — порог перечитывается каждые 5с
        band = dev * SPEC_FIRE_OWED_BAND
        probes = 0
        last_fire = 0.0
        last_hold_log = 0.0
        cache = {}      # (mid, b) -> (probe|None, built_ts): кэш пробы, см. SPEC_FIRE_REBUILD_SEC
        cap_spent: dict = {}   # (mid, b) -> swap_meta: свой резерв живого капа (consume-хук 05.08)
        dead = set()    # LOSS-стоп: цели, разобранные конкурентом/погашенные (bs==0 на пересборке)
        nobuild: dict = {}   # фолбэк (01.08): (mid, b) -> ts, до которого цель не пересобираем
        owed_until = 0.0     # peak-owed: до какого момента транзит «заряжен» (0 = долга нет)
        owed_ret = 0.0       # пиковое |ret| горячей фазы — им меряем reach в долге
        was_raw_hot = False
        gaps: list = []      # B3: пробелы проб горячей фазы (p95 в close-строке — метрика-гейт <4с)
        gap_t0 = None
        last_yield_log = 0.0
        fat_mode = False     # EV-плотность (06.08): жир в досягаемости -> каденс 0.12с, кап 600
        next_board_try = 0.0  # v5 доска: когда снова пробовать положить/переложить план
        _unreadable = 0      # В1: нечитаемые тики подряд (ret_fn=None); K подряд закрывают окно
        # СНИМОК НА АРМЕ ОКНА: приёмка (б) судится ЗДЕСЬ И СЕЙЧАС, и она принадлежит ЭТОМУ
        # окну — параллельное окно каскада не имеет права её загрязнить. Ключ плана на арме
        # ещё неизвестен (доску кладёт тред прогрева), поэтому снимок берётся ПОЛНЫЙ, а ключ
        # выбирается на закрытии — из плана, который опубликовало это самое окно.
        _probe0 = self._probe_snap()
        try:
            while not stop.is_set() and probes < _window_cap(fat_mode, _det_exempt):
                if self._now() >= _det_next:      # детонатор: перечитать близость целей
                    _det_next = self._now() + 5.0
                    thr, _det_d = self._det_thr(feed, direction, _thr_uni)
                pf = self.pending_fire.pop(feed, None)
                if pf is not None and self._now() - pf[3] <= PENDING_FIRE_FRESH_SEC:
                    # A2: handoff от pending-detect — жертва флипнута в ФОРМИРУЕМОМ блоке.
                    # Стреляем вне очереди: без ret-гейта, без интервала, без арбитра (B).
                    # Тот же send-шов (send_spec_fire_probe, единый nonce) — fire-путь не менялся.
                    _pm, _pb, _pd = pf[0], pf[1], pf[2]
                    # ПОДТВЕРЖДЁННЫЙ ТРАНЗИТ — сильнейший сигнал, какой мы умеем видеть, и он
                    # приходит В ТОМ ЧИСЛЕ в окна НИЖЕ порога огня (класс cbXRP: оракул -0.50%
                    # при нашем ret -0.43%) — ровно те, ради которых делался #47. Раньше право
                    # огня здесь висело на fat_mode, который выставляется только в горячей
                    # ветке: детект открыли, а флот в этом блоке оставался нем структурно
                    # (ревью 09.08, CONFIRMED). Откат: SPEC_FIRE_HANDOFF_KEEPALIVE=0.
                    if fat_mode or SPEC_FIRE_HANDOFF_KEEPALIVE:
                        self._engine_fat_keepalive(feed)   # право огня ДО сборки/отправки пробы
                        # Ш29: ЗАЛП ПО ФАКТУ ТРАНЗИТА. Здесь момент ИЗВЕСТЕН (жертва флипнута
                        # в формируемом блоке), и это ровно та точка, где бьёт конкурент:
                        # вскрытие 49834406 показало двадцать его транзакций подряд в призовом
                        # окне [436..455] на НАШЕМ же классе tip, тогда как наши двадцать легли
                        # на 407..426 — на 29 позиций раньше, потому что мы льём ровно, а он
                        # выбрасывает залп за миллисекунды. Порядок важен: право огня СНАЧАЛА,
                        # иначе жетоны некому тратить (armed() ещё ложно).
                        try:
                            eng = self._engine()
                            if eng is not None and SPEC_FIRE_TRANSIT_BURST_ON:
                                eng.transit_burst()
                        except Exception as e:
                            self._log("SPECFIRE залп по транзиту: %s" % _diag(e))
                    try:
                        probe, _bts = cache.get((_pm, _pb), (None, 0.0))
                        if not isinstance(probe, dict):
                            self._release_cap(cap_spent, (_pm, _pb))
                            probe = (self._build_fn or self._build)(_pm, _pb, _pd)
                            if isinstance(probe, dict):
                                cache[(_pm, _pb)] = (probe, self._now())
                        if isinstance(probe, dict):
                            h = (self._send_fn or self._send)(probe["calldata"], probe["gas"])
                            if h is not None:
                                self._consume_cap(cap_spent, (_pm, _pb), probe)
                                probes += 1
                                self.stats["probes"] += 1
                                self.stats["pending_fires"] += 1
                                last_fire = self._now()
                                if gap_t0 is not None:
                                    gaps.append(last_fire - gap_t0)
                                gap_t0 = last_fire
                                self._log("SPECFIRE probe #%d feed=%s %s/%s debt=$%.0fk "
                                          "[pending-handoff] tx=%s" % (
                                              probes, feed, _pm[:10], _pb[:10], _pd / 1e3, h))
                                self._rcpt_dispatch(h, "probe", (_pm, _pb, _pd, feed))
                                if fat_mode:      # тир: залп по подтверждённому флипу (07.08)
                                    # транзит подтверждён в pending -> момент известен: разом
                                    self._volley(probe, _pm, _pb, _pd, feed, simultaneous=True)
                    except Exception as e:
                        self._log("SPECFIRE pending-handoff fail feed=%s: %s" % (feed, type(e).__name__))
                    stop.wait(SPEC_FIRE_POLL_SEC)
                    continue
                r = None
                try:
                    r = self.ret_fn(feed)
                except Exception:
                    pass
                # В1-гард: K нечитаемых тиков ПОДРЯД (нет mid = не знаем состояние целей) —
                # незнание закрывает гард: окно закрывается, а не стреляет вслепую серию.
                if r is None:
                    _unreadable = _unreadable + 1
                    if SPEC_FIRE_V1 and _unreadable >= SPEC_FIRE_V1_UNREADABLE_K:
                        self._log("SPECFIRE V1 feed=%s: %d нечитаемых тиков подряд — окно "
                                  "закрыто гардом (незнание)" % (feed, _unreadable))
                        with self._lock:
                            self._windows.pop(feed, None)
                        stop.set()
                        break
                else:
                    _unreadable = 0
                raw_hot = (r is not None and ((direction == "down" and r <= -thr)
                                              or (direction == "up" and r >= thr)))
                _n = self._now()
                if raw_hot:
                    owed_ret = max(owed_ret, abs(r))
                    owed_until = _n + SPEC_FIRE_OWED_HOLD_SEC
                elif (owed_until > _n and r is not None
                        and ((direction == "down" and r <= -(thr - band))
                             or (direction == "up" and r >= thr - band))):
                    owed_until = _n + SPEC_FIRE_OWED_HOLD_SEC   # серая полоса: долг продлевается
                owed_fire = (SPEC_FIRE_PEAK_OWED and not raw_hot
                             and owed_until > _n and owed_ret > 0.0)
                if was_raw_hot and not raw_hot and owed_fire:
                    self._log("SPECFIRE peak-owed feed=%s: отскок с пика %.2f%% — транзит заряжен, "
                              "огонь ещё %.0fс (полоса %.2f%%)" % (
                                  feed, owed_ret * 100.0, owed_until - _n, (thr - band) * 100.0))
                was_raw_hot = raw_hot
                self._owed[feed] = owed_until if SPEC_FIRE_PEAK_OWED else 0.0
                hot = raw_hot or owed_fire
                _pbd = self.probe_board.get(feed)
                if (_pbd is not None and _n - _pbd[5] > SPEC_FIRE_BOARD_RESTAMP_SEC
                        and self._board_plan_live() is not None):
                    # Потребители (tier-2, ws-handoff) гейтят ВОЗРАСТ доски 10с, а переиздать её
                    # прогрев может не раньше 240с и не может вовсе, пока план армлен под ту же
                    # цель (TTL 870с) — фикс #47 жил ~4% окна (ревью 09.08, CONFIRMED). Пока план
                    # ЖИВ on-chain, проба валидна: обновляем ОТМЕТКУ, без RPC и без пересборки.
                    self.probe_board[feed] = _pbd[:5] + (_n,)
                if SPEC_FIRE_V2_BOARD and _n >= self._board_next_try.get(feed, next_board_try):
                    # доску армим ЗАРАНЕЕ и переармливаем по каденсу (роут протухает так же,
                    # как у обычной пробы). Свой тред: сборка плана не крадёт мс у огня.
                    # #57: расписание живёт в _board_next_try — осечка арма подтянет его к
                    # быстрому ретраю, а не оставит окно без доски на весь каденс 240с.
                    self._board_next_try[feed] = _n + SPEC_FIRE_V2_REARM_SEC
                    threading.Thread(target=self._prearm_board, args=(feed, direction, dev),
                                     daemon=True, name="board-%s" % feed).start()
                if hot and gap_t0 is None:
                    gap_t0 = self._now()               # B3: старт горячей фазы — лаг до первой пробы тоже пробел
                elif not hot:
                    gap_t0 = None
                if SPEC_FIRE_DENSE:                    # вся горячая фаза плотно (гонка плотностей, 31.07)
                    iv = _dense_interval(fat_mode)     # EV-плотность: жир решает каденс (06.08)
                elif probes < SPEC_FIRE_BURST_PROBES:
                    iv = SPEC_FIRE_INTERVAL_SEC
                else:                                  # хвост с джиттером (см. SPEC_FIRE_TAIL_JITTER_SEC)
                    _j = SPEC_FIRE_TAIL_JITTER_SEC
                    iv = max(0.3, SPEC_FIRE_SLOW_INTERVAL_SEC + (random.uniform(-_j, _j) if _j > 0 else 0.0))
                if self.pending_healthy_fn is not None:
                    try:
                        if self.pending_healthy_fn():  # A3: pending жив и детектит — on-chain пробы
                            iv = max(iv, PENDING_KEEPALIVE_SEC)   # в кипэлайв (газ ~7× вниз)
                    except Exception:
                        pass
                if hot and self._now() - last_fire >= iv and not self._gate_open(feed):
                    # фазовый гейт: секунда доказуемо холостая (пуш садится на узел решётки).
                    # Патроны не тратим — когда слот откроется, условие интервала уже выполнено
                    # и проба уйдёт сразу, т.е. бюджет сам стягивается в живые секунды.
                    # #64 (ревью 09.08, CONFIRMED): гейт задумывался как экономия ГАЗА кадансовых
                    # проб главного кошелька, но стоял ВЫШЕ единственной точки права огня в тике,
                    # и потому глушил ПЛОТНОСТЬ: на решётке 30с закрытая фаза 26с, а TTL права
                    # огня 1.5с — стена флота гасла до транзита, включая замеренные ~4% пушей
                    # ВНЕ узла. Право огня выдаём и в закрытую секунду: пробы движка стоят
                    # ~$0.0004 и держатся своими бакетами и полом патрона.
                    if fat_mode and SPEC_FIRE_LATTICE_KEEPALIVE:
                        self._engine_fat_keepalive(feed)
                    self.stats["lattice_skips"] += 1
                    stop.wait(SPEC_FIRE_POLL_SEC)
                    continue
                if hot and self._now() - last_fire >= iv:
                    _eff_r = max(abs(r or 0.0), owed_ret if owed_fire else 0.0)
                    reach = _eff_r + SPEC_FIRE_DIST_MARGIN_DEVS * dev   # в долге меряем по пику
                    _depth = max(SPEC_FIRE_TOPK, SPEC_FIRE_FALLBACK_DEPTH if SPEC_FIRE_BUILD_FALLBACK else 0)
                    tgts, hold_dist, edge = self._top_fat(feed, direction, max_dist=reach, k=_depth)
                    if not SPEC_FIRE_EDGE_SLOT:
                        edge = None
                    if dead:
                        tgts = [t for t in tgts if (t[0], t[1]) not in dead]
                        if edge is not None and (edge[0], edge[1]) in dead:
                            edge = None
                    if not tgts and edge is not None:
                        tgts = [edge]              # весь top-K мёртв, кромка жива — окно держит её
                    _fat_now = _tgts_fat(tgts, bonus_of=self._bonus_of)
                    if _fat_now and not fat_mode:
                        self._log("SPECFIRE ev-density feed=%s: жир $%.0fk в досягаемости — "
                                  "каденс %.2fс, кап %d" % (
                                      feed, max(t[2] for t in tgts) / 1e3,
                                      SPEC_FIRE_FAT_INTERVAL_SEC, SPEC_FIRE_FAT_CAP))
                    fat_mode = _fat_now
                    if fat_mode:
                        self._engine_fat_keepalive(feed)
                    if not tgts:
                        if hold_dist is None:
                            break                              # жир ушёл из набора — окно нам не нужно
                        if self._now() - last_hold_log >= 10.0:   # жир есть, но флип вне досягаемости
                            last_hold_log = self._now()           # движения — держим окно, НЕ жжём бакет
                            self._log("SPECFIRE hold feed=%s: жир вне досягаемости (ближ. dist=%.2f%% > reach=%.2f%%)" % (
                                feed, hold_dist * 100.0, reach * 100.0))
                        stop.wait(SPEC_FIRE_POLL_SEC)
                        continue
                    _t0 = self._now()                  # пакет B: заявка = жир первой ДОСТУПНОЙ цели
                    _avail = [t for t in tgts          # (nobuild-скамейка не претендует — иначе
                              if not (SPEC_FIRE_BUILD_FALLBACK                # чужое окно голодает
                                      and nobuild.get((t[0], t[1]), 0.0) > _t0)]   # по нашей несобираемой)
                    _claim = _avail[0][2] if _avail else tgts[0][2]
                    self._prio[feed] = (_claim, _t0)
                    if not self._prio_ok(feed, _claim):
                        if _t0 - last_yield_log >= 10.0:
                            last_yield_log = _t0
                            self._log("SPECFIRE yield feed=%s: слот у более богатого окна "
                                      "(наш жир $%.0fk)" % (feed, _claim / 1e3))
                        stop.wait(SPEC_FIRE_POLL_SEC)
                        continue
                    # плотность ротируется по top-K как раньше; хвост списка — ТОЛЬКО фолбэк
                    # на небилдящиеся (01.08: топ-цель «нет свопа» не должна монополизировать тик).
                    # edge-слот (06.08): ближайшая-по-dist цель входит в head наравне с жиром
                    head = tgts[:SPEC_FIRE_TOPK]
                    tail = tgts[SPEC_FIRE_TOPK:]
                    if edge is not None and all(t[:2] != edge[:2] for t in head):
                        head = head + [edge]
                        tail = [t for t in tail if t[:2] != edge[:2]]
                    _rot = probes % len(head)
                    order = head[_rot:] + head[:_rot] + tail
                    sent = False
                    for mid, b, d in order:
                        _t = self._now()
                        if SPEC_FIRE_BUILD_FALLBACK and nobuild.get((mid, b), 0.0) > _t:
                            continue                           # на скамейке — пересборка через RETRY_SEC
                        try:
                            probe, built_ts = cache.get((mid, b), (None, 0.0))
                            if probe is None or _t - built_ts >= SPEC_FIRE_REBUILD_SEC:
                                self._release_cap(cap_spent, (mid, b))
                                probe = (self._build_fn or self._build)(mid, b, d)
                                if probe == "gone":   # LOSS-стоп (ревью 31.07): жертву разобрали —
                                    dead.add((mid, b))    # кап не догорает ревертами по мёртвой цели
                                    cache.pop((mid, b), None)
                                    self._clear_board(mid, b, feed, "жертву забрали")   # #94
                                    self._log("SPECFIRE loss-stop feed=%s %s/%s: позиция разобрана "
                                              "(конкурент/погашение) — цель снята" % (feed, mid[:10], b[:10]))
                                    continue
                                cache[(mid, b)] = (probe, self._now())
                                if isinstance(probe, dict):
                                    # доска проб (A1 ярус-2): pending-цикл дергает eth_call
                                    # ЭТОЙ пробы по формируемому блоку — та же семантика
                                    self.probe_board[feed] = (mid, b, d, probe["calldata"],
                                                              probe["gas"], self._now())
                                    self._note_plan_key(feed, mid, b)  # блокер C р-6
                            if probe is not None:
                                h = (self._send_fn or self._send)(probe["calldata"], probe["gas"])
                                if h is not None:
                                    self._consume_cap(cap_spent, (mid, b), probe)
                                    probes += 1
                                    self.stats["probes"] += 1
                                    last_fire = self._now()
                                    if gap_t0 is not None:
                                        gaps.append(last_fire - gap_t0)
                                    gap_t0 = last_fire
                                    _om = ""
                                    if owed_fire:              # would-have-fired: старая политика молчала бы
                                        self.stats["owed_probes"] += 1
                                        _om = " [owed пик=%.2f%% ещё %.0fс]" % (
                                            owed_ret * 100.0, max(0.0, owed_until - self._now()))
                                    if edge is not None and (mid, b) == (edge[0], edge[1]):
                                        _om += " [edge]"       # проба edge-слота (кромка по dist)
                                    self._log("SPECFIRE probe #%d feed=%s %s/%s debt=$%.0fk ret=%.4f%%%s tx=%s" % (
                                        probes, feed, mid[:10], b[:10], d / 1e3, (r or 0) * 100.0, _om, h))
                                    self._rcpt_dispatch(h, "probe", (mid, b, d, feed))
                                    if fat_mode:  # тир: жир И каскад -> залп той же пробой (07.08)
                                        self._volley(probe, mid, b, d, feed)
                                sent = True                    # слот тика израсходован отправкой
                                break
                            nobuild[(mid, b)] = self._now() + SPEC_FIRE_NOBUILD_RETRY_SEC
                            self._log("SPECFIRE probe skip feed=%s %s/%s: нет свопа (роут/prearm)%s" % (
                                feed, mid[:10], b[:10],
                                " — фолбэк к следующей цели" if SPEC_FIRE_BUILD_FALLBACK else ""))
                            if not SPEC_FIRE_BUILD_FALLBACK:
                                break                          # прежнее поведение: тик сгорает
                        except Exception as e:
                            self._log("SPECFIRE probe fail feed=%s: %s" % (feed, type(e).__name__))
                            stop.wait(1.0)
                            break
                    if not sent:
                        stop.wait(2.0)                         # весь список без свопа — не молотить чтениями
                stop.wait(SPEC_FIRE_POLL_SEC)
        finally:
            self._owed.pop(feed, None)   # окно закрыто — долг не переживает петлю
            self._prio.pop(feed, None)   # заявка на слот снята (пакет B)
            self.probe_board.pop(feed, None)
            # РЕГРЕССИЯ #57 (ревью 09.08, CONFIRMED): расписание арма переехало в словарь
            # ИНСТАНСА и переживало закрытие окна — окна 2..N того же фида в пределах 240с не
            # грелись ВОВСЕ (ни доски, ни probe_board), то есть детект-пути выбрасывали уже
            # пойманный транзит. В каскаде каждый пуш ре-якорит фид, и это ровно окна 2..N.
            # Лишних setPlan это не создаёт: дедуп «свежая и та же цель» стоит в _arm_board.
            self._board_next_try.pop(feed, None)
            _g = sorted(gaps)
            # close-строка: B3-метрика (gap p95 горячей фазы) + кумулятивные счётчики (C5:
            # owed_probes/sticky_windows/pending_fires видны grep'ом без маркеров)
            # #45: отказы пути движка — в ту же close-строку. Невидимый отказ = отказ, который
            # никто не чинит: нога, замолчавшая на полу или без кэша патрона, до этого была
            # неотличима от «окно было пустым».
            try:
                from chain.execute import (volley_probe_skips, volley_maxfee_muted,
                                            volley_budget_skips, volley_pacer_stats)
                _fs, _us = volley_probe_skips()
                _mm = len(volley_maxfee_muted())
                # #132: немота ПО БЮДЖЕТУ тира — отдельное число. До этого отказ был немым и
                # тонул в skipped_dry вместе со «склад пуст»; в каскаде (всплеск базы) он
                # приходит первым и гасит половину флота.
                _rs, _ifs = volley_budget_skips()
                # #136: пейсер+spill рассылки. pacer_dry (нет токенов, спилл без сети) и
                # transport_reject («over rate limit») РАЗДЕЛЬНО — без числа немота эндпоинта
                # неотличима от «склад пуст», ровно как бюджетная (#132).
                _pdry, _pspill, _prej = volley_pacer_stats()
                # бёрст-в-щель: отправки ИЗ РЕЗЕРВА ведра — приёмка пакета в той же строке
                from chain.execute import pacer_urgent_stats
                _purg = pacer_urgent_stats()
            except Exception:
                _fs = _us = _mm = -1
                _rs = _ifs = -1
                _pdry = _pspill = {}
                _prej = {}          # 20.08: пер-канальный словарь (был суммарный int)
                _purg = {}
            if _mm > 0 and self._alert is not None:
                # У2 (решение kelbic 09.08): немота ног по комиссии = состояние, которое
                # само не рассосётся (долив или ручка MAXFEE_RESERVE_MULT) и которое иначе
                # читается как «не было целей». Антифлуд держит Alerter по ключу.
                self._alert("\U0001F507 флот: %d ног немы ПО КОМИССИИ (резерв gas x maxFee "
                            "съел патрон) — долив ноги или MAXFEE_RESERVE_MULT" % _mm,
                            "leg-maxfee-mute")
            _eng = getattr(self, "_fire_engine", None)
            _es = dict(getattr(_eng, "stats", {}) or {}) if _eng is not None else {}
            _cs = dict(getattr(getattr(_eng, "_collector", None), "stats", {}) or {}) if _eng else {}
            # #110: индекс — В ЗАКРЫВАЮЩЕЙ СТРОКЕ ОКНА. Приёмка окна читается вместе с
            # состоянием источника правды: протухший индекс делает «probes=N, wins=0»
            # непроверяемым утверждением, и это обязано быть видно в той же строке.
            try:
                from chain import chain_index as _ci
                _ix = _ci.get_index()
                _is = _ix.snapshot() if _ix is not None else "НЕ ПОДНЯТ"
            except Exception:
                _is = "?"
            # ПОЗИЦИИ ЗА ЭТО ОКНО (р-3): критерий (б) читается из `окно_позиции=`, а не из
            # `stats=` (там пожизненный итог, который умеет только расти). КЛЮЧ — план,
            # который опубликовало ЭТО окно (блокер C р-6): ярлык фида в бою ставит последний
            # тикнувший keepalive, и по нему приёмка (б) меряла чужие пробы.
            _wkey = (getattr(self, "_plan_key_by_feed", None) or {}).pop(feed, None)
            # НЕЗНАНИЕ ЗАКРЫВАЕТ ГАРД (блокер B2 р-7): без ключа плана окно не смеет печатать
            # ЧИСЛО — прежде оно печатало дельту кумулятива процесса как свою приёмку.
            try:
                _pw = self._probe_window_report(_probe0, _wkey)
            except Exception as _e:
                # УЧЁТ НЕ РОНЯЕТ ДАЖЕ СТРОКУ (правило р-7). Этот блок стоит в `finally` петли
                # окна: бросок измерителя уносил бы ВСЮ закрывающую строку и убивал тред с
                # трейсбеком — то есть отказ учёта делал бы невидимым и сам отказ, и приёмку
                # окна разом. Печатаем причину В ПОЛЕ и идём дальше.
                _pw = "УЧЁТ ПОЗИЦИЙ УПАЛ: %s: %s" % (type(_e).__name__, _e)
            _mdr = sorted(self.stats.get("match_delta_ring") or [])
            _md_str = ("p50=%+d/p90=%+d/n=%d" % (_mdr[len(_mdr)//2], _mdr[int(len(_mdr)*0.9)],
                                                 len(_mdr))) if _mdr else "—"
            # П.3: наблюдаемость коллектора окна — глубина очереди, переполнения, латентность
            _rl = sorted(self.stats.get("rcpt_lat_ring") or [])
            _rcpt_s = "%s q=%d overflow=%d lat=%s/%s" % (
                SPEC_FIRE_RCPT_MODE,
                getattr(self, "_rcpt_col", None).pending() if getattr(self, "_rcpt_col", None) else 0,
                self.stats.get("collector_overflow", 0),
                ("%.1fс" % _rl[len(_rl) // 2]) if _rl else "—",
                ("%.1fс" % _rl[int(len(_rl) * 0.9)]) if _rl else "—")
            # МЕТРИКА ПОЗИЦИИ Г-ЗВЕНА (п.2 ревьюера 26.08): «наш первый idx − транзит» —
            # ГЛАВНАЯ цифра звена Г, рядом с плотностью чужих в полосе. Цель +1..+5; анкер
            # 50471608: наши +12..+20 при конкурентах +1..+11 (они снимают приз раньше нас
            # на ~10 позиций ≈ 100-200мс — ровно наш разрыв detect→prep).
            _pos_s = "—"
            try:
                _nd = sorted(self.stats.get("nearest_delta_ring") or [])
                _nn = self.stats.get("nearest_n", 0)
                if _nd:
                    _fs_avg = (self.stats.get("nearest_foreign_sum", 0) / _nn) if _nn else 0.0
                    _in_target = 100.0 * sum(1 for x in _nd if 1 <= x <= 5) / len(_nd)
                    _pos_s = "первый_delta p50=%+d p90=%+d чужих_между_ср=%.1f в_цели(+1..+5)=%.0f%% n=%d" % (
                        _nd[len(_nd) // 2], _nd[int(len(_nd) * 0.9)], _fs_avg, _in_target, len(_nd))
            except Exception:                                # noqa: BLE001
                pass
            # ПРИБОР КАДЕНСА (26.08): ритм ОТПРАВОК ДВИЖКА — «стоим в окне» или «стоим в
            # СУБ-БЛОКЕ». Цель ≤0.2с (суб-блок Base); 0.9с = пол-блока = +80-180 позиций.
            _cad = "—"
            try:
                _eng = getattr(self, "_fire_engine", None)
                _gr = sorted((_eng.stats.get("send_gap_ring") or [])) if _eng else []
                if _gr:
                    _cad = "p50=%.2fс p90=%.2fс n=%d доля≤0.2с=%.0f%%" % (
                        _gr[len(_gr) // 2], _gr[int(len(_gr) * 0.9)], len(_gr),
                        100.0 * sum(1 for x in _gr if x <= 0.2) / len(_gr))
            except Exception:                                # noqa: BLE001
                pass
            # П.2: пер-тирная немота/огонь в строке окна
            try:
                from chain.execute import volley_tier_stats as _vts
                _t = _vts()
                _tier_s = "a_mute=%d b_mute=%d a_fired=%d b_esc_skips=%d" % (
                    _t["a_mute"], _t["b_mute"], _t["a_fired"], _t["b_esc_skips"])
            except Exception:                            # noqa: BLE001
                _tier_s = "—"
            self._log("SPECFIRE window close feed=%s probes=%d gap_p95=%s det[%s] позиция[%s] каденс[%s] rcpt=%s tiers[%s] "
                      "patron_floor_skips=%d patron_unknown_skips=%d leg_maxfee_mute=%d "
                      "budget_reserve_skips=%d budget_inflight_skips=%d "
                      # 20.08: все три — ПО КАНАЛАМ (url|ip). transport_reject был суммарным
                      # int; с двумя egress-адресами суммарное число не отвечает на вопрос
                      # «умер адрес или режет секвенсер», а именно он теперь и стоит.
                      "pacer_dry=%s spill_sent=%s transport_reject=%s urgent_sent=%s match_delta=%s "
                      "class_between_slots=%s low_density_blocks=%s "
                      "engine=%s collector=%s index=%s план_окна=%s окно_позиции=%s stats=%s" % (
                          feed, probes,
                          ("%.1fс" % _g[max(0, int(len(_g) * 0.95) - 1)]) if _g else "—",
                          _det_state, _pos_s, _cad, _rcpt_s, _tier_s,
                          _fs, _us, _mm, _rs, _ifs, _pdry or "—", _pspill or "—", _prej or "—",
                          _purg or "—", _md_str,
                          self.stats.get("class_between_slots", 0),
                          self.stats.get("low_density_blocks", 0),
                          _es or "—", _cs or "—", _is,
                          ("%s/%s" % (_wkey[0][:10], _wkey[1][:10])) if _wkey else "НЕТ",
                          _pw, self.stats))

    def handle_event(self, ev: dict):
        try:
            kind = ev.get("event")
            feed = (ev.get("feed") or "").upper()
            if kind == "arm":
                direction = ev.get("dir") or "down"
                if self._cooldown_active(feed):            # WIN-пауза (#46: по умолчанию пер-фид)
                    return None
                best, hold_dist, _ = self._top_fat(feed, direction, max_dist=SPEC_FIRE_ARM_MAX_DIST)
                if not best:
                    if hold_dist is not None:              # жир есть, но заведомо вне окна — не палим
                        _n = self._now()                   # ни петлю, ни ончейн-паттерн
                        if _n - self._armskip_ts.get(feed, -1e9) >= 300.0:
                            self._armskip_ts[feed] = _n
                            self._log("SPECFIRE arm-skip feed=%s: ближ. жир dist=%.2f%% > потолок %.1f%%" % (
                                feed, hold_dist * 100.0, SPEC_FIRE_ARM_MAX_DIST * 100.0))
                    return None                            # окна без (досягаемого) жира не запускают петлю
                with self._lock:
                    old = self._windows.pop(feed, None)
                    if old is not None:
                        old.set()
                    stop = threading.Event()
                    self._windows[feed] = stop
                    self.stats["windows_armed"] += 1
                _n = self._now()                           # каскад-детект (гибрид): армы И факты
                self._arm_ts = [t for t in self._arm_ts if _n - t < 3600.0] + [_n]
                if len(self._arm_ts) >= SPEC_FIRE_CASCADE_WINDOWS:
                    if _facts_fresh():
                        from chain.execute import specfire_cascade_boost
                        if specfire_cascade_boost() and _n - self._armskip_ts.get("_boost", -1e9) >= 300.0:
                            self._armskip_ts["_boost"] = _n
                            self._log("SPECFIRE каскад-детект: %d окон/час + факт-флаг — бакет поднят "
                                      "до каскадного (TTL 1ч, продлевается армами)" % len(self._arm_ts))
                    elif _n - self._armskip_ts.get("_nofacts", -1e9) >= 300.0:
                        self._armskip_ts["_nofacts"] = _n
                        self._log("SPECFIRE каскад-армы (%d/час) БЕЗ факт-флага — бустер молчит "
                                  "(fail-closed, штатный бакет)" % len(self._arm_ts))
                self._win_birth[feed] = self._now()   # В1: рождение серии (перезапись = чистка)
                self._win_pushes[feed] = 0
                self._log("SPECFIRE LIVE window feed=%s dir=%s — жир на прицеле, огонь при |ret|>=%.3f%%" % (
                    feed, direction, self.dev_by.get(feed, 0.005) * SPEC_FIRE_THRESHOLD * 100.0))
                threading.Thread(target=self._window_loop, args=(feed, direction, stop),
                                 daemon=True, name="specfire-%s" % feed).start()
            elif kind in ("confirmed", "push", "disarm", "falsepos", "stale"):
                if kind in ("confirmed", "push"):
                    self.note_push(feed, updated_at=ev.get("updated_at"))
                    # решётка OCR: метка севшего апдейта — по времени ОРАКУЛА (#49)
                    # В1: пуш сел — окно живёт СЕРИЮ, а не закрывается по первому транзиту.
                    # Гарды: жёсткий TTL серии + кап пушей; нечитаемость закрывает ПЕТЛЯ.
                    if SPEC_FIRE_V1 and feed in self._windows:
                        _birth = self._win_birth.get(feed, 0.0)
                        _pushes = self._win_pushes.get(feed, 0) + 1
                        _age = self._now() - _birth
                        if _birth > 0.0 and _age < SPEC_FIRE_V1_SERIES_TTL_SEC \
                                and _pushes < SPEC_FIRE_V1_MAX_PUSHES:
                            self._win_pushes[feed] = _pushes
                            self.stats["v1_series_pushes"] = self.stats.get("v1_series_pushes", 0) + 1
                            self._log("SPECFIRE V1 серия feed=%s: пуш №%d сел — окно живёт "
                                      "(возраст %.0fс из %.0fс)" % (feed, _pushes, _age,
                                                                    SPEC_FIRE_V1_SERIES_TTL_SEC))
                            return None
                        self._log("SPECFIRE V1 серия feed=%s ИСЧЕРПАНА (возраст %.0fс, пушей %d)"
                                  % (feed, _age, _pushes))
                if (SPEC_FIRE_PEAK_OWED and kind in ("disarm", "falsepos")
                        and self._owed.get(feed, 0.0) > self._now()
                        and feed in self._windows):
                    # sticky: транзит заряжен на пике — отскок предикта окно не убивает;
                    # confirmed/push (транзит сел) и stale (фид умер) закрывают как раньше
                    self.stats["sticky_windows"] += 1
                    self._log("SPECFIRE sticky feed=%s: %s при заряженном транзите — окно живёт "
                              "ещё %.0fс" % (feed, kind, self._owed[feed] - self._now()))
                    return None
                with self._lock:
                    stop = self._windows.pop(feed, None)
                if stop is not None:
                    stop.set()
        except Exception:
            log.exception("spec-fire live: событие %s упало (слой изолирован)", ev.get("event"))
        return None
